INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2585d9d7-0e6c-51da-a5e3-6821f01b0227','e1000001-0000-4000-8000-000000000011','step',1,'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a975319f-3ca6-595b-82f0-73637f95b28a','e1000001-0000-4000-8000-000000000011','step',2,'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c40b0ef-1785-55c5-b588-3bbd97be50f4','e1000001-0000-4000-8000-000000000011','step',3,'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8136085e-7437-57b5-952a-aefeeaa2f0e5','e1000001-0000-4000-8000-000000000011','step',4,'Slowly begin to bring the bar back to starting position as your breathe in.','en','source:free_exercise_db');
