INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f26e3b93-87da-5335-837a-f3e7eba92651','e1000001-0000-4000-8000-000000000011','mistake',3,'Half reps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8891bdb9-dfdb-5c6a-b9e6-867431c0f3f6','e1000001-0000-4000-8000-000000000004','step',1,'Stand in front of a loaded barbell.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('93e0b189-134f-5227-a202-7ef859d4d95e','e1000001-0000-4000-8000-000000000004','step',2,'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('af88d26c-1b78-5502-9c7d-44cdd304349d','e1000001-0000-4000-8000-000000000004','step',3,'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9d846536-1df2-5a12-99ad-f43f7dcfe624','e1000001-0000-4000-8000-000000000004','step',4,'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2dbe1b74-a909-58c3-9029-2ae4ef8a7a94','e1000001-0000-4000-8000-000000000004','step',5,'Perform the amount of repetitions prescribed in the program.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6505db1f-d8f0-568c-9493-f8f272a3db98','e1000001-0000-4000-8000-000000000004','cue',1,'Bar over mid-foot, shins close','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b53aee4b-a146-503a-96a5-6a6070eedbdc','e1000001-0000-4000-8000-000000000004','cue',2,'Pull the slack out of the bar before lifting','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('28050992-10cd-52d2-b682-5373a70521a2','e1000001-0000-4000-8000-000000000004','cue',3,'Push the floor away, then drive hips through','en','ai_authored:specific');
