INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('020897ef-7492-550c-8f27-3e12e3fb7813','e1000001-0000-4000-8000-00000000001a','step',1,'Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b17f5cf9-8571-5487-99ef-d635bbeb7447','e1000001-0000-4000-8000-00000000001a','step',2,'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5ac11796-14d6-5204-9f1b-cf3a857ef47c','e1000001-0000-4000-8000-00000000001a','step',3,'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('28c5d1b7-cc08-5b09-b0f1-c0ce9bac6dc4','e1000001-0000-4000-8000-00000000001a','cue',1,'Upper back on bench edge, bar padded over hips','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a2d427e8-b152-5a2d-9cc1-3a45af0e7771','e1000001-0000-4000-8000-00000000001a','cue',2,'Tuck chin and ribs down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f55ef57e-ff7f-5077-a0e6-affa7e9c1e60','e1000001-0000-4000-8000-00000000001a','cue',3,'Squeeze glutes hard at the top','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4d2e080c-0cf3-5369-9101-286a8f002068','e1000001-0000-4000-8000-00000000001a','mistake',1,'Arching the lower back at the top','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59c650b5-22b9-57ca-8a55-e5126889bf93','e1000001-0000-4000-8000-00000000001a','mistake',2,'Feet too far/close','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('43b8e303-1001-5ec6-a809-0bbeec7d8cd6','e1000001-0000-4000-8000-00000000001a','mistake',3,'Pushing through toes','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cb753d2d-da1a-5100-97d2-e29406ff3827','e1000001-0000-4000-8000-000000000001','step',1,'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f31db872-acbe-5030-9341-455cb05d7ba4','e1000001-0000-4000-8000-000000000001','step',2,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('455a1fab-9070-5aaf-920f-4d26bf91d20f','e1000001-0000-4000-8000-000000000001','step',3,'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52097e66-34b3-56ca-8d36-c04ebeba72ce','e1000001-0000-4000-8000-000000000001','step',4,'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dba5bf04-e135-5691-80c8-cac2a825783c','e1000001-0000-4000-8000-000000000001','step',5,'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2e0901ef-7a57-525d-bc5a-3288b403a2c9','e1000001-0000-4000-8000-000000000001','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea3c0c56-5bdc-588c-9ade-f0df149a52d0','e1000001-0000-4000-8000-000000000001','cue',1,'Bar on upper traps, hands just outside shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07eae4cf-fc89-52b1-9a71-b55fe52d5fe4','e1000001-0000-4000-8000-000000000001','cue',2,'Break at hips and knees together','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37bfe616-ddd0-5ed2-a1a8-859219ee8af0','e1000001-0000-4000-8000-000000000001','cue',3,'Squat to at least parallel if mobility allows','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b2d1d43-cc0b-5b8f-91f9-63e0c29e3d12','e1000001-0000-4000-8000-000000000001','mistake',1,'Good-morning squat (hips rise first)','en','ai_authored:specific');
