INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('32d6388b-118e-5c63-a6de-4fc43ff69df3','e1000001-0000-4000-8000-000000000024','mistake',2,'Bouncing in the saddle','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9a9691f4-86c7-5846-8ac0-87985ac4dafa','e1000001-0000-4000-8000-000000000024','mistake',3,'Too much resistance early','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('108202a8-bb84-50c0-aef3-794128ae057c','e1000001-0000-4000-8000-00000000001d','step',1,'Start on hands and knees, hands under shoulders and knees under hips.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6eacbbda-ecff-5e46-ac7e-6ef607e40d0d','e1000001-0000-4000-8000-00000000001d','step',2,'Brace your core and keep your back flat.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dce86a2a-cae0-5193-a8d4-9cac3ed8b8cd','e1000001-0000-4000-8000-00000000001d','step',3,'Extend one arm forward and the opposite leg back until both are in line with your body.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a4dc6e0-10a4-5728-ae6d-09a3c989ca42','e1000001-0000-4000-8000-00000000001d','step',4,'Hold for 2 seconds, then return with control.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c0eaa2ee-4817-5a02-87da-430810c9fbec','e1000001-0000-4000-8000-00000000001d','step',5,'Repeat on the other side.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('71fff1be-f9ac-5bc7-ae84-f4a380c08da7','e1000001-0000-4000-8000-00000000001d','cue',1,'Keep hips level','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1118e507-8197-5a9b-baf3-58b339c0b602','e1000001-0000-4000-8000-00000000001d','cue',2,'Reach long rather than high','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e20a63dd-4212-5ffa-869e-84cba19740dc','e1000001-0000-4000-8000-00000000001d','cue',3,'Move slowly','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f24a4f9b-cc98-5dcd-8985-8121c1d8c7f7','e1000001-0000-4000-8000-00000000001d','mistake',1,'Arching the lower back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1227c63d-0a3b-5ad6-b4d3-7960e10739ba','e1000001-0000-4000-8000-00000000001d','mistake',2,'Rotating the hips','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0cd6b1cb-838f-5f95-9aa4-a932d3acfa4b','e1000001-0000-4000-8000-00000000001d','mistake',3,'Rushing the reps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e013f05e-f943-5de6-b4c1-e8c3b35d71a9','e1000001-0000-4000-8000-000000000014','step',1,'Begin standing with your feet shoulder width apart and your hands on your hips.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9202a7ac-109e-5cb6-bcf5-94b2187e1efb','e1000001-0000-4000-8000-000000000014','step',2,'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4059f56-5441-541c-b121-4c943915d506','e1000001-0000-4000-8000-000000000014','step',3,'Drive through the heel of your lead foot and extend both knees to raise yourself back up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2ad17e40-5129-5068-ac28-79231fdb9b4f','e1000001-0000-4000-8000-000000000014','step',4,'Step forward with your rear foot, repeating the lunge on the opposite leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aaac7698-c8c2-5a2c-8b10-33163f80085a','e1000001-0000-4000-8000-000000000014','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('66599a1a-88e2-59ba-a7bd-e5a9cfa28afd','e1000001-0000-4000-8000-000000000014','cue',2,'Lower the back knee straight down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a92cb51a-8541-5f89-a3ee-a914c1d357c1','e1000001-0000-4000-8000-000000000014','cue',3,'Keep your torso tall','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f52adc60-dbb3-5953-93ee-6c285bd11fde','e1000001-0000-4000-8000-000000000014','mistake',1,'Front knee collapsing inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('823c285e-a5df-5e4f-a2e1-4d73789a76fa','e1000001-0000-4000-8000-000000000014','mistake',2,'Pushing off the back foot instead of the front heel','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3ae04d0f-6b5c-5a01-a998-7b37eec12cdf','e1000001-0000-4000-8000-000000000014','mistake',3,'Short, choppy steps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c9bb238-6887-5592-9d58-d861d9295c01','e1000001-0000-4000-8000-000000000022','step',1,'To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc653fbe-09b2-5a21-891c-91ac2cde017a','e1000001-0000-4000-8000-000000000022','step',2,'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8af5d927-33ad-5906-abaf-ef4177e4c251','e1000001-0000-4000-8000-000000000022','step',3,'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('835ed159-51c8-55d1-8775-391ae2ff1d79','e1000001-0000-4000-8000-000000000022','step',4,'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('84966a51-478f-5db2-b33c-b5851ca2106f','e1000001-0000-4000-8000-000000000022','step',5,'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('13d7d98e-2864-5ea1-8336-d74e85fe12e7','e1000001-0000-4000-8000-000000000022','cue',1,'Keep a slight bend in the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('05ecb9e5-7f53-5f88-aa7e-062954ae12ba','e1000001-0000-4000-8000-000000000022','cue',2,'Move in a wide arc','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f7334bb6-e822-5cf1-a887-933cdbf82d75','e1000001-0000-4000-8000-000000000022','cue',3,'Squeeze the chest at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('05bf6ca6-309b-5464-9943-06a0d5e8a27f','e1000001-0000-4000-8000-000000000022','mistake',1,'Bending elbows into a press','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b099a0b5-b775-5c4e-9105-eb94960f3145','e1000001-0000-4000-8000-000000000022','mistake',2,'Going too deep and straining the shoulder','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('454ff47c-4b45-5f73-83fe-4e788ecfadda','e1000001-0000-4000-8000-000000000022','mistake',3,'Using too much weight','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('572139bd-957f-53b3-942f-73cabb21f0dc','e1000001-0000-4000-8000-00000000001c','step',1,'Begin lying on your back with your hands extended above you toward the ceiling.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('425f9f97-166a-5e3d-832f-89cf981b8d8c','e1000001-0000-4000-8000-00000000001c','step',2,'Bring your feet, knees, and hips up to 90 degrees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6252ebd3-9d90-5ab9-b84e-3e89a95d33e7','e1000001-0000-4000-8000-00000000001c','step',3,'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position. Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c762d419-84ac-5a0c-aeee-121cab1c5a54','e1000001-0000-4000-8000-00000000001c','step',4,'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cfd06acb-d4b3-5915-8fab-045a87417fae','e1000001-0000-4000-8000-00000000001c','step',5,'Stay tight and return the working leg to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fae5da95-bcd5-5e4f-b899-ba5a83ea0763','e1000001-0000-4000-8000-00000000001c','step',6,'Repeat on the opposite side, alternating until the set is complete.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea7ddbb0-8f32-5e28-a63e-51efa8f005af','e1000001-0000-4000-8000-00000000001c','cue',1,'Press lower back into the floor','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a95362c5-7fb6-54a8-baee-b01b7d41cabc','e1000001-0000-4000-8000-00000000001c','cue',2,'Move opposite arm and leg slowly','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d4e6723f-a4d2-516c-9e53-06b5d6231224','e1000001-0000-4000-8000-00000000001c','cue',3,'Exhale as you extend','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6818b6bf-ad95-5212-8817-0488809ef622','e1000001-0000-4000-8000-00000000001c','mistake',1,'Lower back arching off the floor','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bea67395-7e2b-5efa-99bd-956552ef30de','e1000001-0000-4000-8000-00000000001c','mistake',2,'Moving too fast','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('219ec91b-2644-5c3a-8e52-61ee7e61da83','e1000001-0000-4000-8000-00000000001c','mistake',3,'Holding breath','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6e5a9922-d00c-5f2b-8111-50e6d51b0a4c','e1000001-0000-4000-8000-000000000021','step',1,'Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ee4fa11d-dae8-5853-8716-b1eee9f29753','e1000001-0000-4000-8000-000000000021','step',2,'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11d58a78-dd91-5b62-9f90-8eb4f3becac2','e1000001-0000-4000-8000-000000000021','step',3,'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8f7526b1-a870-569d-8382-208df7250b4d','e1000001-0000-4000-8000-000000000021','step',4,'Return your arms back to the starting position as you squeeze your chest muscles and breathe out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('899215e6-f3fa-5ee1-902c-0ab6300c41bb','e1000001-0000-4000-8000-000000000021','step',5,'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4da4e62d-5abf-5d53-a3d2-08629a78ecf2','e1000001-0000-4000-8000-000000000021','cue',1,'Keep a slight bend in the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('04bbbc91-07e1-540f-a7cb-325ed2ce8852','e1000001-0000-4000-8000-000000000021','cue',2,'Move in a wide arc','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6c231430-0425-56f5-b28d-953b205f3f6b','e1000001-0000-4000-8000-000000000021','cue',3,'Squeeze the chest at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2504de17-974b-5483-bf32-5eebb139a051','e1000001-0000-4000-8000-000000000021','mistake',1,'Bending elbows into a press','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6d37a332-e9b8-5d81-b911-99e73d730f6b','e1000001-0000-4000-8000-000000000021','mistake',2,'Going too deep and straining the shoulder','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5fd87cc0-22a7-5006-a7fc-076776b378e5','e1000001-0000-4000-8000-000000000021','mistake',3,'Using too much weight','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b6360c9a-4d1a-5707-8012-ea9641ad3781','e1000001-0000-4000-8000-000000000009','step',1,'While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a9e44a24-bec0-513f-9555-5f20027d3ac1','e1000001-0000-4000-8000-000000000009','step',2,'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d3c40ba6-e7d3-5654-9b18-ac410b692274','e1000001-0000-4000-8000-000000000009','step',3,'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('205a1ef5-67eb-59df-bf88-7c2d466e349c','e1000001-0000-4000-8000-000000000009','step',4,'Now, exhale and push the dumbbells upward until they touch at the top.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f2c755a1-b623-5bff-b0fb-373064664a36','e1000001-0000-4000-8000-000000000009','step',5,'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c11af291-f6d1-5acf-bcda-085d28a53d36','e1000001-0000-4000-8000-000000000009','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('27edc69d-46f8-592d-9554-246d2378f8dc','e1000001-0000-4000-8000-000000000009','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('357faa26-5fe8-5ba6-82dc-ed1debc20271','e1000001-0000-4000-8000-000000000009','cue',2,'Press in a straight line overhead','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9888c822-fb29-59f7-9b6e-66a1b1568a41','e1000001-0000-4000-8000-000000000009','cue',3,'Finish with biceps near the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e4a304ff-e856-5263-96d4-237dc263746f','e1000001-0000-4000-8000-000000000009','mistake',1,'Excessive lower-back arch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('34945f09-6eb2-5af9-9063-716198bc86ee','e1000001-0000-4000-8000-000000000009','mistake',2,'Pressing forward instead of up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69197c1d-75ac-5781-803d-46f7debfb6b1','e1000001-0000-4000-8000-000000000009','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3311b397-87b3-5bbf-a3d2-e40fc3f60f0c','e1000001-0000-4000-8000-000000000013','step',1,'Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8dc4cc2a-9d64-544e-989b-c0e2df239d22','e1000001-0000-4000-8000-000000000013','step',2,'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dae08255-e8cc-5a76-9fc9-1ef32f0b2971','e1000001-0000-4000-8000-000000000013','step',3,'Lift the bar back to the starting position by extending the elbow and exhaling.','en','source:free_exercise_db');
