INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9288a59c-f240-5684-b0e2-22011d6bd3f4','e1000001-0000-4000-8000-000000000010','step',1,'Set a rope attachment on a cable at upper-chest to face height.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a43a7138-a5c1-50b7-a136-fb251b5851e6','e1000001-0000-4000-8000-000000000010','step',2,'Grip the rope with palms facing in and step back until arms are straight.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e2072801-ed5f-5283-80bc-795f54f1d867','e1000001-0000-4000-8000-000000000010','step',3,'Pull the rope toward your face, elbows high and wide.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ca25741-c7e2-5cbd-9f9d-9f71cfe4e37f','e1000001-0000-4000-8000-000000000010','step',4,'Squeeze your shoulder blades, then return under control.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4b641488-8caf-513e-b107-dd6bef97e32c','e1000001-0000-4000-8000-000000000010','cue',1,'Rope at upper-chest/face height','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('21ef32ba-49a0-5a39-be3b-ce12bbb3986d','e1000001-0000-4000-8000-000000000010','cue',2,'Pull toward your eyes, elbows high','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d1aaea54-0ef7-57a3-9b47-1e3a59b72915','e1000001-0000-4000-8000-000000000010','cue',3,'Rotate hands back at the end','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe34830b-bf85-5155-ad89-becbb14735cb','e1000001-0000-4000-8000-000000000010','mistake',1,'Pulling to the chin','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('881ffeec-3bf6-52bc-8c1d-10a9ac9c8727','e1000001-0000-4000-8000-000000000010','mistake',2,'Leaning back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f64cba29-043e-5fbf-982f-8874e3514fb5','e1000001-0000-4000-8000-000000000010','mistake',3,'Using too much weight','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fcc22a68-8d78-581e-bccf-fa6b04e632a3','e1000001-0000-4000-8000-00000000001e','step',1,'There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59fca931-49a1-5190-8491-97f21969ea12','e1000001-0000-4000-8000-00000000001e','step',2,'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d5fe8ff-4c32-54a0-8d5d-75d3a86b75bb','e1000001-0000-4000-8000-00000000001e','step',3,'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69ef9392-f548-57c2-aec4-70b0fc6ae54e','e1000001-0000-4000-8000-00000000001e','cue',1,'Grip handles in the centre','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e34c2be6-8705-5d5c-be1c-88a3b1458c2a','e1000001-0000-4000-8000-00000000001e','cue',2,'Stand tall, shoulders down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02de4842-6e65-5953-b174-4378a2ef4eca','e1000001-0000-4000-8000-00000000001e','cue',3,'Walk with short steps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f0182dfa-f51c-5972-b84d-d027e584752c','e1000001-0000-4000-8000-00000000001e','mistake',1,'Leaning','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c34a16be-7559-51f7-b8e5-a3ae64cd217b','e1000001-0000-4000-8000-00000000001e','mistake',2,'Shrugging','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb3544b2-007f-53f6-a342-5afb7e2e89e7','e1000001-0000-4000-8000-00000000001e','mistake',3,'Letting weights swing','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d7f52a0a-c3b6-5f94-89e6-932b70e50462','e1000001-0000-4000-8000-000000000002','step',1,'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f436e815-73f6-5e68-b011-da3089560421','e1000001-0000-4000-8000-000000000002','step',2,'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('515b5312-e0a6-55ac-bfb9-da474471c107','e1000001-0000-4000-8000-000000000002','step',3,'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('558ef22b-4bf9-5018-b6c2-3b380bfeafe1','e1000001-0000-4000-8000-000000000002','step',4,'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dd1b6a1f-db82-5090-9819-8d347f0692ab','e1000001-0000-4000-8000-000000000002','step',5,'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6ec04003-7aa5-5021-aecf-bd449e6b1038','e1000001-0000-4000-8000-000000000002','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d91c2ffc-181f-58c7-a6fa-4f46b459c980','e1000001-0000-4000-8000-000000000002','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c9df31f8-0466-5fa3-8cdf-2288677f3962','e1000001-0000-4000-8000-000000000002','cue',2,'Knees track over your toes','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a86d62b0-54ca-5d77-a4fb-35fb57696387','e1000001-0000-4000-8000-000000000002','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3d68c825-53b3-56b3-b856-09960aa19198','e1000001-0000-4000-8000-000000000002','mistake',1,'Knees caving inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f1d4329-1d49-5e41-9668-7be66aee2682','e1000001-0000-4000-8000-000000000002','mistake',2,'Heels lifting off the floor','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('15029831-2212-5c84-bb7b-7a97630d655b','e1000001-0000-4000-8000-000000000002','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c1f9bdd-7092-5749-9aca-054b04161cdd','e1000001-0000-4000-8000-000000000020','step',1,'Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17d15314-c478-5d22-855c-a8d1576f1186','e1000001-0000-4000-8000-000000000020','step',2,'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff874b5f-8898-51b2-b98d-487c2f1aa540','e1000001-0000-4000-8000-000000000020','step',3,'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('664e0f2b-64f2-5b91-b952-dbf427fae64d','e1000001-0000-4000-8000-000000000020','cue',1,'Hold the weight at your chest, elbows down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4d784b58-1698-50a8-9992-10c37826a135','e1000001-0000-4000-8000-000000000020','cue',2,'Sit between your heels','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('464b5aaa-5b46-56c1-9d06-aba5db72c52b','e1000001-0000-4000-8000-000000000020','cue',3,'Keep chest up','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c57d9871-4130-5ed4-8358-79d34dc51363','e1000001-0000-4000-8000-000000000020','mistake',1,'Rounding forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3468ae92-73ea-5b70-9f14-c3348d183ac5','e1000001-0000-4000-8000-000000000020','mistake',2,'Heels lifting','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('518eed48-a0e7-5e3c-9986-5f8796af10b0','e1000001-0000-4000-8000-000000000020','mistake',3,'Knees caving','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('196eba21-bf10-5210-99ba-c92866b279e4','e1000001-0000-4000-8000-000000000006','step',1,'Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('48067b9e-7a5b-57a5-93e7-136f08942355','e1000001-0000-4000-8000-000000000006','step',2,'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('957ba0d8-8f47-500a-9f59-d1b0994b33c9','e1000001-0000-4000-8000-000000000006','step',3,'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1784ea19-4745-5fc6-b46e-9db606e75845','e1000001-0000-4000-8000-000000000006','step',4,'Lock your arms at the top, hold for a second, and then start slowly lowering the weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e9c1e04e-3c11-5989-b2d9-78b70fc656e2','e1000001-0000-4000-8000-000000000006','step',5,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d425fb36-f7cc-5ea5-9cc9-6cf8c1e5174b','e1000001-0000-4000-8000-000000000006','step',6,'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6511ea62-eff8-5db3-a266-7fbbcbc6fc07','e1000001-0000-4000-8000-000000000006','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9cd492d7-ac21-5506-b877-a7dd11189d01','e1000001-0000-4000-8000-000000000006','cue',2,'Wrists stacked over elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ecb32be3-c029-5bb0-89a2-3e3cf8a40428','e1000001-0000-4000-8000-000000000006','cue',3,'Lower under control to chest level','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('055f50f3-bd96-59b9-b748-bc42cd3f85bb','e1000001-0000-4000-8000-000000000006','mistake',1,'Flaring elbows to 90 degrees','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c8ed20c7-89e0-521a-97c1-4e5e75fc742f','e1000001-0000-4000-8000-000000000006','mistake',2,'Bouncing off the chest','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c3a9d20e-3f1f-5489-b104-817166eba4b4','e1000001-0000-4000-8000-000000000006','mistake',3,'Lifting hips off the bench','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62cdd559-f552-53da-8a5b-1c53baeae7c9','e1000001-0000-4000-8000-000000000018','step',1,'For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ec6ef6d5-0a73-53ef-9ed8-5e1d1c3a051f','e1000001-0000-4000-8000-000000000018','step',2,'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ef8b33a1-194e-5781-a6e7-5755eb869cc4','e1000001-0000-4000-8000-000000000018','step',3,'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('49b95b63-2dc2-5e0d-8f93-9ed3acc64df3','e1000001-0000-4000-8000-000000000018','step',4,'Repeat for the recommended amount of times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d7abcb2-48cd-5ca8-8129-02545ff3240e','e1000001-0000-4000-8000-000000000018','cue',1,'Pause briefly at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e7184f39-6878-51a9-9168-4a31096bb0de','e1000001-0000-4000-8000-000000000018','cue',2,'Control the lowering phase','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('54bc08f0-59da-520d-8b28-53ebc84bd9aa','e1000001-0000-4000-8000-000000000018','cue',3,'Keep hips pressed into the seat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c553598-252b-574e-84ab-5250f3b9110b','e1000001-0000-4000-8000-000000000018','mistake',1,'Swinging the weight up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('65d6e737-b9d3-54af-a25e-12755ce83a7b','e1000001-0000-4000-8000-000000000018','mistake',2,'Locking the knees hard','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d2b9b836-e9d0-57d3-ba56-7aa28d764cf2','e1000001-0000-4000-8000-000000000018','mistake',3,'Lifting hips off the pad','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a07c542e-2fe1-5fb9-9f83-febf18d7eecf','e1000001-0000-4000-8000-000000000016','step',1,'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dfadfe4f-8f31-5c90-86b3-a408bee210b6','e1000001-0000-4000-8000-000000000016','step',2,'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3290e30a-e6f1-5634-be41-f23338e5d6c2','e1000001-0000-4000-8000-000000000016','step',3,'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('95b558d0-6480-5ee5-b625-657064fe8065','e1000001-0000-4000-8000-000000000016','step',4,'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b9d197d1-427d-5363-ae93-e4ab4e14b3fd','e1000001-0000-4000-8000-000000000016','cue',1,'Feet shoulder-width mid-platform','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('feb5b33b-2e5d-56f3-8016-4783e1f364ea','e1000001-0000-4000-8000-000000000016','cue',2,'Lower until knees ~90 degrees','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b40b8f22-3fe6-5ed2-96aa-5bb978b28336','e1000001-0000-4000-8000-000000000016','cue',3,'Keep lower back on the pad','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6c6af9e0-8a0c-55e4-87e0-5cb19ee2cb28','e1000001-0000-4000-8000-000000000016','mistake',1,'Locking knees','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dba90f26-cf9b-54e6-9281-18b4a9e0af03','e1000001-0000-4000-8000-000000000016','mistake',2,'Hips rolling off the pad','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('43dfd235-e0b0-5497-b57f-376b53414101','e1000001-0000-4000-8000-000000000016','mistake',3,'Knees caving','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7930c8a3-0282-558f-9718-12571bdd741b','e1000001-0000-4000-8000-000000000017','step',1,'Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0ff5d104-47d3-57f8-8106-90343c15421d','e1000001-0000-4000-8000-000000000017','step',2,'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3b7630c-925d-565b-bfea-7ad2fafd7bae','e1000001-0000-4000-8000-000000000017','step',3,'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f807885f-03e8-5111-a91f-8f42ef1004f3','e1000001-0000-4000-8000-000000000017','step',4,'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('78409844-ca0d-54a1-8903-50f6fb7923ad','e1000001-0000-4000-8000-000000000017','cue',1,'Keep hips pressed down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0d97e22e-fcc1-5cbc-b1e6-51d9420a6527','e1000001-0000-4000-8000-000000000017','cue',2,'Curl through the full range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c8cf34a-1dbb-5aa4-ad46-dc8e833dc1dd','e1000001-0000-4000-8000-000000000017','cue',3,'Lower slowly','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3bbe90bc-4673-5cfd-b1f0-bc08ed7129c3','e1000001-0000-4000-8000-000000000017','mistake',1,'Hips lifting off the pad','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e87c7517-5b3d-512f-beb8-88edb666f0f5','e1000001-0000-4000-8000-000000000017','mistake',2,'Using momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('df22c410-a2a9-5f91-a19d-624e38b94e3a','e1000001-0000-4000-8000-000000000017','mistake',3,'Partial reps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9fedf25-44ae-5750-9ed4-58f3e996897c','e1000001-0000-4000-8000-00000000000f','step',1,'Choose a flat bench and place a dumbbell on each side of it.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b3639c8f-fb44-5e1d-8878-8aba2edf7ac5','e1000001-0000-4000-8000-00000000000f','step',2,'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bf8011b3-de8e-5d20-b072-27c3d3d45f84','e1000001-0000-4000-8000-00000000000f','step',3,'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position. Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1f201213-4543-5afc-9956-ed96dfb24436','e1000001-0000-4000-8000-00000000000f','step',4,'Lower the resistance straight down to the starting position. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('78459184-90bc-5f33-a295-96f59420ef04','e1000001-0000-4000-8000-00000000000f','step',5,'Repeat the movement for the specified amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0c845e26-4a23-5d69-a0b8-1b08a425c62a','e1000001-0000-4000-8000-00000000000f','step',6,'Switch sides and repeat again with the other arm.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e764f056-35b8-515d-9e68-f12e6dae3c7c','e1000001-0000-4000-8000-00000000000f','cue',1,'Hand and knee on bench, back flat','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('da5c3c70-710a-5f86-baf8-b91eaf5ef9c4','e1000001-0000-4000-8000-00000000000f','cue',2,'Pull elbow toward the hip','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('da66735f-2c18-5725-a756-b45ca5cc19b6','e1000001-0000-4000-8000-00000000000f','cue',3,'Do not rotate the torso','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('13ffb49a-9a79-54f9-afaf-6d6c5b4ba6d2','e1000001-0000-4000-8000-00000000000f','mistake',1,'Twisting to lift','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4e7b7227-dc71-5aa3-a80c-8a19b5a867e4','e1000001-0000-4000-8000-00000000000f','mistake',2,'Shrugging','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52c0a533-5f5f-5cd5-bda9-687da5e302ed','e1000001-0000-4000-8000-00000000000f','mistake',3,'Short range','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1657fccd-5fe4-59da-bebe-b1c2ca03180a','e1000001-0000-4000-8000-00000000001f','step',1,'Stand with feet a little wider than hip-width, kettlebell on the floor in front of you.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ccee1a73-f274-5a2a-9136-05343cb4fa03','e1000001-0000-4000-8000-00000000001f','step',2,'Hinge at the hips and grip the handle with one hand, back flat.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0daeb364-a46f-5751-a144-118be6da7306','e1000001-0000-4000-8000-00000000001f','step',3,'Hike the bell back between your legs.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe76b13f-6ee7-5090-b8cc-bf57a330ef7d','e1000001-0000-4000-8000-00000000001f','step',4,'Drive your hips forward explosively so the bell swings up to chest height.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('76bdd44a-cd72-5d55-9907-5242d6d504a7','e1000001-0000-4000-8000-00000000001f','step',5,'Let it swing back down and flow into the next rep; switch hands after the set.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('34ba5dbb-3469-5f63-9a4d-5c8440c4c8b9','e1000001-0000-4000-8000-00000000001f','cue',1,'Hike the bell back between the legs','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d537a793-bfe0-58ef-b46b-da105b7ee377','e1000001-0000-4000-8000-00000000001f','cue',2,'Snap hips forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a61cf8ae-e59c-5986-86b1-c12c82749d28','e1000001-0000-4000-8000-00000000001f','cue',3,'Let the bell float to chest height','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7a1bc774-e894-51bc-921e-1bb007c6d416','e1000001-0000-4000-8000-00000000001f','mistake',1,'Squatting the swing','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bf0cbb22-c37b-50ba-a525-8cff5c6f1a15','e1000001-0000-4000-8000-00000000001f','mistake',2,'Lifting with the arm','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c36c9da-5452-5447-b6b3-65fe9c9fa5c4','e1000001-0000-4000-8000-00000000001f','mistake',3,'Hyperextending at the top','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8216efd4-706f-56d0-aadf-95c149610239','e1000001-0000-4000-8000-00000000001b','step',1,'Place your forearms on the floor, elbows under shoulders.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37e6646b-9b6c-56e3-be6c-1a9653d03193','e1000001-0000-4000-8000-00000000001b','step',2,'Step your feet back so your body forms a straight line from head to heels.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('21cbb123-e7cf-5034-8f7b-e107e4a5c00d','e1000001-0000-4000-8000-00000000001b','step',3,'Squeeze glutes and brace your core.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fc9f446c-37a7-5699-8e67-087bfae8feab','e1000001-0000-4000-8000-00000000001b','step',4,'Hold for the planned time while breathing steadily.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd8a1475-6d6f-5253-b1f4-0694352d1f87','e1000001-0000-4000-8000-00000000001b','cue',1,'Elbows under shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('868391f3-2c7d-5dca-bb94-725f7a6a680b','e1000001-0000-4000-8000-00000000001b','cue',2,'Squeeze glutes and quads','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('105226fc-f983-5477-ac8a-4532eaf6c8d1','e1000001-0000-4000-8000-00000000001b','cue',3,'Push the floor away','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('15cc0b1e-388e-51c9-94c6-f80bdddf5baa','e1000001-0000-4000-8000-00000000001b','mistake',1,'Sagging hips','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74eb70a7-bf6b-5faa-b293-119f659cb63c','e1000001-0000-4000-8000-00000000001b','mistake',2,'Hips too high','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5a6e4de9-7841-5506-879d-ed3a1ea45c54','e1000001-0000-4000-8000-00000000001b','mistake',3,'Looking up','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fabfea19-5557-58ca-b2e9-db4a77c9aa8d','e1000001-0000-4000-8000-00000000000b','step',1,'Grab the pull-up bar with the palms facing forward using the prescribed grip. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('24b62a86-96e8-5796-bec7-61913fb7bd72','e1000001-0000-4000-8000-00000000000b','step',2,'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('08d1c1c8-4570-5d42-941b-b3c98769f61e','e1000001-0000-4000-8000-00000000000b','step',3,'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a0a7ba31-4537-530a-9033-27d8f54248cd','e1000001-0000-4000-8000-00000000000b','step',4,'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('12e7dd1e-29ec-5f69-a4ae-df0877f79b86','e1000001-0000-4000-8000-00000000000b','step',5,'Repeat this motion for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('874c6a2a-f6af-5f05-896f-a609a154def2','e1000001-0000-4000-8000-00000000000b','cue',1,'Start from a dead hang','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('da14ca16-ae38-5ba2-a69a-05b574a56a7e','e1000001-0000-4000-8000-00000000000b','cue',2,'Pull chest toward the bar','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('22e0e053-9228-5c25-bdaf-1dd171d93639','e1000001-0000-4000-8000-00000000000b','cue',3,'Lower to full hang every rep','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dcfe2009-8c5d-580e-a04e-858889768a87','e1000001-0000-4000-8000-00000000000b','mistake',1,'Kipping','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9a527e1c-2414-5d5d-9bc8-a1c2a5faa352','e1000001-0000-4000-8000-00000000000b','mistake',2,'Chin-poking to clear the bar','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('13840ce1-a4e9-5f82-9a38-d6c895be6dc8','e1000001-0000-4000-8000-00000000000b','mistake',3,'Half reps','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ca66d2d5-e9a1-5073-82cb-c3f8c9b78a1d','e1000001-0000-4000-8000-000000000007','step',1,'Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1082029e-d222-52b4-9a42-8110d5cb9b99','e1000001-0000-4000-8000-000000000007','step',2,'Next, lower yourself downward until your chest almost touches the floor as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cfbd64a7-818d-5f34-ae9f-37f30a818505','e1000001-0000-4000-8000-000000000007','step',3,'Now breathe out and press your upper body back up to the starting position while squeezing your chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('04cfc81b-e86c-524f-9019-eba1c5cfbe57','e1000001-0000-4000-8000-000000000007','step',4,'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('131cbc12-89d9-5a5b-b720-458759d8a6b5','e1000001-0000-4000-8000-000000000007','cue',1,'Hands just outside shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('708a338c-f15e-5089-830e-6f2c034751e2','e1000001-0000-4000-8000-000000000007','cue',2,'Body in one straight line','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('39d8fd63-c233-5e43-9185-d43adf77c7c5','e1000001-0000-4000-8000-000000000007','cue',3,'Chest to fist-height from the floor','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8614af73-6512-54b7-89d2-77c0345eb767','e1000001-0000-4000-8000-000000000007','mistake',1,'Sagging hips','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07e30c49-7e26-5b11-a1fb-8912a69e047b','e1000001-0000-4000-8000-000000000007','mistake',2,'Head poking forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b167116f-bcce-5741-9aaa-3399ff6f4b24','e1000001-0000-4000-8000-000000000007','mistake',3,'Elbows flared to 90 degrees','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fb7abeb0-9f95-5a65-8a9c-fc818d407600','e1000001-0000-4000-8000-000000000003','step',1,'Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a8c0bd3-7d67-5534-930a-38fb500d897f','e1000001-0000-4000-8000-000000000003','step',2,'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('991eed28-4a3f-5c14-8b91-8f83a9f3c26c','e1000001-0000-4000-8000-000000000003','step',3,'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('39e2b05d-bc47-5ae8-be57-408aafc08b0d','e1000001-0000-4000-8000-000000000003','step',4,'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Hold your breath as you lower and exhale as you complete the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35346a8f-c86c-5c84-8744-30a80173754b','e1000001-0000-4000-8000-000000000003','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d63b102-a61a-578c-b1f5-4bba2827abb0','e1000001-0000-4000-8000-000000000003','cue',1,'Soft knees, hips back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2ef2520e-4d0a-59c8-81e4-2ef09b3b0ed4','e1000001-0000-4000-8000-000000000003','cue',2,'Slide the bar down the thighs','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('41034d81-bfba-5170-8f40-abc18f8adab7','e1000001-0000-4000-8000-000000000003','cue',3,'Stop when hamstrings are fully stretched','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b9fe198-fe7b-548e-8cf7-59713e86f06e','e1000001-0000-4000-8000-000000000003','mistake',1,'Bending knees into a squat','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('882652e7-8098-5f86-8287-9b962b9ee965','e1000001-0000-4000-8000-000000000003','mistake',2,'Rounding the back to go lower','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('857fbf9e-55d8-50fc-b818-3e5ade6a7d2d','e1000001-0000-4000-8000-000000000003','mistake',3,'Letting the bar drift forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d0f5f357-c684-502f-9076-1f4baceebad0','e1000001-0000-4000-8000-00000000000d','step',1,'For this exercise you will need access to a low pulley row machine with a V-bar. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3977ee94-a59c-54bd-ba3a-e4d47ccdb544','e1000001-0000-4000-8000-00000000000d','step',2,'Lean over as you keep the natural alignment of your back and grab the V-bar handles.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62a39a51-f894-59b5-82b1-05220033689e','e1000001-0000-4000-8000-00000000000d','step',3,'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ff5ae6e-c871-58eb-a097-e9f3f5a56d92','e1000001-0000-4000-8000-00000000000d','step',4,'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9248e70f-ffed-5f2f-861a-fef573d9421f','e1000001-0000-4000-8000-00000000000d','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('605919ef-1cc1-5673-af4a-7cd7d7d169d7','e1000001-0000-4000-8000-00000000000d','cue',1,'Sit tall, slight knee bend','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea82d08b-d771-5133-bc96-fafca7b92ca0','e1000001-0000-4000-8000-00000000000d','cue',2,'Pull handle to lower ribs','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7147a3a3-bf00-5f2a-9ec0-d6f34621dd56','e1000001-0000-4000-8000-00000000000d','cue',3,'Let shoulders reach forward under control','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('347871f3-ba30-56bb-a9f9-1b64bca583a5','e1000001-0000-4000-8000-00000000000d','mistake',1,'Rocking the torso','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('13dc8e3b-cec2-5f34-b05e-9111435dc839','e1000001-0000-4000-8000-00000000000d','mistake',2,'Shrugging','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('291ec6bf-7b09-56c7-98d6-9707c10ccc52','e1000001-0000-4000-8000-00000000000d','mistake',3,'Rounding the back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('510e9092-98af-5280-89b4-279c9baa1f9e','e1000001-0000-4000-8000-00000000000a','step',1,'Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1dcf91bc-2d64-574b-aab0-fa07feb6923b','e1000001-0000-4000-8000-00000000000a','step',2,'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bf196f6e-90d8-5891-af32-6a3537566546','e1000001-0000-4000-8000-00000000000a','step',3,'Lower the dumbbells back down slowly to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a6cd5656-07ed-5fab-bf5e-67ffdeb8a412','e1000001-0000-4000-8000-00000000000a','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a43a490e-26b3-55c8-a023-8f4ddae6732e','e1000001-0000-4000-8000-00000000000a','cue',1,'Slight bend in elbows','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9f01df74-e515-5a71-9db6-fdff69ec16bf','e1000001-0000-4000-8000-00000000000a','cue',2,'Raise to shoulder height','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('27cafcf3-437e-54c9-8d77-af9e1fbfa693','e1000001-0000-4000-8000-00000000000a','cue',3,'Lead with elbows, thumbs neutral','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('559b89ae-c3a9-57aa-a757-c2d001862330','e1000001-0000-4000-8000-00000000000a','mistake',1,'Swinging','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('05e8b1c2-6dab-5a7f-bafb-53254f630cd5','e1000001-0000-4000-8000-00000000000a','mistake',2,'Shrugging','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6e688d8e-c453-5b4e-8636-2f93ed865582','e1000001-0000-4000-8000-00000000000a','mistake',3,'Raising above shoulder height with heavy weight','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('68e2c7fd-df81-56f8-a9da-101380b75dbc','e1000001-0000-4000-8000-000000000015','step',1,'Position yourself into a staggered stance with the rear foot elevated and front foot forward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac79588c-03e8-5c4b-a79c-386de559f9e9','e1000001-0000-4000-8000-000000000015','step',2,'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('92635b0a-6a7b-596a-894a-f389f2b4517e','e1000001-0000-4000-8000-000000000015','step',3,'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('133e585f-fa09-56d6-b657-047d37ec9fa6','e1000001-0000-4000-8000-000000000015','step',4,'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dc98b95c-531c-5620-8037-5d99471ca2be','e1000001-0000-4000-8000-000000000015','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac4ca29e-c8ab-5a56-9ac2-5fcb73e1e768','e1000001-0000-4000-8000-000000000015','cue',2,'Lower the back knee straight down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d26aab18-7cb7-5ef7-8537-ca4968a6955d','e1000001-0000-4000-8000-000000000015','cue',3,'Keep your torso tall','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59dd1c41-fff1-53c2-980f-dc6e358f89c6','e1000001-0000-4000-8000-000000000015','mistake',1,'Front knee collapsing inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('125b8aba-9e7d-585b-924d-17902552259f','e1000001-0000-4000-8000-000000000015','mistake',2,'Pushing off the back foot instead of the front heel','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('81fc0b15-0152-5623-bdeb-65078440864a','e1000001-0000-4000-8000-000000000015','mistake',3,'Short, choppy steps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('36b58e6e-0685-5e54-81f0-a1e7b6af1890','e1000001-0000-4000-8000-000000000019','step',1,'Adjust the padded lever of the calf raise machine to fit your height.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e45e9e6b-a7ad-54c1-a002-05a552a803b6','e1000001-0000-4000-8000-000000000019','step',2,'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('065dfcd3-2e9d-5056-a529-96db90b75247','e1000001-0000-4000-8000-000000000019','step',3,'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff807616-5446-56d2-a44b-3cc76e97b0c2','e1000001-0000-4000-8000-000000000019','step',4,'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3642328f-1b27-5d7a-a5d9-d2d854e2e05c','e1000001-0000-4000-8000-000000000019','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('024d7919-a2f6-51f4-abd5-bb6bb0c1a8d3','e1000001-0000-4000-8000-000000000019','cue',1,'Rise as high as possible onto the balls of the feet','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d91adc7-0f68-540f-bd25-d79967c4d674','e1000001-0000-4000-8000-000000000019','cue',2,'Pause at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8edd8490-7c49-55cd-8cf2-86fefd16d54e','e1000001-0000-4000-8000-000000000019','cue',3,'Lower fully into a stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eeb0315c-0336-5561-a565-9f2ecfac0567','e1000001-0000-4000-8000-000000000019','mistake',1,'Bouncing at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('16a92e4d-bc21-5f04-944d-2597552058c8','e1000001-0000-4000-8000-000000000019','mistake',2,'Bending the knees to cheat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c84b47a4-a5ba-504a-a0e9-7754e3b95078','e1000001-0000-4000-8000-000000000019','mistake',3,'Short range of motion','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('340f8008-7ca5-5f17-a673-45f4fbdc26c3','e1000001-0000-4000-8000-000000000008','step',1,'Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('54cb15c0-0dd5-57da-93c3-03ab0e14a6f8','e1000001-0000-4000-8000-000000000008','step',2,'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4ff06f0-5046-5fdc-ab52-d3403862a520','e1000001-0000-4000-8000-000000000008','step',3,'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('200f9869-3a17-5970-a4db-eaf3c8e757b1','e1000001-0000-4000-8000-000000000008','step',4,'Lower the bar down to the collarbone slowly as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c7e37adb-562c-5284-9371-09c17a675cda','e1000001-0000-4000-8000-000000000008','step',5,'Lift the bar back up to the starting position as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4e82d441-fbaa-5379-92bb-7a701f5b4987','e1000001-0000-4000-8000-000000000008','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('acff58fd-806c-5c16-8212-39cd57b9bd80','e1000001-0000-4000-8000-000000000008','cue',1,'Bar starts on front shoulders','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4fa51ac-7636-5f89-a9fc-d188d3b5689f','e1000001-0000-4000-8000-000000000008','cue',2,'Head moves back then through','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('034276f8-8bc3-59d2-9254-e24864246304','e1000001-0000-4000-8000-000000000008','cue',3,'Lock out overhead with biceps by ears','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac4c2915-fbe2-5939-80cc-4316520ae364','e1000001-0000-4000-8000-000000000008','mistake',1,'Leaning back','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8474133c-9d01-5a26-acb0-472da589f481','e1000001-0000-4000-8000-000000000008','mistake',2,'Pressing forward','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dad81cfb-fed4-506d-bcc8-5d9c1a111979','e1000001-0000-4000-8000-000000000008','mistake',3,'Not locking out','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('840129e8-9925-5f48-9139-b97634126035','e1000001-0000-4000-8000-000000000012','step',1,'Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b8f89af-780b-5a0f-adcd-912dfed18acd','e1000001-0000-4000-8000-000000000012','step',2,'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('917c7c39-7527-512a-b055-3279fc0e0917','e1000001-0000-4000-8000-000000000012','step',3,'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3329fbd6-0ce3-57bd-95b4-7053bcbbb437','e1000001-0000-4000-8000-000000000012','step',4,'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('14a9937b-ff7e-5865-b336-56eec15d3a20','e1000001-0000-4000-8000-000000000012','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
