INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dc4856b8-fa05-55a0-91ca-f479434f64d9','e1000001-0000-4000-8000-000000000023','step',1,'To begin, step onto the treadmill and select the desired option from the menu.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d5b7d81-b749-5120-ba00-ba3cdc0691c3','e1000001-0000-4000-8000-000000000023','step',2,'Most treadmills have a manual setting, or you can select a program to run.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('01da791d-1ca3-5eed-8d66-6b1c4a248e6b','e1000001-0000-4000-8000-000000000023','step',3,'Elevation can be adjusted to change the intensity of the workout.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e0436580-75da-5312-ad46-d1351a6ab8b9','e1000001-0000-4000-8000-000000000023','step',4,'When walking, you should move at a moderate to fast pace, not a leisurely one.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('041f8971-cc24-5471-8444-7c7d05fa9915','e1000001-0000-4000-8000-000000000023','step',5,'Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4754ee82-e7de-559f-bd1f-ebf4842fe99b','e1000001-0000-4000-8000-000000000023','cue',1,'Walk at a brisk pace (talk test)','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9348530c-f33d-5b92-8096-7f28c89dc1ae','e1000001-0000-4000-8000-000000000023','cue',2,'Swing arms naturally','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d1b0fff6-38d5-5c0d-9d03-4f18ef0d8aa6','e1000001-0000-4000-8000-000000000023','cue',3,'Use incline for more effort','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b9d50ba-b117-5ea5-abd5-41bc4caad43e','e1000001-0000-4000-8000-000000000023','mistake',1,'Holding the rails','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bdb17fae-b650-5c04-8c4d-a5b14df8cb72','e1000001-0000-4000-8000-000000000023','mistake',2,'Overstriding','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('160935b9-b781-52a0-ab84-bd701886e7da','e1000001-0000-4000-8000-000000000023','mistake',3,'Looking down','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('609284fc-242c-5448-a9d1-1fe81b16e13c','e1000001-0000-4000-8000-00000000000c','step',1,'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f11689f7-f65b-5f7b-a35c-933c9fa67be8','e1000001-0000-4000-8000-00000000000c','step',2,'Grab the bar with the palms facing forward using the prescribed grip. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aeed4933-6911-58df-9051-07b395977752','e1000001-0000-4000-8000-00000000000c','step',3,'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74fe1de0-1cb4-521f-80b2-bb81d3e553a6','e1000001-0000-4000-8000-00000000000c','step',4,'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d2c56d2a-92e9-51db-af51-e5ab56de9590','e1000001-0000-4000-8000-00000000000c','step',5,'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('826cb182-0f48-55d2-87fb-1f98173f1417','e1000001-0000-4000-8000-00000000000c','step',6,'Repeat this motion for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dbbac60d-5c73-5e68-999b-471efecfad27','e1000001-0000-4000-8000-00000000000c','cue',1,'Thighs locked under the pad','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('49c9dbf7-3c81-5c50-ad8d-c2a8a6528c3b','e1000001-0000-4000-8000-00000000000c','cue',2,'Pull to upper chest','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0f346eb0-35ff-55b1-87f8-8beb886aa289','e1000001-0000-4000-8000-00000000000c','cue',3,'Lean back only slightly','en','ai_authored:specific');
