INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('030f0261-9069-54ea-a29c-1ac2629bcdcd','e1000001-0000-4000-8000-00000000000c','mistake',2,'Leaning far back','en','ai_authored:specific');
