INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8f3229e7-f81d-5961-afa1-526131addd22','455c58af-1490-5ada-bc74-86c3663f7761','step',1,'Lie on your back, with one leg extended straight out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aceb0c39-057a-5861-9e6a-0a8313d40009','455c58af-1490-5ada-bc74-86c3663f7761','step',2,'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('db117339-4be9-55b7-9990-a2a227445008','455c58af-1490-5ada-bc74-86c3663f7761','step',3,'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9dff4b54-a068-5f64-903c-13812598eedd','455c58af-1490-5ada-bc74-86c3663f7761','step',4,'Repeat for 10-20 repetitions, and then switch to the other leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3fe977e9-a662-5c71-8da4-87417fbdfd52','455c58af-1490-5ada-bc74-86c3663f7761','cue',1,'Breathe slowly and deeply','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('188c367e-3640-51d4-ba70-04e38fac8363','455c58af-1490-5ada-bc74-86c3663f7761','cue',2,'Move into the stretch gradually','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9b627f03-c7bb-56ec-b497-09b2c7aa6b7d','455c58af-1490-5ada-bc74-86c3663f7761','cue',3,'Hold or move only in a pain-free range','en','ai_authored:pattern');
