INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb198f2c-410c-5ecf-99bd-626588c6bedf','ca17631a-c08e-5283-bca2-a7e97c267c05','step',1,'Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2bae2ad0-1ee3-5247-9685-d2289dd56313','ca17631a-c08e-5283-bca2-a7e97c267c05','step',2,'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Concentrate on using your abs to move the weight while relaxing your legs and feet.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('635f0e5f-2c9b-5cd9-9f0f-861f08a9df3e','ca17631a-c08e-5283-bca2-a7e97c267c05','step',3,'After a second pause, slowly return to the starting position as you breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d49c1145-72f7-5c0f-917a-90bb991be146','ca17631a-c08e-5283-bca2-a7e97c267c05','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('838d541d-ada6-5bc4-bc07-f61cf67e8b56','ca17631a-c08e-5283-bca2-a7e97c267c05','cue',1,'Exhale as you curl up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c622b682-68f5-582b-872f-db9bd2bc0d81','ca17631a-c08e-5283-bca2-a7e97c267c05','cue',2,'Move the ribs toward the pelvis','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be31b840-755e-59f4-84a1-a4fcee96c3bf','ca17631a-c08e-5283-bca2-a7e97c267c05','cue',3,'Keep the neck relaxed','en','ai_authored:pattern');
