INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('50132d36-44d1-5722-bc31-eb23a9350c6b','bfd9d15c-803e-56e4-a858-c80a65b7ec6a','cue',2,'Keep a straight line from head to heels','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6da84ad8-ed07-5590-a104-ab3d8be504ba','bfd9d15c-803e-56e4-a858-c80a65b7ec6a','cue',3,'Breathe steadily','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7ee63b8-75ae-50bc-9239-b6bc3e017bb6','bfd9d15c-803e-56e4-a858-c80a65b7ec6a','mistake',1,'Hips sagging','en','ai_authored:pattern');
