INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5b8411c5-fa96-5a18-8acc-250722c44691','595d506b-800b-55eb-8922-4e65cc3b14a9','step',1,'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('67191523-79fe-5cee-9ff0-7cdd31202108','595d506b-800b-55eb-8922-4e65cc3b14a9','step',2,'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('535eff70-a9ec-5b22-b790-71ceed3472e8','595d506b-800b-55eb-8922-4e65cc3b14a9','step',3,'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('60783d10-8565-5066-85c8-878b2927bd0f','595d506b-800b-55eb-8922-4e65cc3b14a9','step',4,'Go back to the initial position as you breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('64754625-014e-5a2f-8be8-185d6de6198f','595d506b-800b-55eb-8922-4e65cc3b14a9','step',5,'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7b60dee4-f7ad-55e5-a744-479d238d9d67','595d506b-800b-55eb-8922-4e65cc3b14a9','step',6,'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b30421e6-9c3f-5cbc-8007-f3255273694c','595d506b-800b-55eb-8922-4e65cc3b14a9','cue',1,'Exhale as you curl up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62d6bce2-0da7-5d79-87cb-ea344478a961','595d506b-800b-55eb-8922-4e65cc3b14a9','cue',2,'Move the ribs toward the pelvis','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c355f377-d634-58b4-b761-4a4b00249ade','595d506b-800b-55eb-8922-4e65cc3b14a9','cue',3,'Keep the neck relaxed','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0c84e04c-059f-5e50-b86b-510670283054','595d506b-800b-55eb-8922-4e65cc3b14a9','mistake',1,'Pulling on the neck','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8b377ce-6ab6-5f54-b18d-e1e2ae97f70f','595d506b-800b-55eb-8922-4e65cc3b14a9','mistake',2,'Using hip flexors/momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d5afb10-f0ba-566e-b11a-a1c83c7b5bc8','595d506b-800b-55eb-8922-4e65cc3b14a9','mistake',3,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be500799-e45f-5d62-89f6-a1bc5b78a519','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',1,'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b28ea8f3-61ce-50e9-90b3-463654cabeb2','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',2,'The palms of the hands should be facing your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7b51226-d6cf-52ea-a3f7-f1139f7313f0','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',3,'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6e05a1ac-d2cc-58d1-bd63-cefc2a1d856c','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',4,'Slowly begin to bring the dumbbells back to starting position as your breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1e7ae0df-dc18-5a91-add4-33896937323c','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',5,'Repeat the movement with the left hand. This equals one repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('86610d6f-8bb6-51d1-8157-de425b44b1ec','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','step',6,'Continue alternating in this manner for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07f511ef-fd4b-5aa3-91a5-2c83943df67f','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d5c4bd4f-3fa6-5f86-b474-91fd93506047','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','cue',2,'Squeeze at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d34557e0-0c45-556d-9783-a4344153011e','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','cue',3,'Lower all the way under control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17952e53-9293-5635-846a-c70013b62f0e','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','mistake',1,'Swinging the body','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('15c16ae0-661a-5552-9b42-9a71c460969f','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','mistake',2,'Elbows drifting forward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2300b77-79bd-571b-a41b-67161434bcd3','cb86ad9b-b42e-57a5-8331-cdfa2dd2a98f','mistake',3,'Cutting the range short','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d8d78d8-9ed4-582c-86c3-9d755045bd98','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',1,'Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7ce8847-cc96-5b31-a261-dbce06608d69','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',2,'Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7073aab4-cbe1-59ce-8b31-cc17cb99b3f0','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',3,'Now go back slowly to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('26f398b5-490d-56a9-bb97-7944a2059f0e','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',4,'Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5b68b28f-19d8-5f5f-81e6-f0faedb628c2','628f1ac9-0ebf-5a43-b784-145326bc7ef1','step',5,'Continue alternating sides in this manner until all prescribed repetitions are done.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e63be9b0-fa16-5f5c-aefd-c475ec3cc5ef','628f1ac9-0ebf-5a43-b784-145326bc7ef1','cue',1,'Rotate from the torso with hips stable','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('01d203d6-13ae-58ab-872e-ced324a83ad8','628f1ac9-0ebf-5a43-b784-145326bc7ef1','cue',2,'Move with control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6a667e87-6fb2-5f1f-b5e4-b2192d9642cb','628f1ac9-0ebf-5a43-b784-145326bc7ef1','cue',3,'Keep the core braced','en','ai_authored:pattern');
