INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('093d3496-38ec-5c27-bc80-ff0855ec35e5','628f1ac9-0ebf-5a43-b784-145326bc7ef1','mistake',3,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2150e019-6b11-5fcd-825a-ecb7974f118d','4843fe76-be73-5f5e-8724-20efe7ac747a','step',1,'Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ec0b878b-877f-5c07-8a0b-db29463ba4aa','4843fe76-be73-5f5e-8724-20efe7ac747a','step',2,'Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a41ab9e-3b62-527d-b39f-8ab915246f0b','4843fe76-be73-5f5e-8724-20efe7ac747a','step',3,'Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b2795044-43ee-59e3-a163-8fcd5887b29e','4843fe76-be73-5f5e-8724-20efe7ac747a','cue',1,'Pull with the elbows, not the hands','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('86641683-0def-5677-836a-8060ba4285ff','4843fe76-be73-5f5e-8724-20efe7ac747a','cue',2,'Squeeze shoulder blades together','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9a2003fc-eba0-5090-b418-907d9b35a336','4843fe76-be73-5f5e-8724-20efe7ac747a','cue',3,'Keep the torso still','en','ai_authored:pattern');
