INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('639643a7-fa50-5faa-aae1-1a06d8dabfad','c42534d1-f419-5d16-a72e-3065ae20f1b1','step',1,'Use a sturdy object like a squat rack to hold yourself.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f2425934-66a8-5638-a7b0-25b01b9e47fc','c42534d1-f419-5d16-a72e-3065ae20f1b1','step',2,'Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Breathe normally as you perform the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('888f69ae-cb9e-5584-a9f5-7ff5eb5691d5','c42534d1-f419-5d16-a72e-3065ae20f1b1','step',3,'When you are done with the right foot, then repeat with the left leg.','en','source:free_exercise_db');
