INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aac2c168-6694-55cf-b8a4-1a13cec0d0d0','c42534d1-f419-5d16-a72e-3065ae20f1b1','cue',2,'Move into the stretch gradually','en','ai_authored:pattern');
