INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b98e20cd-0270-58fd-b174-0d5889222a00','59c52855-0cf2-563c-a2de-fcf96163546b','step',1,'Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f6e40f33-c53b-5dee-9400-94a6ac5a6f9f','59c52855-0cf2-563c-a2de-fcf96163546b','step',2,'Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('24e29777-f7b1-5a14-9995-d70e7608d7f3','59c52855-0cf2-563c-a2de-fcf96163546b','step',3,'Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.','en','source:free_exercise_db');
