INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7b74a0e5-b43c-5bb8-9793-a69d73bb70e0','59c52855-0cf2-563c-a2de-fcf96163546b','mistake',3,'Forcing range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2ea59428-286c-5894-8afd-8f3f9f70b1bb','ac365de8-7857-5402-af9a-db30605499ec','step',1,'Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. The starting position should look like the contracted portion of a dumbbell curl.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('27e1f5a0-5ca2-5a33-ba40-f59cf3e3372a','ac365de8-7857-5402-af9a-db30605499ec','step',2,'Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c1017500-76a6-5c41-b1ef-e1f45b15ebc6','ac365de8-7857-5402-af9a-db30605499ec','step',3,'Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b81258f0-31a1-58a6-9172-327b8f895a3c','ac365de8-7857-5402-af9a-db30605499ec','step',4,'After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Breathe in as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eadfc2ea-6fce-5356-b7c4-a326a378d361','ac365de8-7857-5402-af9a-db30605499ec','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9e6331ec-6a23-504d-adef-fefc92d464c1','ac365de8-7857-5402-af9a-db30605499ec','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dc7a8e31-649e-55b2-a76f-f9e7a0d432e2','ac365de8-7857-5402-af9a-db30605499ec','cue',2,'Press in a straight line overhead','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('703f0f04-c581-530d-9e46-928be3a07780','ac365de8-7857-5402-af9a-db30605499ec','cue',3,'Finish with biceps near the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59e5eee3-9dd8-5acf-a06a-67d485effeec','ac365de8-7857-5402-af9a-db30605499ec','mistake',1,'Excessive lower-back arch','en','ai_authored:pattern');
