INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('81d32269-c691-5b4d-8949-c79b8187fba6','20ef3756-a490-523e-b237-eafabad468fd','cue',3,'Keep shoulders away from ears','en','ai_authored:pattern');
