INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0d8f9806-aaa5-53c6-9209-b74bfc4da86c','f0c88ecb-cdb6-5a64-809c-9a36292b71f8','step',1,'Begin on the floor laying on your back with your feet on top of the ball.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4db6618c-b90f-5cc3-826c-22873a8bac79','f0c88ecb-cdb6-5a64-809c-9a36292b71f8','step',2,'Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('08fd9907-2e05-5eb0-a019-2aff24d06308','f0c88ecb-cdb6-5a64-809c-9a36292b71f8','step',3,'Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8a4c08c7-2b7f-5bb8-bbd0-73971dbde696','f0c88ecb-cdb6-5a64-809c-9a36292b71f8','step',4,'Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.','en','source:free_exercise_db');
