INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17b97e83-e3da-54a0-9189-ee0ee393f451','e9e1fea8-796c-5ef5-ab69-813e77c771ee','step',1,'Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8b5ad2a2-32f4-5fb2-9321-11c3b6d6ed06','e9e1fea8-796c-5ef5-ab69-813e77c771ee','step',2,'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3050da88-f403-5ba2-a3a9-bb76269d0d8f','e9e1fea8-796c-5ef5-ab69-813e77c771ee','step',3,'Slowly roll the barbell straight forward, stretching your body into a straight position. Breathe in during this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8d9d2d5b-462f-5dea-b6c6-ed6af43d53aa','e9e1fea8-796c-5ef5-ab69-813e77c771ee','step',4,'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out.','en','source:free_exercise_db');
