INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f2d2a2a2-23a0-5555-a087-1145b4053bcc','e9e1fea8-796c-5ef5-ab69-813e77c771ee','cue',2,'Keep a straight line from head to heels','en','ai_authored:pattern');
