INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('034f4cc4-2ce0-5f0d-a3bd-5467e8275257','a2a6be85-fde8-57f4-8ff0-d9698390fab8','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('14774cec-e91e-5a84-b77b-dae45585192c','4e567745-f548-5c0d-b5a7-aa897f98441c','step',1,'Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7f0f8c43-cbf2-59c9-bbfc-83783b452a17','4e567745-f548-5c0d-b5a7-aa897f98441c','step',2,'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25859b0f-8892-5032-b54e-288ab92080f9','4e567745-f548-5c0d-b5a7-aa897f98441c','step',3,'Extend as far as possible, then reverse the motion to return to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('48b2cf3c-e9fc-53d2-a348-896c5feca9c0','4e567745-f548-5c0d-b5a7-aa897f98441c','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c16082f-af6d-5d04-8dab-45636bab1911','4e567745-f548-5c0d-b5a7-aa897f98441c','cue',2,'Keep the weight close to your legs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('213582bd-5579-59e5-a1b3-82624322f778','4e567745-f548-5c0d-b5a7-aa897f98441c','cue',3,'Neutral spine from head to hips','en','ai_authored:pattern');
