INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dadd1081-0ba7-5a02-a673-341f8fa26c32','7b98027c-7e91-5644-8f2d-772a54a500a0','step',2,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b2b8aa58-dabc-50e6-8b6f-ff98203f0a52','7b98027c-7e91-5644-8f2d-772a54a500a0','step',3,'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e72394b4-12dd-50d4-bc32-56a4dbc5a7a9','7b98027c-7e91-5644-8f2d-772a54a500a0','step',4,'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('47d86036-d9eb-56b4-86bf-d0e77b18b56a','7b98027c-7e91-5644-8f2d-772a54a500a0','step',5,'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('06cadd2f-57ce-55ec-831c-3038d919cc39','7b98027c-7e91-5644-8f2d-772a54a500a0','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b9686203-af37-5b87-b8a5-83b864ca900f','7b98027c-7e91-5644-8f2d-772a54a500a0','cue',2,'Lower the back knee straight down','en','ai_authored:pattern');
