INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e7afc160-5d64-5530-93d9-6fecdbcff168','d4833300-9b69-5ad3-ba9e-c474c78c7718','step',1,'Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e2717e95-97b0-5724-a276-9294f8c7267f','d4833300-9b69-5ad3-ba9e-c474c78c7718','step',2,'Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c204a55e-7887-5623-ae6b-043b13b2f322','d4833300-9b69-5ad3-ba9e-c474c78c7718','step',3,'Lower the bar down to the shoulders slowly as you inhale.','en','source:free_exercise_db');
