INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e81c7e50-0751-5597-9cc3-70792684b365','7c455710-7671-5bc6-b694-08d94f03da0a','step',1,'Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). You can use wrist wraps for this exercise for a better grip. This will be your starting position.','en','source:free_exercise_db');
