INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('78f7757a-d686-5286-8122-a1a128cc403e','5fce11b7-d3f5-5cef-8fd1-db5d2c500908','step',1,'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('90edc513-d8a6-5e12-bccb-e17e1151de9f','5fce11b7-d3f5-5cef-8fd1-db5d2c500908','step',2,'Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ebd0fa67-fdbc-5ea4-8eee-0015a6d74214','5fce11b7-d3f5-5cef-8fd1-db5d2c500908','step',3,'Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('33c62d5a-24c6-52bf-8f61-67782db54bdc','5fce11b7-d3f5-5cef-8fd1-db5d2c500908','step',4,'After performing the recommended amount of reps, repeat the movement with the opposite leg.','en','source:free_exercise_db');
