INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ecf5e79d-8e76-587d-ac3c-4e0c850a05c2','5fce11b7-d3f5-5cef-8fd1-db5d2c500908','mistake',3,'Short, choppy steps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0b3016cd-add3-5e9f-9fcc-fa6e56fdfdd8','1c0df543-b492-5f54-8b84-f6f31aea03c8','step',1,'This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2e6887ee-13ff-509e-8072-23a03b29325a','1c0df543-b492-5f54-8b84-f6f31aea03c8','step',2,'Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87647a2b-47b1-566e-a287-4f7a050ad818','1c0df543-b492-5f54-8b84-f6f31aea03c8','step',3,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('de507827-8e2e-5ada-bd7c-77097f4520d7','1c0df543-b492-5f54-8b84-f6f31aea03c8','step',4,'Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1b203b8d-fd36-5cfd-830f-19aa299ef97e','1c0df543-b492-5f54-8b84-f6f31aea03c8','step',5,'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('498d04f1-64c2-5d24-a20e-d1a9eb5638fe','1c0df543-b492-5f54-8b84-f6f31aea03c8','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d917abb8-6fea-55a7-ac03-60fa4aca400f','1c0df543-b492-5f54-8b84-f6f31aea03c8','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9257aaff-f269-5c7c-8394-c1d945305167','1c0df543-b492-5f54-8b84-f6f31aea03c8','cue',2,'Knees track over your toes','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1c5b2223-c1bf-522d-bb2d-290df9e42345','1c0df543-b492-5f54-8b84-f6f31aea03c8','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('27cf7ecd-bdd6-588b-81a9-0dad5a4720d6','1c0df543-b492-5f54-8b84-f6f31aea03c8','mistake',1,'Knees caving inward','en','ai_authored:pattern');
