INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('97c9f26b-c581-56dd-a324-e90a9d41aeb8','71aa99db-64b7-5455-8bea-bc02ad780942','step',1,'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('311c9589-cf82-5c54-8cd3-73ea515274ed','71aa99db-64b7-5455-8bea-bc02ad780942','step',2,'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9255fb3-6fba-508d-8bfe-74373cdfea39','71aa99db-64b7-5455-8bea-bc02ad780942','step',3,'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a065652e-9d31-5570-81b8-af8bd99eaa00','71aa99db-64b7-5455-8bea-bc02ad780942','step',4,'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.','en','source:free_exercise_db');
