INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3253033b-5384-5540-9397-fdf5142fda1f','ee82bd25-f975-5314-9b9c-adba475c9918','step',1,'Begin standing with your feet shoulder width apart and a barbell across your upper back.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('13ae2805-41ad-5354-9c1e-8e6862b2958e','ee82bd25-f975-5314-9b9c-adba475c9918','step',2,'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1af76dc6-1fc4-5a94-9ac2-614d0b31b077','ee82bd25-f975-5314-9b9c-adba475c9918','step',3,'Drive through the heel of your lead foot and extend both knees to raise yourself back up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bcd9b757-f92d-51db-bd6d-91396802c408','ee82bd25-f975-5314-9b9c-adba475c9918','step',4,'Step forward with your rear foot, repeating the lunge on the opposite leg.','en','source:free_exercise_db');
