INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cd3b08f5-04c8-5c06-80c9-955ca53bc94e','b39acbad-9d48-58ce-a757-820622bc2039','step',1,'For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d9927f7c-4de8-53aa-ac0d-f3fcd3287dcd','b39acbad-9d48-58ce-a757-820622bc2039','step',2,'Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1031dd08-c1e7-5b92-851c-b32dcd061730','b39acbad-9d48-58ce-a757-820622bc2039','step',3,'As you let that arm drop to the starting position, raise the opposite side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5758a516-fd6b-5308-9835-46cfb1b95c24','b39acbad-9d48-58ce-a757-820622bc2039','step',4,'Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e91a318a-1a7b-5bfe-bf40-ecc0f4d4b289','b39acbad-9d48-58ce-a757-820622bc2039','cue',1,'Drive explosively with the legs/hips','en','ai_authored:pattern');
