INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d1317e8c-7f25-5998-8323-ee68c6f4bb8d','8667f449-7c4a-509d-8cbd-f54998b03fcd','step',1,'For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('86f3a507-9315-5ee1-8742-a706e5a8a7e3','8667f449-7c4a-509d-8cbd-f54998b03fcd','step',2,'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Forearms should always be pointing down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c6cb9551-cead-5437-97c1-4d52edc763f8','8667f449-7c4a-509d-8cbd-f54998b03fcd','step',3,'Using your triceps to bring your torso up again, lift yourself back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44295f3f-e6f7-5313-8741-5b40d936336b','8667f449-7c4a-509d-8cbd-f54998b03fcd','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
