INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cd627d44-b6ea-56cc-b847-4b0d6ad6f512','8667f449-7c4a-509d-8cbd-f54998b03fcd','mistake',3,'Using momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6af20709-8b71-5f8c-828b-973109903b26','d7ce07ee-5605-5f42-90ef-b0c5fdb53d2e','step',1,'With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87ab4d46-44ff-5bf6-8c41-1de65a804452','d7ce07ee-5605-5f42-90ef-b0c5fdb53d2e','step',2,'While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('96c88e3d-57b7-598c-8767-09cfcb077bad','d7ce07ee-5605-5f42-90ef-b0c5fdb53d2e','step',3,'Slowly lower the weight again to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('614af1e1-94ca-5f20-886e-f00bad409088','d7ce07ee-5605-5f42-90ef-b0c5fdb53d2e','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1571046f-143c-5661-9163-05750989c544','d7ce07ee-5605-5f42-90ef-b0c5fdb53d2e','cue',1,'Pull with the elbows, not the hands','en','ai_authored:pattern');
