INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('976cf69e-0c57-5975-b102-21bfab9087ea','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',1,'Place a dumbbell standing up on a flat bench.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9ab5fc47-8eef-51aa-a64d-b9ed60a6b75f','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',2,'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('da1aff10-eb38-5778-a411-72815c442dd6','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',3,'Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('380aabef-760a-5247-a8b3-230cafb187ab','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',4,'While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59f0119b-f86b-508a-a796-0d5631443c5c','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',5,'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c159a8ae-92b3-5a2b-b77b-e9b3f73b0fa6','6eb6e252-05bb-5b44-ae4c-43609c25982d','step',6,'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d9c823a4-fb21-5fa6-b3a8-4ddaece12eaf','6eb6e252-05bb-5b44-ae4c-43609c25982d','cue',1,'Keep a slight bend in the elbows','en','ai_authored:pattern');
