INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a14094a2-ed23-528c-85d4-4685bb10253c','43037bed-416f-5ed3-b690-764660d399ca','step',2,'Ride at an easy pace for 5 minutes to warm up.','en','ai_authored:specific');
