INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5dda0309-46bc-54f4-b338-523a61ab26cb','742a4a70-dd78-5515-93c5-ddee0b0787a2','step',3,'Begin by flexing the elbow, lowering yourself towards the bar.','en','source:free_exercise_db');
