INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8582baa6-3578-5760-b94b-5814977b50b6','710db63d-3636-5371-888c-fa181db61bf4','step',2,'Begin the movement by flexing your knees and hips, sitting back with your hips.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e6435c03-0c2e-56b4-8243-2bd33e253d0c','710db63d-3636-5371-888c-fa181db61bf4','step',3,'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.','en','source:free_exercise_db');
