INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4e39b825-e7be-5f61-97ac-7ded2afb6c1c','1d516abe-53dc-55ef-898c-c530f0f59b3f','step',2,'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.','en','source:free_exercise_db');
