INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3b2651b2-5826-5135-acf2-e3d8312932d3','f38bb441-e520-5c9a-9876-6f1e8ec00a15','step',2,'Take hold of the handles. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4fa25c57-6bb3-5236-b661-2af35abd6c10','f38bb441-e520-5c9a-9876-6f1e8ec00a15','step',3,'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e4ebcbc6-1cea-53bb-9de8-077a976dea50','f38bb441-e520-5c9a-9876-6f1e8ec00a15','step',4,'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.','en','source:free_exercise_db');
