INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('22de1db4-0eb5-5040-a820-5ec2ffa96b4d','4e120edc-ea39-5f74-9757-94cfc391cf4b','step',3,'Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6b41f9db-9669-5ae6-9ef8-906534bcfe37','4e120edc-ea39-5f74-9757-94cfc391cf4b','step',4,'With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a99816f1-60c4-5106-b057-f7ef79314df5','4e120edc-ea39-5f74-9757-94cfc391cf4b','step',5,'Slowly return to the starting position as you inhale. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.','en','source:free_exercise_db');
