INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3499ffa4-4e8d-58ce-9a77-5c2f8d4fa1ed','765954f7-289a-5015-9841-bf50127faf5c','step',1,'Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('db8798f2-ee4c-5c5f-b268-213ab272aa22','765954f7-289a-5015-9841-bf50127faf5c','step',2,'Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7b7a2471-02b2-5f22-9793-40e3f3556fc8','765954f7-289a-5015-9841-bf50127faf5c','step',3,'Put your elbows in by your side and keep them there stationary during the entire movement. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aecd7c31-e441-586b-8d6f-73b616739e0b','765954f7-289a-5015-9841-bf50127faf5c','step',4,'Using your biceps, pull your arms up as you exhale until your biceps touch your forearms.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8b57b915-3a4f-550f-bbe5-644b1fd9da2b','765954f7-289a-5015-9841-bf50127faf5c','step',5,'After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('576849e9-7bab-5c63-9065-87dd14267c34','765954f7-289a-5015-9841-bf50127faf5c','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
