INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd9a7b9f-241d-58ef-8524-b36efc85f366','765954f7-289a-5015-9841-bf50127faf5c','cue',2,'Squeeze at the top','en','ai_authored:pattern');
