INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2463ffa9-3301-58b8-b95f-f9f40f5c07ad','96cff86c-5194-5359-9aba-bb35b49a77c7','step',1,'Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3ea4614e-5a55-57ff-8505-e44a36baddb6','96cff86c-5194-5359-9aba-bb35b49a77c7','step',2,'Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37294b30-08c0-5a08-a09c-3d61fa7dd542','96cff86c-5194-5359-9aba-bb35b49a77c7','step',3,'Now step out and away from the stack with a wide stance and grasp the bar of the pulley system. Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2e21cf07-2813-5dbb-b5eb-c061d2b44a65','96cff86c-5194-5359-9aba-bb35b49a77c7','step',4,'Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bbfb198d-110d-514f-abdb-eebd13718a99','96cff86c-5194-5359-9aba-bb35b49a77c7','step',5,'Slowly return to the starting position as you breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d3b8b3d-7c2a-5395-9add-15d1d298d934','96cff86c-5194-5359-9aba-bb35b49a77c7','step',6,'Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('40d78b2c-0439-532b-be74-7eec12e9d249','96cff86c-5194-5359-9aba-bb35b49a77c7','cue',1,'Move slowly and under control','en','ai_authored:pattern');
