INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c55d0a8a-4945-5309-b106-582e34f596b2','936553dd-4dbf-5189-a83b-86dd74d5ae2e','step',1,'Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('766ff8ef-b7f5-5cf9-b461-543fe234154d','936553dd-4dbf-5189-a83b-86dd74d5ae2e','step',2,'Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('65a304e4-4cf5-5eba-9d23-9375cc3e8fb7','936553dd-4dbf-5189-a83b-86dd74d5ae2e','step',3,'Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('094bdf76-0bff-5a11-bb01-0fde05304f2c','936553dd-4dbf-5189-a83b-86dd74d5ae2e','step',4,'Slowly go back to the initial position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('de8de693-a472-56da-9967-95b61b585ed0','936553dd-4dbf-5189-a83b-86dd74d5ae2e','step',5,'Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ebd89e66-bf6b-5128-8130-01f5e689ccf3','936553dd-4dbf-5189-a83b-86dd74d5ae2e','cue',1,'Lead with the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('639b0134-b1e4-51f7-b754-d62577a8b20f','936553dd-4dbf-5189-a83b-86dd74d5ae2e','cue',2,'Control the lowering','en','ai_authored:pattern');
