INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c24573bd-4534-5c43-b7b0-a01eb2db485a','9ce330e8-2592-5dc8-9d3e-9af71695fef4','step',1,'With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9e125a2b-a44c-59c4-948b-f8eeaa9c701d','9ce330e8-2592-5dc8-9d3e-9af71695fef4','step',2,'Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('38317091-4607-5ea1-90dc-d14ba7b7bcc3','9ce330e8-2592-5dc8-9d3e-9af71695fef4','step',3,'As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Your upper arms should remain stationary at all times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('327afdc9-e2d0-52dc-b55b-deb76a06ecae','9ce330e8-2592-5dc8-9d3e-9af71695fef4','step',4,'Squeeze the triceps and hold for a second in this contracted position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c118bf7-c031-5c04-8875-2ba69485c1e4','9ce330e8-2592-5dc8-9d3e-9af71695fef4','step',5,'Slowly return the handle to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9bff0f6-227d-5b4b-a53f-2c6c1e52da6d','9ce330e8-2592-5dc8-9d3e-9af71695fef4','step',6,'Repeat for the recommended amount of repetitions and then perform the same movement with the other arm.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('58590ca8-dbde-5ffd-bb49-3133bc08e692','9ce330e8-2592-5dc8-9d3e-9af71695fef4','cue',1,'Keep upper arms still','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fb2972bb-2f31-515b-93bd-5168bf4c562b','9ce330e8-2592-5dc8-9d3e-9af71695fef4','cue',2,'Fully straighten the elbow','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('493dfe89-031c-54ce-862a-ca75f0cf0edf','9ce330e8-2592-5dc8-9d3e-9af71695fef4','cue',3,'Control the stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('42227143-cf95-508b-86bf-8b226a109466','9ce330e8-2592-5dc8-9d3e-9af71695fef4','mistake',1,'Flaring elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ce82f3c6-fb26-5946-8c70-d992c45dbcbb','9ce330e8-2592-5dc8-9d3e-9af71695fef4','mistake',2,'Moving the shoulders','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7094f981-b746-5d36-9ea5-15057a942f21','9ce330e8-2592-5dc8-9d3e-9af71695fef4','mistake',3,'Using momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('821d4c54-12bf-5d2b-84ef-8fd6d87e4457','655d3484-4dee-55f9-a7f1-4e309792d60c','step',1,'Place a preacher bench about 2 feet in front of a pulley machine.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e61f9118-30e1-528d-af9d-e98ff6c1589d','655d3484-4dee-55f9-a7f1-4e309792d60c','step',2,'Attach a straight bar to the low pulley.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('16a59d74-ded3-57eb-a692-263957d910d0','655d3484-4dee-55f9-a7f1-4e309792d60c','step',3,'Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley. Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b90705f8-1e13-58e9-8d38-31be3033e053','655d3484-4dee-55f9-a7f1-4e309792d60c','step',4,'Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eeb27023-0d67-5702-8c69-2a456b5d2182','655d3484-4dee-55f9-a7f1-4e309792d60c','step',5,'Now slowly lower the weight to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7ac5fd5c-c82f-50a2-93ab-0fdaddbfbc78','655d3484-4dee-55f9-a7f1-4e309792d60c','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e52ef92d-0de8-5ec9-8f80-0e9bfb50abd8','655d3484-4dee-55f9-a7f1-4e309792d60c','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('19dd8455-fcef-5061-b5b4-4cc953018ed4','655d3484-4dee-55f9-a7f1-4e309792d60c','cue',2,'Squeeze at the top','en','ai_authored:pattern');
