INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1c6d1d50-f30e-59a2-b944-ebe0cf1888f7','655d3484-4dee-55f9-a7f1-4e309792d60c','mistake',3,'Cutting the range short','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1c59fb7a-330d-5fd3-a317-b41f096f29d2','45d3406f-f880-5f8f-8add-28ed58ef2306','step',1,'Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b5856972-fb41-5ee4-af69-53910b81add7','45d3406f-f880-5f8f-8add-28ed58ef2306','step',2,'Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52a0a45f-2599-5785-b8bd-942488fcf959','45d3406f-f880-5f8f-8add-28ed58ef2306','step',3,'Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('482b4c97-0b0c-55a7-8723-ac075d34d4c9','45d3406f-f880-5f8f-8add-28ed58ef2306','step',4,'Pause at the end of the motion before returning the handles to the start position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b5267e15-7507-5569-aa4e-bf0b311ffc34','45d3406f-f880-5f8f-8add-28ed58ef2306','cue',1,'Lead with the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f37ca829-c7c8-5f96-b07f-21630d9ab2b4','45d3406f-f880-5f8f-8add-28ed58ef2306','cue',2,'Control the lowering','en','ai_authored:pattern');
