INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c5a585ed-7b5f-5ef8-891e-be5dcfb4a84b','45d3406f-f880-5f8f-8add-28ed58ef2306','mistake',2,'Shrugging the weight up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f7b74596-1426-5621-9a27-8eeff4d34dc1','45d3406f-f880-5f8f-8add-28ed58ef2306','mistake',3,'Going too heavy','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('24921ebc-859b-54ab-8759-f89516e7aebb','6e6afac8-7606-5c75-a475-787bd707f552','step',1,'Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('47a1bd41-3f8a-50fa-b6fc-a19321e94dfa','6e6afac8-7606-5c75-a475-787bd707f552','step',2,'Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5e273aa2-e7ef-5796-858f-2c9493e72d43','6e6afac8-7606-5c75-a475-787bd707f552','step',3,'Bend forward while keeping your back flat and rest your torso on the thighs. Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2515981b-a22d-50fb-a84d-bef2d46238eb','6e6afac8-7606-5c75-a475-787bd707f552','step',4,'While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe1b618e-1085-508c-b408-bc759fe3b26a','6e6afac8-7606-5c75-a475-787bd707f552','step',5,'Slowly lower your arms to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eedcbb53-839c-5b8e-ad01-9d07a99c7657','6e6afac8-7606-5c75-a475-787bd707f552','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('20e2cb69-9c8f-5796-a565-699ef562cdda','6e6afac8-7606-5c75-a475-787bd707f552','cue',1,'Lead with the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('edde88b6-e68d-522c-bbad-8247474935be','6e6afac8-7606-5c75-a475-787bd707f552','cue',2,'Control the lowering','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d3f60e1-0b8a-58b4-a391-1dc008801a8f','6e6afac8-7606-5c75-a475-787bd707f552','cue',3,'Keep shoulders away from ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b817752e-48a5-501f-906e-05497860bc22','6e6afac8-7606-5c75-a475-787bd707f552','mistake',1,'Swinging with the torso','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d09021f7-e436-5d43-ba15-47234c847ddb','6e6afac8-7606-5c75-a475-787bd707f552','mistake',2,'Shrugging the weight up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7526ca50-63df-5e98-8c0a-f414d2f206c4','6e6afac8-7606-5c75-a475-787bd707f552','mistake',3,'Going too heavy','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3d2a3e91-3d0a-53a7-bb60-85e6d72f9ad7','0a1d47d4-3497-5411-9953-fab1b7710c5e','step',1,'Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('67fd2287-caac-5078-a83b-6038cd83957c','0a1d47d4-3497-5411-9953-fab1b7710c5e','step',2,'Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25e7919b-ee4a-5d20-aee1-c5b461d6a5f2','0a1d47d4-3497-5411-9953-fab1b7710c5e','step',3,'Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9971471d-eaae-5d3c-9a4c-cc6781643f15','0a1d47d4-3497-5411-9953-fab1b7710c5e','step',4,'Lower the bar back to the original position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a5157130-8f0a-5765-82e4-b5ae9b1c814e','0a1d47d4-3497-5411-9953-fab1b7710c5e','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d37b592e-2e2f-5d73-b280-191718ae7586','0a1d47d4-3497-5411-9953-fab1b7710c5e','cue',1,'Lift shoulders straight up toward the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37c7cd12-0bab-5842-841c-766581754646','0a1d47d4-3497-5411-9953-fab1b7710c5e','cue',2,'Pause at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('54bc8df3-054e-50ee-9409-074d71d91d4a','0a1d47d4-3497-5411-9953-fab1b7710c5e','cue',3,'Lower slowly','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5bdc48af-f59f-57d1-917f-0a2c190e7dc2','0a1d47d4-3497-5411-9953-fab1b7710c5e','mistake',1,'Rolling the shoulders','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9eb49c38-a8bc-5a66-a4e1-5fe054496a84','0a1d47d4-3497-5411-9953-fab1b7710c5e','mistake',2,'Bending the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e7eab6dd-ef99-5d03-94d4-b17cb8905118','0a1d47d4-3497-5411-9953-fab1b7710c5e','mistake',3,'Jerking the weight','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4d77f2b-77ca-5f04-a6eb-6302ec943187','011a2762-21e5-5d6d-9939-d548dc1d9af2','step',1,'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6afef66e-a2fc-5be6-9eba-c59e4d387d66','011a2762-21e5-5d6d-9939-d548dc1d9af2','step',2,'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea78407f-92e4-5106-8e39-f3f12d6f495d','011a2762-21e5-5d6d-9939-d548dc1d9af2','step',3,'Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f66e2bcf-690e-54ec-9c86-3733caf28978','011a2762-21e5-5d6d-9939-d548dc1d9af2','step',4,'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aeb6f51a-f974-5f87-9c2e-62b7e5567e56','011a2762-21e5-5d6d-9939-d548dc1d9af2','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cd02e529-5ceb-538d-865d-1943d41c31fb','011a2762-21e5-5d6d-9939-d548dc1d9af2','cue',1,'Rise as high as possible onto the balls of the feet','en','ai_authored:pattern');
