INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff3ca947-1ec9-5687-8dd0-e2eb96cecaa0','e79b7a8b-1d8c-5762-9e65-d61082333125','step',3,'Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.','en','source:free_exercise_db');
