INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b21f2ec0-f40c-5ca7-ade6-edf1053e75e3','a6bbc179-22aa-5783-a794-d24691fa136c','step',1,'Move into a prone position on the floor, supporting your weight on your hands and toes.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6574345c-35ba-50f8-914b-adf4809caf3c','a6bbc179-22aa-5783-a794-d24691fa136c','step',2,'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0a26d216-e366-5ae2-be24-c0b573a67e65','a6bbc179-22aa-5783-a794-d24691fa136c','step',3,'Descend by flexing at the elbow, lowering your chest toward the ground.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('390f340d-9d1c-5947-8d41-75c58c4a9a93','a6bbc179-22aa-5783-a794-d24691fa136c','step',4,'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a6e7f8cd-7744-50dd-8e1d-ea33a05320b3','a6bbc179-22aa-5783-a794-d24691fa136c','step',5,'As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6b57b080-15be-5c31-b7d0-5aa6e4bb54b4','a6bbc179-22aa-5783-a794-d24691fa136c','step',6,'Return to the starting position and repeat the exercise, working all the way around until you are back where you started.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c02573d-9bcb-5fdb-b8d2-04126e165ac8','a6bbc179-22aa-5783-a794-d24691fa136c','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
