INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e323e5ed-e303-54ef-b1e6-1dfe2d9a28a5','34e0ff98-254c-5c4a-bc4f-173058609bea','step',1,'Lie on a flat bench with an EZ bar loaded to an appropriate weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3cec5b6a-3e7d-50c8-a48e-13acde56e4ee','34e0ff98-254c-5c4a-bc4f-173058609bea','step',2,'Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3f53da8d-b342-52e6-92f3-061294321fe4','34e0ff98-254c-5c4a-bc4f-173058609bea','step',3,'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2fe39023-1e39-547d-91eb-265e70303960','34e0ff98-254c-5c4a-bc4f-173058609bea','step',4,'Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f41db257-27f4-5ac8-96c7-bb40b878115f','34e0ff98-254c-5c4a-bc4f-173058609bea','step',5,'Repeat.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f2606615-6312-54c3-9d73-d68c3e4d4db7','34e0ff98-254c-5c4a-bc4f-173058609bea','cue',1,'Keep upper arms still','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('16cc8bf7-8dd5-562c-9579-19d0553c03c1','34e0ff98-254c-5c4a-bc4f-173058609bea','cue',2,'Fully straighten the elbow','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('440c3723-95ff-5570-b834-eec49bd6ae22','34e0ff98-254c-5c4a-bc4f-173058609bea','cue',3,'Control the stretch','en','ai_authored:pattern');
