INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a1948014-6cf8-5a56-913b-6577fbd128b0','34e0ff98-254c-5c4a-bc4f-173058609bea','mistake',2,'Moving the shoulders','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80d66608-f0c2-5394-b4f7-30daca7a6dd5','34e0ff98-254c-5c4a-bc4f-173058609bea','mistake',3,'Using momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d130bfd7-419b-504f-9804-cffd3df4b055','57240ac8-2613-5fd7-a530-c64c2e132fea','step',1,'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02d92ff7-503b-5b95-8de0-6a5f4d8fdb5f','57240ac8-2613-5fd7-a530-c64c2e132fea','step',2,'Grab the bar with the palms facing forward using the prescribed grip. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9f07a0ea-3e11-597a-ae06-3a1b5130375f','57240ac8-2613-5fd7-a530-c64c2e132fea','step',3,'As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('66562d4a-6876-5617-99aa-aa16c14af688','57240ac8-2613-5fd7-a530-c64c2e132fea','step',4,'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dec800b0-e6c6-56ad-9445-6a29e72be616','57240ac8-2613-5fd7-a530-c64c2e132fea','step',5,'After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37566233-5bf5-5fea-b590-4a4c56165869','57240ac8-2613-5fd7-a530-c64c2e132fea','step',6,'6. Repeat this motion for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9447889c-867c-5ebd-9b0b-08c7812de30d','57240ac8-2613-5fd7-a530-c64c2e132fea','cue',1,'Start each rep by pulling the shoulder blades down','en','ai_authored:pattern');
