INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f3d7fcce-0ec3-5b93-9260-0aaa6573ba91','861133c6-68b5-577a-bef4-37908a874efc','step',1,'Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8091ea80-7719-560d-811e-554322ccda1c','861133c6-68b5-577a-bef4-37908a874efc','step',2,'To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b1001436-7c79-5339-a0f2-39685198d79d','861133c6-68b5-577a-bef4-37908a874efc','step',3,'After a brief pause, return to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aefdc9e7-5eb9-577a-8e1b-809765fe4360','861133c6-68b5-577a-bef4-37908a874efc','cue',1,'Exhale as you curl up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bacd799d-f907-5ee3-8126-ebde56427f00','861133c6-68b5-577a-bef4-37908a874efc','cue',2,'Move the ribs toward the pelvis','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11ebb7dd-3ffc-51a7-9648-41ea02d9d3a5','861133c6-68b5-577a-bef4-37908a874efc','cue',3,'Keep the neck relaxed','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9da0c6b6-1f52-5122-b76f-31ccdffedc9e','861133c6-68b5-577a-bef4-37908a874efc','mistake',1,'Pulling on the neck','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b86011a9-b9a2-5ea5-9b9b-9cc202dd353c','861133c6-68b5-577a-bef4-37908a874efc','mistake',2,'Using hip flexors/momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aa0590e3-5b47-56e0-88b1-42783b60fc97','861133c6-68b5-577a-bef4-37908a874efc','mistake',3,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f2fa5d8-ce78-5211-a031-4fd8ea0cbfb0','ef22908a-48c8-5371-94f6-abad96f36d87','step',1,'Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea5c1b5f-8b24-57ee-837a-9af5ba3ad238','ef22908a-48c8-5371-94f6-abad96f36d87','step',2,'Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('109263c4-2de5-5dc5-a726-c3fd0b648afd','ef22908a-48c8-5371-94f6-abad96f36d87','step',3,'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('27d0601f-7c5d-594e-a447-4faf0e8d9a8a','ef22908a-48c8-5371-94f6-abad96f36d87','step',4,'Slowly begin to bring the dumbbells back to starting position as your breathe in.','en','source:free_exercise_db');
