INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d86018e3-50a5-5c74-abf0-353d9ddf6863','7b94bd6f-c7b5-50c2-8bb5-fac81c62b33f','step',2,'While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bfed2cc7-06f2-560a-9caf-f4827ffe8529','7b94bd6f-c7b5-50c2-8bb5-fac81c62b33f','step',3,'Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.','en','source:free_exercise_db');
