INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8ca83e5-ec9e-54cb-8586-96f92ab1ccf4','28b6c147-d423-5f32-81b4-875f8db37c76','step',1,'Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b4a3f41f-1948-5cf4-b5f9-ef3b0a92aed1','28b6c147-d423-5f32-81b4-875f8db37c76','step',2,'Now place your hands lightly on either side of your head keeping your elbows in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('890c8d85-70a7-5040-93f7-0f4c981726ff','28b6c147-d423-5f32-81b4-875f8db37c76','step',3,'While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9079b48f-8030-5180-a2e8-a713158020ea','28b6c147-d423-5f32-81b4-875f8db37c76','step',4,'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aff9f4f2-0fc7-54c9-a6a0-f0f76fb936a3','28b6c147-d423-5f32-81b4-875f8db37c76','step',5,'After the one second contraction, begin to come down slowly again to the starting position as you inhale.','en','source:free_exercise_db');
