INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('93cbcf5f-1b95-5aa7-b593-871d16a8d580','069adb1e-6542-5d92-a14b-e01cef6e338f','step',2,'Once you are laying down, move the dumbbells in front of you at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aff71b35-d84f-5ad4-9be1-18c3117b5777','069adb1e-6542-5d92-a14b-e01cef6e338f','step',3,'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d5acdfed-1e25-5279-b972-85a3fdd2d7cb','069adb1e-6542-5d92-a14b-e01cef6e338f','step',4,'Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b1ebadf1-eecd-55cb-8f4b-d1f9d27c7e89','069adb1e-6542-5d92-a14b-e01cef6e338f','step',5,'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('914c8217-54c1-5de1-9004-54ae53006a34','069adb1e-6542-5d92-a14b-e01cef6e338f','step',6,'Repeat the movement for the prescribed amount of repetitions of your training program.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('10aa32e8-042c-5e67-ba13-1c090aa98591','069adb1e-6542-5d92-a14b-e01cef6e338f','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
