INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ae31c15f-f330-59b1-b370-4ba52d591092','ee97a6e5-512b-59c4-9a4b-b54817dddafe','step',1,'Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('30d78a71-7aa2-51af-b820-d18013a34770','ee97a6e5-512b-59c4-9a4b-b54817dddafe','step',2,'Next, lower yourself downward until your chest almost touches the floor as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f4b5b8d7-c7ef-5460-8200-9b34e88018e9','ee97a6e5-512b-59c4-9a4b-b54817dddafe','step',3,'Now breathe out and press your upper body back up to the starting position while squeezing your chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('717819b0-c5af-57c0-b8d1-785f70a827e4','ee97a6e5-512b-59c4-9a4b-b54817dddafe','step',4,'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.','en','source:free_exercise_db');
