INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc424db8-2fa5-5401-85fc-02b60ba661f1','27f03181-7bdc-52ce-a319-fd8b36bfc6a2','step',1,'Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fc0e4f66-7499-5f16-99f3-fa946bf68db7','27f03181-7bdc-52ce-a319-fd8b36bfc6a2','step',2,'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e3667138-2a90-58f3-a7ae-636de0d07d51','27f03181-7bdc-52ce-a319-fd8b36bfc6a2','step',3,'Lower the bar by bending at the hips and guiding it to the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5b5c7d72-069e-5c06-8cae-5b7d6b4b468f','27f03181-7bdc-52ce-a319-fd8b36bfc6a2','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4a693ddc-c837-54a9-94ea-d00d8b177252','27f03181-7bdc-52ce-a319-fd8b36bfc6a2','cue',2,'Keep the weight close to your legs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6ee7b2f0-8ed3-574e-adfd-71df690597b9','27f03181-7bdc-52ce-a319-fd8b36bfc6a2','cue',3,'Neutral spine from head to hips','en','ai_authored:pattern');
