INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9e00d73b-3677-5bc7-896d-e0eaa3f6f251','d7af6cfa-72c9-5e3a-af98-912692ef2d3f','step',1,'Sit securely in a dip machine, select the weight and firmly grasp the handles.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6fdab3ca-4014-540a-aa8e-133258eb152f','d7af6cfa-72c9-5e3a-af98-912692ef2d3f','step',2,'Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69ea2198-024c-5d93-8a0c-b81c68482ebf','d7af6cfa-72c9-5e3a-af98-912692ef2d3f','step',3,'As you contract the triceps, extend your arms downwards as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('29ab821e-a0df-5383-9d90-53b62435f24f','d7af6cfa-72c9-5e3a-af98-912692ef2d3f','step',4,'Now slowly let your arms come back up to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('79df2d4e-c4f3-5d72-9943-2d737c7b635b','d7af6cfa-72c9-5e3a-af98-912692ef2d3f','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
