INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0483353c-ec6d-5120-b236-dc683ced9374','83c8cf70-9761-546b-9bf3-6d047481d4a8','step',1,'For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('744ad62d-1560-5f29-bb94-f9966689856b','83c8cf70-9761-546b-9bf3-6d047481d4a8','step',2,'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0fc3c20b-2bc8-52b6-8688-99cf0651c516','83c8cf70-9761-546b-9bf3-6d047481d4a8','step',3,'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out.','en','source:free_exercise_db');
