INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e7fdac1f-d668-587b-8bd5-39443da93b2d','3de2802e-c564-5664-a404-e765f7f8a3a6','step',1,'To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f0f9148-7e59-5ae0-88a4-3d868887c421','3de2802e-c564-5664-a404-e765f7f8a3a6','step',2,'Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('585a3b26-5650-56bb-a40b-f06bd6f25848','3de2802e-c564-5664-a404-e765f7f8a3a6','step',3,'Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1a15b30a-e682-5e61-8ab7-4ef9339c04fb','3de2802e-c564-5664-a404-e765f7f8a3a6','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
