INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('863b89aa-c17d-5b61-bfc6-981912ae4f58','3de2802e-c564-5664-a404-e765f7f8a3a6','cue',2,'Fully straighten the elbow','en','ai_authored:pattern');
