INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0decf27a-446f-5ca6-956f-b25156bc4abc','3de2802e-c564-5664-a404-e765f7f8a3a6','mistake',3,'Using momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('edf26d7d-1840-5b83-b3db-a5a6124a6044','98da6598-f147-5a82-ad16-229ec533cd31','step',1,'For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('40f02e84-33ed-523b-b334-8af3877875a3','98da6598-f147-5a82-ad16-229ec533cd31','step',2,'Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c47607f-6050-5049-83eb-e6641c6dc10d','98da6598-f147-5a82-ad16-229ec533cd31','step',3,'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f5a1add9-9472-594e-bb01-24df38ced4f3','98da6598-f147-5a82-ad16-229ec533cd31','step',4,'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9f37a8ac-d7be-565a-8332-4064299eed8b','98da6598-f147-5a82-ad16-229ec533cd31','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0fdfe79b-3d2d-5883-93d3-6c46e927cc48','98da6598-f147-5a82-ad16-229ec533cd31','cue',1,'Rise as high as possible onto the balls of the feet','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d7135e39-c094-54d3-8f1d-c440f2e7f021','98da6598-f147-5a82-ad16-229ec533cd31','cue',2,'Pause at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('45ee2815-8ee3-50b1-86c8-34a50dfa6feb','98da6598-f147-5a82-ad16-229ec533cd31','cue',3,'Lower fully into a stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('49dd84df-de12-5d4e-82d4-3d6e7ed9936c','98da6598-f147-5a82-ad16-229ec533cd31','mistake',1,'Bouncing at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c5ee9f56-521d-5b44-b896-26faa2342be1','98da6598-f147-5a82-ad16-229ec533cd31','mistake',2,'Bending the knees to cheat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('83f927e8-212c-5a6c-a255-b788a5a7b9c5','98da6598-f147-5a82-ad16-229ec533cd31','mistake',3,'Short range of motion','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c9daedf-9025-5eed-9f75-bb82746c9554','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','step',1,'Begin standing with your knees slightly bent.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25bbae27-816f-5340-bad9-0c74b0c560a3','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','step',2,'Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ddb5577f-a6ed-58aa-b859-001ade679408','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','step',3,'As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0631edb0-9c2a-5d8b-980f-575269c56108','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','step',4,'Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('135b49a4-1320-5534-b5eb-a9921fb7fafe','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','cue',1,'Land softly on the balls of the feet','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e4609690-0279-59fe-bdc7-dd33a2dd520d','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','cue',2,'Knees track over toes on landing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('03bd03c5-d3b4-5dda-b4ae-814fe7a0ef2e','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','cue',3,'Reset between reps if needed','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b8d2a111-576e-5ecb-bd80-f7101cad8e0d','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','mistake',1,'Stiff-legged landings','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c3ba1837-4e4d-5bf4-9ab2-0cf39807fbc6','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','mistake',2,'Knees caving on landing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7db2e4d6-b937-55d0-899f-0a1f2ec1dafd','0001b24c-fd72-5efb-a3b5-b646b8ccca1b','mistake',3,'Continuing when tired','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('22613a82-aad8-5344-bec7-9d9520b6dba6','a4ec4b6b-5a00-5338-bce6-22db27272a75','step',1,'Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44791999-7fa5-5989-9b19-19447ef46132','a4ec4b6b-5a00-5338-bce6-22db27272a75','step',2,'As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Also, do not lift your shoulders.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('010e82e0-1ea2-544e-894f-26e29706b74a','a4ec4b6b-5a00-5338-bce6-22db27272a75','step',3,'Slowly go back to the starting position as you keep the bar in contact with the torso at all times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2cdeeac0-3453-5dd8-9b7a-1e6d5d0569df','a4ec4b6b-5a00-5338-bce6-22db27272a75','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('271d95ee-15c1-59ac-a92e-1590536900be','a4ec4b6b-5a00-5338-bce6-22db27272a75','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a1d09267-1c1a-5f80-8207-7eb248b4b7fa','a4ec4b6b-5a00-5338-bce6-22db27272a75','cue',2,'Squeeze at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c0ab7452-47d2-5092-bb81-786e4b6d87b7','a4ec4b6b-5a00-5338-bce6-22db27272a75','cue',3,'Lower all the way under control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9f3bf2d-886c-5015-bf02-418f9a3f0036','a4ec4b6b-5a00-5338-bce6-22db27272a75','mistake',1,'Swinging the body','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('054ef134-70ad-52c6-b208-8fbfe3a22065','a4ec4b6b-5a00-5338-bce6-22db27272a75','mistake',2,'Elbows drifting forward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37f5eb04-a44f-5f09-9374-7137010b4ec9','a4ec4b6b-5a00-5338-bce6-22db27272a75','mistake',3,'Cutting the range short','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac70566f-e011-564a-83e3-2e7f1a0cadb0','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',1,'Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e0727ad6-ad2c-5bec-bc20-b5cef5b32f16','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',2,'While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d5e8e330-ab5b-5064-a4a3-d2c12b6f2ec9','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',3,'Slowly begin to bring the dumbbell back to the starting position as your breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f0942a2-1c5f-5e82-880d-efa72850ebe8','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',4,'Repeat the movement with the left hand. This equals one repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35196a0c-da69-59a4-9be8-a2169beb2fc6','ad4e4734-fcae-5d77-920e-1a483624bd5d','step',5,'Continue alternating in this manner for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('39561a79-d57c-5224-93ef-044a9d154e84','ad4e4734-fcae-5d77-920e-1a483624bd5d','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4f568e6d-af6c-5eb7-95ef-84e64977ffb2','ad4e4734-fcae-5d77-920e-1a483624bd5d','cue',2,'Squeeze at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be3e47b9-c16c-5cd5-aca3-c9eafc7dc08b','ad4e4734-fcae-5d77-920e-1a483624bd5d','cue',3,'Lower all the way under control','en','ai_authored:pattern');
