INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('70095115-fc34-5ecf-8a82-abfa09482650','51b19b04-8533-505a-bd4a-adcde93eb7b8','step',1,'Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b21f98ba-461f-5332-9723-3b36ad604153','51b19b04-8533-505a-bd4a-adcde93eb7b8','step',2,'Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fc24f2f8-edf4-55f6-8e0c-a8766929532f','51b19b04-8533-505a-bd4a-adcde93eb7b8','step',3,'Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f8a403b4-be4c-564d-9827-d30a5a13d444','51b19b04-8533-505a-bd4a-adcde93eb7b8','step',4,'Pause, then extend the elbow and return to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be7453d0-35b1-574e-a3aa-95f61022ebe8','51b19b04-8533-505a-bd4a-adcde93eb7b8','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
