INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dd735708-a7ab-51c2-8101-bac79b399a4d','51b19b04-8533-505a-bd4a-adcde93eb7b8','mistake',2,'Bouncing off the chest','en','ai_authored:pattern');
