INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('47f1b496-2a6a-5180-b92d-8d45b37c8677','b612db81-9565-5e78-991b-daf2be053e4e','step',2,'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.','en','source:free_exercise_db');
