INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0a3f6ef7-4787-558a-a758-c8a0943c9272','d92cbc12-13be-5e12-8cb7-2eae6d69fd56','step',1,'Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('47adaee4-1af5-5ebd-82ef-a9f0d7a851d5','d92cbc12-13be-5e12-8cb7-2eae6d69fd56','step',2,'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2e311187-6982-5f54-b262-2127a789b7be','d92cbc12-13be-5e12-8cb7-2eae6d69fd56','step',3,'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','en','source:free_exercise_db');
