INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7668f1a3-e84e-54f6-b9c4-1b3ce843562f','eae24e89-2d29-5834-837d-c2deae29b79f','step',2,'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0ae0f097-5aa9-5fc6-ac71-16a060cc6e9c','eae24e89-2d29-5834-837d-c2deae29b79f','step',3,'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3440914d-e976-5e25-a66a-2eae654dc68f','eae24e89-2d29-5834-837d-c2deae29b79f','step',4,'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.','en','source:free_exercise_db');
