INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b786c653-34f6-581e-a879-d9b58911b0e5','8d67f8f7-b2f8-5fce-ab1d-ea9cb83d8cd3','step',3,'Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5e84395d-fecd-536b-8da3-709a27b42887','8d67f8f7-b2f8-5fce-ab1d-ea9cb83d8cd3','step',4,'Repeat 5-10 times, increasing speed as you do so.','en','source:free_exercise_db');
