INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('810389d8-d471-59e2-8eb8-7334bb76ac05','bd7ae998-245c-5d94-9060-aa8ad9728019','step',1,'Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8b6a3a07-96ce-5a43-ae3d-24bac58f61f8','bd7ae998-245c-5d94-9060-aa8ad9728019','step',2,'Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87f01815-bb27-54ee-98ea-6066845b3b50','bd7ae998-245c-5d94-9060-aa8ad9728019','step',3,'Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.','en','source:free_exercise_db');
