INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d518ffd6-e092-51db-bbea-f08718749025','09d7be1a-85c2-521a-90bb-494e0284e618','step',1,'Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('33e7b0f4-7af5-5790-b3a0-6fcebedb3bd9','09d7be1a-85c2-521a-90bb-494e0284e618','step',2,'Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7abfb0e1-bdc6-5521-bb7d-1030945a7f22','09d7be1a-85c2-521a-90bb-494e0284e618','step',3,'Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1df4303a-79bb-54f4-9f74-cf86277bf688','09d7be1a-85c2-521a-90bb-494e0284e618','step',4,'Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7f4e868e-c002-570d-8aae-6982baccf0e0','09d7be1a-85c2-521a-90bb-494e0284e618','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('df071d2a-0308-58c8-976a-dcd25db7a99b','09d7be1a-85c2-521a-90bb-494e0284e618','cue',2,'Lower the back knee straight down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6fb1d94a-b514-5b4f-acf0-8a3589f1afa8','09d7be1a-85c2-521a-90bb-494e0284e618','cue',3,'Keep your torso tall','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f7370a90-9915-5dee-85a0-c1e94db2ea5f','09d7be1a-85c2-521a-90bb-494e0284e618','mistake',1,'Front knee collapsing inward','en','ai_authored:pattern');
