INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c92a8cd-700e-5f93-bd0c-dec877cf3042','09d7be1a-85c2-521a-90bb-494e0284e618','mistake',3,'Short, choppy steps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f23827a8-46e3-5ae8-b99b-5c37ee0c5e4a','34001892-c69e-5413-bdc1-ca9b407d0a0f','step',1,'Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9133e961-0986-56ea-8b18-a5ce6169f9c0','34001892-c69e-5413-bdc1-ca9b407d0a0f','step',2,'Place it on the seat of the cable row machine.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6088f569-03d2-55cd-ae3b-0c5857045c3f','34001892-c69e-5413-bdc1-ca9b407d0a0f','step',3,'Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the V-bar handles.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1ab8fae0-fe72-5234-8468-5691944f81ae','34001892-c69e-5413-bdc1-ca9b407d0a0f','step',4,'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a2bd65aa-4ac6-5568-81c9-b6c78ab08863','34001892-c69e-5413-bdc1-ca9b407d0a0f','step',5,'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9c2ed269-985a-5f26-adb3-c810b8d42ada','34001892-c69e-5413-bdc1-ca9b407d0a0f','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c25debf-70e8-5a73-8460-e78b4d2a38fb','34001892-c69e-5413-bdc1-ca9b407d0a0f','cue',1,'Pull with the elbows, not the hands','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52cf5d39-1d58-5e5b-97f5-c358a7da250a','34001892-c69e-5413-bdc1-ca9b407d0a0f','cue',2,'Squeeze shoulder blades together','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('62cd3d10-f8a3-5c5c-8f9b-920155803944','34001892-c69e-5413-bdc1-ca9b407d0a0f','cue',3,'Keep the torso still','en','ai_authored:pattern');
