INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3b85a990-cd73-5b5c-8036-ff2c8601d20c','1d210f1c-7e1f-51f8-9610-758b414c38dd','step',2,'Start moving at an easy pace for a warm-up.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35c9d62e-5edc-5e64-945b-ff70c6dc7006','1d210f1c-7e1f-51f8-9610-758b414c38dd','step',3,'Increase resistance or pace to the planned effort, keeping an upright posture.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fb6a35af-0222-5c1a-ad7f-df0cf203bfd3','1d210f1c-7e1f-51f8-9610-758b414c38dd','step',4,'Cool down at an easy pace.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('38b8a7e9-0f8b-510f-a122-b3fe6e8e6989','1d210f1c-7e1f-51f8-9610-758b414c38dd','cue',1,'Start with a 5-minute easy warm-up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b94fb573-a9a9-53f5-8b9e-7d08e7648cfd','1d210f1c-7e1f-51f8-9610-758b414c38dd','cue',2,'Keep a pace where you can speak in short sentences (moderate)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9058e9fe-c0e7-59b2-9919-6b1ff363e1ef','1d210f1c-7e1f-51f8-9610-758b414c38dd','cue',3,'Relax shoulders and keep good posture','en','ai_authored:pattern');
