INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('41d2a240-3849-59c6-8c12-7ccbf7f8f1e0','1d210f1c-7e1f-51f8-9610-758b414c38dd','mistake',2,'Holding the handrails (machines)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a65a4f57-15b2-5ce2-98a8-6d3696820b05','1d210f1c-7e1f-51f8-9610-758b414c38dd','mistake',3,'Skipping the cool-down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9c6dd569-b848-546a-bc3b-9dd9cf4973e7','df93181c-5b1f-539d-9208-d9b4c8e96d9f','step',1,'Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('36d6235d-4742-53a1-bd66-2277f3995133','df93181c-5b1f-539d-9208-d9b4c8e96d9f','step',2,'Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('55120f4e-1806-5483-baa1-d0834ba84352','df93181c-5b1f-539d-9208-d9b4c8e96d9f','step',3,'With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1afd6684-71b1-5dbb-b361-82f2a4aead65','df93181c-5b1f-539d-9208-d9b4c8e96d9f','step',4,'As you inhale, go back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0797d64b-e1f0-50b9-8f6f-d7265dc47148','df93181c-5b1f-539d-9208-d9b4c8e96d9f','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e387498e-3e49-506f-925f-4231bcb9ddc0','df93181c-5b1f-539d-9208-d9b4c8e96d9f','cue',1,'Exhale as you curl up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('36036abb-9410-5d73-ad5e-709600ac81fa','df93181c-5b1f-539d-9208-d9b4c8e96d9f','cue',2,'Move the ribs toward the pelvis','en','ai_authored:pattern');
