INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('debb4084-cb7c-5547-bf53-9292b8c14add','d4704777-c68d-54bc-869a-edae8f7317db','step',2,'Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2e389c77-553d-50e6-969b-21057ab4cdcf','d4704777-c68d-54bc-869a-edae8f7317db','step',3,'Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.','en','source:free_exercise_db');
