INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('88cd9808-b5b4-530a-b32f-1c07aa2f9fa5','cc2b6ccf-7880-54a5-b204-611bfc0d7917','step',2,'Lay flat on the bench and keep your feet on the ground.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0388e433-b2e4-5d2b-892c-6ae56bac0dbd','cc2b6ccf-7880-54a5-b204-611bfc0d7917','step',3,'Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip. Extend your arms by your side with a slight bend on your elbows. Your arms should be parallel to the floor. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('00b03776-7326-589a-b90a-c29b4845fb2b','cc2b6ccf-7880-54a5-b204-611bfc0d7917','step',4,'Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('df42bb6d-5f03-5626-9fb3-b696b23263f8','cc2b6ccf-7880-54a5-b204-611bfc0d7917','step',5,'Slowly come back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a45981ae-97ee-5df3-bf91-4672af6a8f39','cc2b6ccf-7880-54a5-b204-611bfc0d7917','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
