INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fb225b2a-c9ba-54d3-b220-d13b41470a6d','3b8264f9-4b27-595e-8de7-2aefeaa811f6','step',1,'On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e3fabcac-ff72-518e-8dbd-ab6a3548d0d8','3b8264f9-4b27-595e-8de7-2aefeaa811f6','step',2,'Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a2e88aa8-fc13-52f6-a961-aabd62f82657','3b8264f9-4b27-595e-8de7-2aefeaa811f6','step',3,'Start the movement by lifting the left leg higher than the right leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b4eae4c6-d9be-5d89-9116-2f6b4b16e738','3b8264f9-4b27-595e-8de7-2aefeaa811f6','step',4,'Then lower the left leg as you lift the right leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('90ac4d7a-c720-5cd0-994b-03c88968b62c','3b8264f9-4b27-595e-8de7-2aefeaa811f6','step',5,'Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times.','en','source:free_exercise_db');
