INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7a6b5baa-0825-5c00-ae6a-6bec4238ed8e','a08f6479-0a45-5afa-be42-080a8cbe8673','step',2,'With your head up and your back straight, position your feet at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bfc7bd33-f7ca-5395-826b-ce05640b32c9','a08f6479-0a45-5afa-be42-080a8cbe8673','step',3,'Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6323be38-b35d-53ec-8fd0-639ee30e845b','a08f6479-0a45-5afa-be42-080a8cbe8673','step',4,'Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d138cb83-28dd-5c67-9f78-4a36279fbe5b','a08f6479-0a45-5afa-be42-080a8cbe8673','step',5,'When you touch the floor again, immediately squat down and jump again.','en','source:free_exercise_db');
