INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bc68a0f6-35e4-5a66-bfd0-661397fa0957','a73cf1ff-7dbf-5e74-8abd-b3b7454523f9','step',2,'Perform a short squat in preparation for jumping, swinging your arms behind you.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3522ccb7-4e1c-54ce-8f00-7461274d58a2','a73cf1ff-7dbf-5e74-8abd-b3b7454523f9','step',3,'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8f1e1aa-c830-5d4c-999c-e45ebd91fa82','a73cf1ff-7dbf-5e74-8abd-b3b7454523f9','step',4,'Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.','en','source:free_exercise_db');
