INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8eed73f7-ef13-5036-bc61-61063f8eb59b','ac296d55-c143-596f-9aab-d193687c2efa','step',1,'Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('51f0c2e6-44bc-5992-abed-5f2b9e2f93ed','ac296d55-c143-596f-9aab-d193687c2efa','step',2,'Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bb1a8c79-e298-51d0-86b6-783941f350a4','ac296d55-c143-596f-9aab-d193687c2efa','step',3,'While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('127c9ab4-f78f-5b71-a9e0-735f48ea1584','ac296d55-c143-596f-9aab-d193687c2efa','step',4,'Now as you inhale lower the arm back down slowly to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d9788a04-6310-50c8-a41e-3aa50d4efea5','ac296d55-c143-596f-9aab-d193687c2efa','step',5,'Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.','en','source:free_exercise_db');
