INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11aafa8d-4f95-5074-9534-b0442ce3f9c5','c69bc829-7b12-5447-8337-e142eab0744c','step',2,'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74e2d36b-7391-52f7-8a0c-2d3de18ee190','c69bc829-7b12-5447-8337-e142eab0744c','step',3,'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.','en','source:free_exercise_db');
