INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f658aaf9-a759-5f51-9c5a-ae481d277bf3','9d908936-3789-52ae-bc5e-18decca9b53e','step',1,'While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. This will be your starting position.','en','source:free_exercise_db');
