INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5ce09b4b-600b-5ae0-9af3-72c089a2106a','0e202853-3fd1-5c5e-8250-3e1988bf5437','step',2,'Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('31423118-ecd4-5f0c-afad-30cea90e4360','0e202853-3fd1-5c5e-8250-3e1988bf5437','step',3,'Rise back up by driving through your heels and repeat.','en','source:free_exercise_db');
