INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5989f187-731c-5138-8377-531d4b1a1531','15543365-d05e-5dde-9ed5-eaa0a7eaff03','step',2,'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d04e988b-c53c-552c-afda-b4bda4657b6f','15543365-d05e-5dde-9ed5-eaa0a7eaff03','step',3,'Return to the starting position, keeping your descent under control.','en','source:free_exercise_db');
