INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a78e098e-cfe4-50b0-b016-37a86c6ca248','03943bf1-62cf-5e5d-8b8e-89363dc95e73','step',1,'Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c426f62-41ec-5fbe-97a7-e2e7f6d7c65b','03943bf1-62cf-5e5d-8b8e-89363dc95e73','step',2,'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc5d1679-62bb-584b-b1a6-d8183e268da9','03943bf1-62cf-5e5d-8b8e-89363dc95e73','step',3,'Go back to the initial position as you inhale and now repeat with the left leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25991ede-c3fd-59fb-a900-a244454fda0c','03943bf1-62cf-5e5d-8b8e-89363dc95e73','step',4,'Continue to alternate legs until all of the recommended repetitions have been performed.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9032c8c7-9bde-526b-a008-2f51ecd3890a','03943bf1-62cf-5e5d-8b8e-89363dc95e73','cue',1,'Move slowly and under control','en','ai_authored:pattern');
