INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f0852daa-32d2-582d-a04e-6499cf0befd8','d5ffd4b6-d501-5f65-92cd-0df364b8364f','step',1,'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4335675d-1b91-508d-b69d-dadde3678344','d5ffd4b6-d501-5f65-92cd-0df364b8364f','step',2,'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('79640761-2a7b-5cbd-99e9-df5d51e8a562','d5ffd4b6-d501-5f65-92cd-0df364b8364f','step',3,'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position). Now straighten your legs without locking the knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0bbec5c3-2f7c-5fda-8484-ea79556eb214','d5ffd4b6-d501-5f65-92cd-0df364b8364f','step',4,'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6bdb0be2-8482-5e93-ba37-899d311b056c','d5ffd4b6-d501-5f65-92cd-0df364b8364f','step',5,'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9cd5c03-9375-58fd-9c7e-e9eea66f9e5c','d5ffd4b6-d501-5f65-92cd-0df364b8364f','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
