INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('499af3a8-7904-5e67-9d44-815219725ff5','d5ffd4b6-d501-5f65-92cd-0df364b8364f','cue',2,'Knees track over your toes','en','ai_authored:pattern');
