INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('54ccc465-3fe4-5498-a4da-fc0cfa6b69e2','f44b00c6-c230-575d-9ffa-d5d8d9177fa9','step',1,'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('67df0157-6490-5d80-859c-78b054de1f23','f44b00c6-c230-575d-9ffa-d5d8d9177fa9','step',2,'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6305df0e-d40a-5268-b2a9-8f65080f6352','f44b00c6-c230-575d-9ffa-d5d8d9177fa9','step',3,'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position. Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9330c09c-6090-5e96-8463-ccce5d4f92f7','f44b00c6-c230-575d-9ffa-d5d8d9177fa9','step',4,'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d3eb49a-e4cc-5cf7-97f9-f9e036a590e7','f44b00c6-c230-575d-9ffa-d5d8d9177fa9','step',5,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c361e602-58c1-5c6b-a19e-7e5c5ae032a2','f44b00c6-c230-575d-9ffa-d5d8d9177fa9','step',6,'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.','en','source:free_exercise_db');
