INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dabc41b8-1172-50d0-990f-f88a6ecc1b9c','19e130ae-4bf6-5df5-81ae-1ac1c5c61383','step',3,'Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.','en','source:free_exercise_db');
