INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80075622-262b-532b-9379-49c34f738503','76675db3-643d-52f9-ae58-9cf0213c1ee7','step',3,'Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.','en','source:free_exercise_db');
