INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('028f9145-c7b1-5089-8b00-acdbf322b2a3','1eaf317d-2f5f-5bfb-870a-b76d6330d263','step',2,'Hold your arms under the knees, not over (that would put to much pressure on your knee joints).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('140da18d-0492-50f1-88d8-271422311923','1eaf317d-2f5f-5bfb-870a-b76d6330d263','step',3,'Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles.','en','source:free_exercise_db');
