INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('14971eb9-0495-59e3-9351-80e4d4e9ad43','b0a0cb8b-619a-5d12-b89f-2ebd6c20a8e1','step',1,'Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('767e23e9-1f55-5c66-af4e-1dfec8da4d5e','b0a0cb8b-619a-5d12-b89f-2ebd6c20a8e1','step',2,'Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('911e330f-26b6-551a-8ed3-8b490d7979b7','b0a0cb8b-619a-5d12-b89f-2ebd6c20a8e1','step',3,'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('76cc76c2-0ed8-5387-bbf0-98fcd94d2a16','b0a0cb8b-619a-5d12-b89f-2ebd6c20a8e1','step',4,'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('08a93038-9124-5a76-b2be-b839432b090d','b0a0cb8b-619a-5d12-b89f-2ebd6c20a8e1','step',5,'Slowly raise your torso back to the initial position as you inhale. Also, do not swing the torso at any time in order to protect the back from injury.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5a092860-feb9-5fb7-ab1d-7088da518cc0','b0a0cb8b-619a-5d12-b89f-2ebd6c20a8e1','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
