INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d51035dd-3cd0-5fd4-8665-f65da79a6870','0212971f-39ea-5755-a7e3-53c91b7d076e','step',2,'Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8fdc7c3f-2952-5fb8-bb9f-a7f2079983d0','0212971f-39ea-5755-a7e3-53c91b7d076e','step',3,'Keep going until your body is parallel to the ground in a pushup position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4e028112-7967-53a8-a119-ee8f3a81a856','0212971f-39ea-5755-a7e3-53c91b7d076e','step',4,'Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9c50bdc3-f686-5e6f-897a-c08fa20e3b71','0212971f-39ea-5755-a7e3-53c91b7d076e','step',5,'Continue walking until your feet are by hour hands, keeping your legs straight as you do so.','en','source:free_exercise_db');
