INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0337379d-a825-5328-be71-b5bea2b8615c','6214ce32-c8f7-5fce-9d9c-71d5383d49eb','step',2,'Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ed1762f4-94b1-5549-bfe8-ff931d65db9c','6214ce32-c8f7-5fce-9d9c-71d5383d49eb','step',3,'With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44a4643c-cf01-5008-9141-f6d96c4fa099','6214ce32-c8f7-5fce-9d9c-71d5383d49eb','step',4,'With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. The movement should only occur at the shoulder joint.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('157e5a84-4419-5bc5-a04b-84c162d8c5f8','6214ce32-c8f7-5fce-9d9c-71d5383d49eb','step',5,'Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('080cd68a-71f7-5589-a93f-71d9a99e3470','6214ce32-c8f7-5fce-9d9c-71d5383d49eb','step',6,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
