INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bfbdcadf-8929-5084-ba71-386b2c99a0a3','c6c653da-eb56-5a00-b17a-77765b19bbc3','step',3,'Now rotate the wrists so that the palms of your hands are facing you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('950ffba0-4c7e-56d0-a7fd-acefd6003e8d','c6c653da-eb56-5a00-b17a-77765b19bbc3','step',4,'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('91811c17-a703-5a8b-9a26-d46ba67a28d7','c6c653da-eb56-5a00-b17a-77765b19bbc3','step',5,'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. There is no motion that happens at the elbow joint.','en','source:free_exercise_db');
