INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07843ea1-78ea-5e00-8f83-2dbfd925179b','971aa71f-9f87-53f1-912d-6dfbf3576d79','step',2,'Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.','en','source:free_exercise_db');
