INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0730ce58-9b02-5627-884d-3cc0e1f193a2','971aa71f-9f87-53f1-912d-6dfbf3576d79','cue',2,'Wrists stacked over elbows','en','ai_authored:pattern');
