INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9901be4b-aa70-51fc-b0db-32fc22b29468','fafd2277-644a-5b02-8c62-07e4e35f3d18','step',2,'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.','en','source:free_exercise_db');
