INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a6edb6f5-1826-523c-b383-71e56154c68a','04a96b3d-6263-501c-82a6-c91afbe63d9c','step',2,'As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. The upper torso should be off the floor.','en','source:free_exercise_db');
