INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fc3dcfe7-077b-5175-9b57-26e05cc7298f','e0bf6eea-c8d9-57bb-a5a9-51dda9ee6673','step',1,'Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2fed619-1076-539d-8ace-44616bc5432f','e0bf6eea-c8d9-57bb-a5a9-51dda9ee6673','step',2,'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5cb5104a-e35f-5f95-8308-ad6bac247f5c','e0bf6eea-c8d9-57bb-a5a9-51dda9ee6673','step',3,'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('79679d2c-fb16-5bd9-a12f-fa9e8cc5bc42','e0bf6eea-c8d9-57bb-a5a9-51dda9ee6673','step',4,'Now go back to the starting position and start over.','en','source:free_exercise_db');
