INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e0619607-1f75-55e0-940b-e5664844ffda','3752c8fb-dd6c-541c-8180-96712baa596e','step',4,'Reverse the motion to swing the weight all the way to the opposite side.','en','source:free_exercise_db');
