INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('64c2a8c7-b90f-54cd-b018-02d41f292215','64ef3d80-f4b3-5ea2-bc2c-fe1f203fdada','step',2,'Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.','en','source:free_exercise_db');
