INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b6a3c00d-0434-5c3d-b859-9aed2aefe293','64ef3d80-f4b3-5ea2-bc2c-fe1f203fdada','step',4,'Upon landing, immediately push off in the opposite direction, returning to your original start position.','en','source:free_exercise_db');
