INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('052f49a5-88ca-53c0-875c-bb3af80fb6f2','64ef3d80-f4b3-5ea2-bc2c-fe1f203fdada','cue',3,'Reset between reps if needed','en','ai_authored:pattern');
