INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a28a04b-ec3d-5b22-b578-ee262bb5cc87','e00f945e-2623-503b-b0b4-af8f45866049','step',1,'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4270aaaf-db4e-511c-90d5-71f449985a4b','e00f945e-2623-503b-b0b4-af8f45866049','step',2,'Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Also, keep your torso stationary and pause for a second at the top of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aaaae73b-ab53-52d8-ae26-1437e20d4ef8','e00f945e-2623-503b-b0b4-af8f45866049','step',3,'Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0833fd7d-0591-5dba-83ba-11434bd7dc77','e00f945e-2623-503b-b0b4-af8f45866049','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
