INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f25a9766-dc88-5dcd-9fd1-75ef5e03f973','11ee914f-9392-5ffc-a777-e6b65b7be26d','mistake',3,'Rounding the back','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9c38c03a-058a-51ee-acc8-f02438299ff8','1f2e6f34-41a3-5e54-93c8-bd893d28949d','step',1,'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ff256cc-58a7-59dd-a43f-5f74cf0a35cb','1f2e6f34-41a3-5e54-93c8-bd893d28949d','step',2,'Press the handles upward by extending through the elbow.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('12a6dad9-3225-5e9c-9058-447bb50d8928','1f2e6f34-41a3-5e54-93c8-bd893d28949d','step',3,'After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('522e5ae4-5a51-5133-b4a9-22500bff947d','1f2e6f34-41a3-5e54-93c8-bd893d28949d','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d5426039-7962-5a46-b726-676b2f3b73e9','1f2e6f34-41a3-5e54-93c8-bd893d28949d','cue',2,'Press in a straight line overhead','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('887f51ea-73fe-5eea-a250-b5dc2e9a36fe','1f2e6f34-41a3-5e54-93c8-bd893d28949d','cue',3,'Finish with biceps near the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('33c480e2-3e96-529a-bfdf-94f3a6e6b4ae','1f2e6f34-41a3-5e54-93c8-bd893d28949d','mistake',1,'Excessive lower-back arch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1ebe1fc9-b576-573b-8815-5b80fc893ed5','1f2e6f34-41a3-5e54-93c8-bd893d28949d','mistake',2,'Pressing forward instead of up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f6a04fa8-f431-5693-aa3d-bbbcbedea2bb','1f2e6f34-41a3-5e54-93c8-bd893d28949d','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('696467a8-8da1-5bac-aa9c-c25e3b6db954','e0acc087-db15-5ddb-b664-939559c76830','step',1,'To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a02da8dd-b490-59be-ad57-b256826ed804','e0acc087-db15-5ddb-b664-939559c76830','step',2,'Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('971c2407-3c2a-5ca4-af9b-8ecc86a15a62','e0acc087-db15-5ddb-b664-939559c76830','step',3,'With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e31df4f7-38e3-5e05-baf6-fb14c15cd5a4','e0acc087-db15-5ddb-b664-939559c76830','step',4,'Return your arms back to the starting position after a brief pause.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cbb60773-988d-5922-887f-1edfd437b0cb','e0acc087-db15-5ddb-b664-939559c76830','cue',1,'Keep a slight bend in the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b55c973f-1a1e-53e0-8179-50fdff642564','e0acc087-db15-5ddb-b664-939559c76830','cue',2,'Move in a wide arc','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('743791a9-ecf5-52b1-9871-cb9b7270ad8c','e0acc087-db15-5ddb-b664-939559c76830','cue',3,'Squeeze the chest at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('55a3e638-3e7a-5b56-bdac-e9d46c9baed0','e0acc087-db15-5ddb-b664-939559c76830','mistake',1,'Bending elbows into a press','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dfbead8b-7ce1-5b2d-899a-64dfeec6cef2','e0acc087-db15-5ddb-b664-939559c76830','mistake',2,'Going too deep and straining the shoulder','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('76738bd9-513a-5d12-9839-60149244eaa2','e0acc087-db15-5ddb-b664-939559c76830','mistake',3,'Using too much weight','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('86769fe7-a044-5336-832a-0d5ef79fc206','635e566c-21f1-5577-aa0d-be82eb15f7c4','step',1,'Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1ad7cc05-4ebe-5da9-bcc8-187661dd277c','635e566c-21f1-5577-aa0d-be82eb15f7c4','step',2,'As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0445cc6a-1560-578c-919a-e20b902b55ab','635e566c-21f1-5577-aa0d-be82eb15f7c4','step',3,'At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e27513f8-be84-51e6-b8c2-4fa9590d3cfe','635e566c-21f1-5577-aa0d-be82eb15f7c4','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a2432ade-f31a-584a-b35d-14afbf13d35c','635e566c-21f1-5577-aa0d-be82eb15f7c4','cue',1,'Keep upper arms still','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1c5422ca-b048-53a5-8422-6db5394b0e21','635e566c-21f1-5577-aa0d-be82eb15f7c4','cue',2,'Fully straighten the elbow','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('67b454aa-d39f-54f6-b1ff-0bc3922eae7b','635e566c-21f1-5577-aa0d-be82eb15f7c4','cue',3,'Control the stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3b50e852-28e2-5552-a67d-f46ded55f6b4','635e566c-21f1-5577-aa0d-be82eb15f7c4','mistake',1,'Flaring elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('24e0f804-ce8d-5f04-a5ad-ce6f427ed5ab','635e566c-21f1-5577-aa0d-be82eb15f7c4','mistake',2,'Moving the shoulders','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc3bfa06-1b6d-5c9b-ae36-68116b2fce7e','635e566c-21f1-5577-aa0d-be82eb15f7c4','mistake',3,'Using momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5f6bbbc0-6374-59bd-96dd-0ebbd287f1e6','95984c7f-d04f-5638-af7c-20338f1898e3','step',1,'Lie on your back with your partner kneeling beside you.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d7b907e8-5a44-51d7-9070-bc2c3ddb1387','95984c7f-d04f-5638-af7c-20338f1898e3','step',2,'Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('762c19d2-5716-5a62-9ea5-02e76db9d3b4','95984c7f-d04f-5638-af7c-20338f1898e3','step',3,'Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('53d7fa49-6e6a-5db7-ba28-e347c8e65450','95984c7f-d04f-5638-af7c-20338f1898e3','step',4,'After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b93d352a-517c-5f91-89a7-a9eb1e6dde4f','95984c7f-d04f-5638-af7c-20338f1898e3','cue',1,'Breathe slowly and deeply','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('110ca8a9-06ab-562d-9996-d33a9396f3ea','95984c7f-d04f-5638-af7c-20338f1898e3','cue',2,'Move into the stretch gradually','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1c4d874a-8fbd-59b7-abd3-c6c224b11cce','95984c7f-d04f-5638-af7c-20338f1898e3','cue',3,'Hold or move only in a pain-free range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7faed667-ad41-54ad-9cfb-c0b2815c0491','95984c7f-d04f-5638-af7c-20338f1898e3','mistake',1,'Bouncing into the stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('51214575-17e2-5de1-8ce7-0014a16719c8','95984c7f-d04f-5638-af7c-20338f1898e3','mistake',2,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('201b8998-683d-5a3e-89db-737b8de8e5b6','95984c7f-d04f-5638-af7c-20338f1898e3','mistake',3,'Forcing range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e1d9a1c8-ba26-563a-a594-504a37ab9fca','da301907-2a5b-5420-9a7e-9661d31baa8c','step',1,'Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('04cb4285-67e6-5a43-955f-b460de2d25e0','da301907-2a5b-5420-9a7e-9661d31baa8c','step',2,'Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0ae12292-b362-5576-ad8d-b7ac4b3343ff','da301907-2a5b-5420-9a7e-9661d31baa8c','step',3,'Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0e46bd5a-ab56-5cdb-bdf1-ad3b3bf3a498','da301907-2a5b-5420-9a7e-9661d31baa8c','step',4,'While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('32a9d844-f86b-5ec1-9d7a-54d3ed89812f','da301907-2a5b-5420-9a7e-9661d31baa8c','step',5,'Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f30943b6-9ef1-52f6-9878-608d4a18e294','da301907-2a5b-5420-9a7e-9661d31baa8c','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8cb8b629-2b8b-5ca8-ab25-8eedeb8ec51b','da301907-2a5b-5420-9a7e-9661d31baa8c','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8be98ee5-389e-57c6-8ad4-2160bd4f16a1','da301907-2a5b-5420-9a7e-9661d31baa8c','cue',2,'Knees track over your toes','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f19a341b-4138-5ba7-855c-e35fb4ab9c56','da301907-2a5b-5420-9a7e-9661d31baa8c','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('15e56cd2-1931-551a-a2ef-6784c97a9975','da301907-2a5b-5420-9a7e-9661d31baa8c','mistake',1,'Knees caving inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc8ab426-4480-5fbf-993b-3380f695d032','da301907-2a5b-5420-9a7e-9661d31baa8c','mistake',2,'Heels lifting off the floor','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ebc0b712-ecb4-50f9-8bdd-bd9f7e52b784','da301907-2a5b-5420-9a7e-9661d31baa8c','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eaeb122a-6561-5293-a81a-3e2a2b040e5e','63fc2d36-987d-5a02-a06a-71128c0f5421','step',1,'Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ce84964d-18fd-5ee3-b220-70acc3a17527','63fc2d36-987d-5a02-a06a-71128c0f5421','step',2,'Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3e2f5213-3a74-5759-92cb-972ba5f0d705','63fc2d36-987d-5a02-a06a-71128c0f5421','step',3,'Lift the bar off the rack and extend your arms in front of you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('507569bd-113e-5586-b99a-ec4022642261','63fc2d36-987d-5a02-a06a-71128c0f5421','step',4,'As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c1170faf-4de1-5d7f-86c0-9ffe743b8cb4','63fc2d36-987d-5a02-a06a-71128c0f5421','step',5,'After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eacaab86-e3f6-599b-86a4-a35647d8b004','63fc2d36-987d-5a02-a06a-71128c0f5421','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a524dc69-d9b8-5bc7-923c-63a12fcd0bf6','63fc2d36-987d-5a02-a06a-71128c0f5421','cue',1,'Pull with the elbows, not the hands','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('64c84277-4923-594c-84a5-c53b7163db42','63fc2d36-987d-5a02-a06a-71128c0f5421','cue',2,'Squeeze shoulder blades together','en','ai_authored:pattern');
