INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be983a91-db3d-54d4-ba06-4a598792a740','b037c732-5a3f-5706-ab21-673eba41c238','step',2,'Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. The elbows should be tucked in. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f3462db3-a006-5efe-b2f5-fe15db915f32','b037c732-5a3f-5706-ab21-673eba41c238','step',3,'As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e8f15831-2eff-5f3e-9718-8febac36862c','b037c732-5a3f-5706-ab21-673eba41c238','step',4,'At that point, use the triceps to bring the weight back up to the starting position as you breathe out.','en','source:free_exercise_db');
