INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('208f1f4a-5d21-52d9-82ff-2a7f2e6bd673','65346e8f-8faf-5a58-a81f-1a2a0201c2ab','step',2,'Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.','en','source:free_exercise_db');
