INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d87c5ec-cb14-512b-b200-098b9b8e2652','65346e8f-8faf-5a58-a81f-1a2a0201c2ab','step',4,'Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.','en','source:free_exercise_db');
