INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('555d3a6d-4f5d-5c03-8fb7-8b9acffb1c7c','e4ada150-c69e-52f0-ad42-9a8665b4ead5','step',2,'To begin, take short steps forward alternating your left and right foot.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe5d87c7-6b34-5ddf-be06-8dbe0e936c3e','e4ada150-c69e-52f0-ad42-9a8665b4ead5','step',3,'After several steps, do just the opposite and walk backward to where you started.','en','source:free_exercise_db');
