INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4d5207b2-02fb-5289-aba8-8d197694ae17','547e40a4-2bc8-5db0-bfad-edfc385cc7cb','step',4,'Keep hips level and core braced throughout.','en','ai_authored:specific');
