INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('21b5fa20-ed42-51d3-9edc-6c94b0fe8b2e','547e40a4-2bc8-5db0-bfad-edfc385cc7cb','cue',2,'Keep a straight line from head to heels','en','ai_authored:pattern');
