INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4e1d6d2a-f487-5d5d-82dc-fc873068efe4','bc61cbbd-d6d4-5b8e-b0ef-c8f190597d68','step',1,'Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5841f8c0-22a1-5c8a-a295-c561a0907aa1','bc61cbbd-d6d4-5b8e-b0ef-c8f190597d68','step',2,'As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('38120463-69fd-52a5-b63d-1e68450956c3','bc61cbbd-d6d4-5b8e-b0ef-c8f190597d68','step',3,'Maintaining control and stability, extend through the elbow to complete the motion.','en','source:free_exercise_db');
