INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fa3f931c-5e8d-5950-b2fa-6b2d10a863aa','ffe87198-397f-5b54-84c8-b19278f9aa70','step',1,'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ca5b7134-4433-589d-b8a4-1d90abaf0a22','ffe87198-397f-5b54-84c8-b19278f9aa70','step',2,'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('06cfbba4-7ed9-5145-be6f-10d39637561a','ffe87198-397f-5b54-84c8-b19278f9aa70','step',3,'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4025c1a-95e1-5fa1-beed-c027dfd554e3','ffe87198-397f-5b54-84c8-b19278f9aa70','step',4,'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f5076e8f-5dcf-58cd-a13c-70c9ad5d18e6','ffe87198-397f-5b54-84c8-b19278f9aa70','step',5,'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('32768464-e750-5517-97a5-d90bb483c489','ffe87198-397f-5b54-84c8-b19278f9aa70','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('448bc844-a41c-5bd5-9380-ee58830a8b3c','ffe87198-397f-5b54-84c8-b19278f9aa70','cue',2,'Knees track over your toes','en','ai_authored:pattern');
