INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ec740e68-5c07-52c0-b0dc-b7beb3713280','ffe87198-397f-5b54-84c8-b19278f9aa70','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8f456308-4194-5c8c-954b-c0b262f82b98','a60b6a32-2880-5c04-8f37-23e7a01c0d35','step',1,'Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0b33ab56-813a-5701-9a83-69064de2ff23','a60b6a32-2880-5c04-8f37-23e7a01c0d35','step',2,'This will be your starting position. Lower yourself under control until your knees are almost completely straight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fb46df1a-b2ee-5614-b057-e77c4554e84a','a60b6a32-2880-5c04-8f37-23e7a01c0d35','step',3,'Remaining in control, raise yourself back up to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb9c7ffb-f3ec-5f7e-b670-7af9da3272b4','a60b6a32-2880-5c04-8f37-23e7a01c0d35','step',4,'If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e18349fc-bd3f-5ecd-995f-fce5e316f289','a60b6a32-2880-5c04-8f37-23e7a01c0d35','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f2f7736d-df77-50e5-a924-26fe44ce3984','a60b6a32-2880-5c04-8f37-23e7a01c0d35','cue',2,'Keep the weight close to your legs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d4483002-5653-571a-b80c-977a2833b2b4','a60b6a32-2880-5c04-8f37-23e7a01c0d35','cue',3,'Neutral spine from head to hips','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('96a9021a-b878-52af-9fcb-bc2640727165','a60b6a32-2880-5c04-8f37-23e7a01c0d35','mistake',1,'Rounding the back','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2014928-875a-581a-8741-98391e7d04c4','a60b6a32-2880-5c04-8f37-23e7a01c0d35','mistake',2,'Turning the hinge into a squat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f872899f-3996-5e9a-93a3-fcab0672e366','a60b6a32-2880-5c04-8f37-23e7a01c0d35','mistake',3,'Hyperextending at lockout','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb3a9b8f-0bf4-513c-9a49-e5c0cfe3a772','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','step',1,'Lie down on a flat bench with a dumbbell in one hand on top of your thigh.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('10d7018d-c494-552b-ae9b-bc10469f46a9','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','step',2,'By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1c0078c8-9543-50a4-9623-46fb6fb23ca5','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','step',3,'Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position. Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02e64b01-402b-51cc-869a-d34913ec737b','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','step',4,'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('588b411e-33a5-5527-9d4a-233da050fc37','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','step',5,'Repeat the movement for the prescribed amount of repetitions of your training program.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7f660603-878a-59ba-b91a-7d53da1e762f','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','step',6,'Switch arms and repeat the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c0612d52-8edd-56ce-8e43-4d7a7170b3a1','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1090d78e-65d5-57eb-90b5-8897323a4d30','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','cue',2,'Wrists stacked over elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('caf4214a-1aad-5fba-ab6e-327bf1a44949','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','cue',3,'Lower under control to chest level','en','ai_authored:pattern');
