INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4e106b7f-0fa9-5651-9018-fb587d441309','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','mistake',2,'Bouncing off the chest','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6c647e5d-b808-50ba-ab0b-f7c626d253b0','7aad29c5-e1f0-5ebc-bc3c-b5d34dc22fee','mistake',3,'Lifting hips off the bench','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3d9e5034-e9c0-5fa4-aff3-b609064a5f17','f5fecffa-50e5-500c-9dae-183adb08aea1','step',1,'Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3112980c-360a-5c26-a7a1-56b04b34673b','f5fecffa-50e5-500c-9dae-183adb08aea1','step',2,'As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f07a6909-0338-5c19-9142-8e4960f4634b','f5fecffa-50e5-500c-9dae-183adb08aea1','step',3,'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0dff502a-4c69-55aa-bd04-735a4a056d7a','f5fecffa-50e5-500c-9dae-183adb08aea1','step',4,'Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
