INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87e0c5e2-a6b9-5a48-8a81-5097259e9b93','45dca996-f226-5c11-a621-a4dba82b2099','step',2,'Pull the handle down, squeezing your elbow to your side as you flex the elbow.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7136ca2-d5b3-5bf4-a322-8439ddac1462','45dca996-f226-5c11-a621-a4dba82b2099','step',3,'Pause at the bottom of the motion, and then slowly return the handle to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3144f3cf-5750-57cc-a873-ef4ee9505d14','45dca996-f226-5c11-a621-a4dba82b2099','step',4,'For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.','en','source:free_exercise_db');
