INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2af0b190-1484-5cc2-819e-167ee43c28ca','83881218-01d2-5741-a9cd-4914c6c17ee0','step',3,'Row the bell toward your hip, elbow close to the body.','en','ai_authored:specific');
