INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('04861190-53c2-5f87-8963-81735add6b28','83881218-01d2-5741-a9cd-4914c6c17ee0','cue',2,'Squeeze shoulder blades together','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('796eaa73-0b39-5c65-a864-e89c7139630a','83881218-01d2-5741-a9cd-4914c6c17ee0','cue',3,'Keep the torso still','en','ai_authored:pattern');
