INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9d39a14-82e2-5a2a-930d-f0bc14e7b2ef','0e1905c7-262e-51dd-a8e8-d55dbb23df03','step',2,'Face the weight stack from a distance of about two feet, grasping the steel frame for support.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a1e2092d-bc94-58e1-8e35-aa191e5c2c45','0e1905c7-262e-51dd-a8e8-d55dbb23df03','step',3,'While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('955f098f-71cb-5c36-b0f0-049068640c28','0e1905c7-262e-51dd-a8e8-d55dbb23df03','step',4,'Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ecd20b4e-7d05-5a57-bd1f-1938236bc704','0e1905c7-262e-51dd-a8e8-d55dbb23df03','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
