INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d9871f9-2445-5f9a-b5a3-74f4ee426d02','0e1905c7-262e-51dd-a8e8-d55dbb23df03','cue',1,'Move slowly and under control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0ed116ad-7629-5774-866f-4dba1d8fde40','0e1905c7-262e-51dd-a8e8-d55dbb23df03','cue',2,'Keep the pelvis level','en','ai_authored:pattern');
