INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0edb618d-b863-56b8-ab58-b55ad9fd9abc','fb7d73a1-182f-5d09-8be6-4ab4fd892560','step',1,'Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a996cf17-4447-5989-9b3f-e10bffa0936b','fb7d73a1-182f-5d09-8be6-4ab4fd892560','step',2,'Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.','en','source:free_exercise_db');
