INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b80fa509-5f71-5d8b-9c82-b9d6ab1d0f51','7cf8b405-f395-5be8-88f6-fb14fc1ff089','step',2,'Initiate the countermovement by raising the ball above your head and fully extending your body.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd7e735b-1e96-552c-a6e9-9b3c69e13021','7cf8b405-f395-5be8-88f6-fb14fc1ff089','step',3,'Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('91a04461-9ccd-557b-bbe9-49972d27670b','7cf8b405-f395-5be8-88f6-fb14fc1ff089','step',4,'Receive the ball with both hands on the bounce and repeat the movement.','en','source:free_exercise_db');
