INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8f788b2a-d459-5ff4-8dbf-ed529d54c1dd','ee6da9da-d08c-577d-a025-0799c1a05bbc','step',4,'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('029d7b48-00ca-5c38-96c5-74be6635361a','ee6da9da-d08c-577d-a025-0799c1a05bbc','step',5,'Return to the starting position and repeat the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c5c7b494-7f77-593f-8734-c1cceee7052e','ee6da9da-d08c-577d-a025-0799c1a05bbc','step',6,'For added difficulty, add claps into the movement while you are air borne.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f946fc54-f299-50e7-b034-6870bd267268','ee6da9da-d08c-577d-a025-0799c1a05bbc','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('09f73bb4-91d8-5692-93a1-b6b08c938933','ee6da9da-d08c-577d-a025-0799c1a05bbc','cue',2,'Wrists stacked over elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ab4af31d-9de5-55ee-8ad3-817a032e55a2','ee6da9da-d08c-577d-a025-0799c1a05bbc','cue',3,'Lower under control to chest level','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('38046b82-7006-5790-bb92-f70e18146b86','ee6da9da-d08c-577d-a025-0799c1a05bbc','mistake',1,'Flaring elbows to 90 degrees','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d21431ec-52b5-57ba-922f-2029f75ff88e','ee6da9da-d08c-577d-a025-0799c1a05bbc','mistake',2,'Bouncing off the chest','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f40ae871-01a2-562c-8a9b-7eae5ec82edd','ee6da9da-d08c-577d-a025-0799c1a05bbc','mistake',3,'Lifting hips off the bench','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6a2c6ddd-977c-52f1-acc3-c60443f0f0a3','ee116ad3-f1d2-5eab-ace6-ad91959d039f','step',1,'Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly. Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended. Place the bar about 1 inch in front of your shins and over the balls of your feet. Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8efc25b8-a597-5252-bc39-4e98357103a0','ee116ad3-f1d2-5eab-ace6-ad91959d039f','step',2,'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase. Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings. Keep elbows fully extended with the head in a neutral position and the shoulders over the bar. As the bar raises keep it as close to the shins as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4da86430-c3eb-5b02-9306-ddab796de588','ee116ad3-f1d2-5eab-ace6-ad91959d039f','step',3,'As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Keep the back flat or slightly arched, elbows fully extended and your head neutral. Inhale and then forcefully and quickly extend your hips and knees and stand on your toes. Keep the bar as close to your body as possible. Also, keep your shoulders over the bar and arms straight as long as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9dbecf8a-0d92-55a4-86ea-ef1d24c8a837','ee116ad3-f1d2-5eab-ace6-ad91959d039f','step',4,'When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement. As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar. Continue to pull the arms as high and as long as possible. After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f3ec9be3-f571-5848-8980-2d04b74362d7','ee116ad3-f1d2-5eab-ace6-ad91959d039f','step',5,'Simultaneously, flex the hips and knees into a quarter squat position. Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles. Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement. Stand up by extending the hips and knees to a fully erect position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8241ebf9-f6e0-5c02-b45a-315558d14536','ee116ad3-f1d2-5eab-ace6-ad91959d039f','step',6,'Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement. Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs. Squat down with the elbows fully extended until the bar touches the floor. Start over at Phase 1 and repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('79f8c3e3-98bd-5a57-ad6b-108a0f6c7932','ee116ad3-f1d2-5eab-ace6-ad91959d039f','cue',1,'Drive explosively with the legs/hips','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3f23d3fc-be32-5397-9af2-0c184f95d456','ee116ad3-f1d2-5eab-ace6-ad91959d039f','cue',2,'Keep the load close','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4238e6ed-7385-56a9-9db7-473dbac5ef1a','ee116ad3-f1d2-5eab-ace6-ad91959d039f','cue',3,'Land or receive softly','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('56795884-0c78-58dc-8ebd-7c010bb4d6d8','ee116ad3-f1d2-5eab-ace6-ad91959d039f','mistake',1,'Pulling early with the arms','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd3dd373-64c9-5c38-bb2e-9272269467b3','ee116ad3-f1d2-5eab-ace6-ad91959d039f','mistake',2,'Poor bar path','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e7c872cb-8455-5c34-8c0a-8f2d662e4c24','ee116ad3-f1d2-5eab-ace6-ad91959d039f','mistake',3,'Doing these when fatigued','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3649e37d-280d-57f9-aff7-fc92e50f9277','1658e26a-5b19-502f-bf83-7235ed184fd9','step',1,'Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('914fb28b-e277-562c-b9dd-8ef0f2158532','1658e26a-5b19-502f-bf83-7235ed184fd9','step',2,'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6a064c0e-b69d-5b8a-8730-77e28b2967cc','1658e26a-5b19-502f-bf83-7235ed184fd9','step',3,'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d92362d3-798c-5c06-8efe-5d05b5efe8b8','1658e26a-5b19-502f-bf83-7235ed184fd9','step',4,'As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('415ae9be-bbc6-5aa9-a2ea-1314b61d17a2','1658e26a-5b19-502f-bf83-7235ed184fd9','step',5,'Return to a standing position with the weight over head.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17f781b1-06bb-5baf-a999-d7d45da89bb8','1658e26a-5b19-502f-bf83-7235ed184fd9','cue',1,'Drive explosively with the legs/hips','en','ai_authored:pattern');
