INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ddbd2e83-a76f-5e01-934b-282d278fccd8','1658e26a-5b19-502f-bf83-7235ed184fd9','mistake',3,'Doing these when fatigued','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('029beafc-57db-58f0-bd38-039a6186c753','200c9fb6-5f0f-5ded-9888-49f110a2b4e0','step',1,'To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4f7b134b-3c49-59fc-b98e-b5bf2ce9bc7e','200c9fb6-5f0f-5ded-9888-49f110a2b4e0','step',2,'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5836bfd1-50f6-5f4c-aeaa-c39f0971d023','200c9fb6-5f0f-5ded-9888-49f110a2b4e0','step',3,'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('88820797-4203-5e77-b153-a19d9afeea00','200c9fb6-5f0f-5ded-9888-49f110a2b4e0','step',4,'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('55f3f9d1-74cb-510e-94e5-07f93ecd14d4','200c9fb6-5f0f-5ded-9888-49f110a2b4e0','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('18daf940-2c16-5739-ac02-c8f0cea16419','200c9fb6-5f0f-5ded-9888-49f110a2b4e0','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
