INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ef7d313c-51d3-50e8-8a6e-fd2fd4899678','ebef52b2-dd11-5ad5-892e-68f505966591','step',2,'Face away from the machine, straddling the cable, with your feet set wide apart.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07283ffa-f96d-5683-88c2-c2002e13c0bc','ebef52b2-dd11-5ad5-892e-68f505966591','step',3,'Begin the movement by reaching through your legs as far as possible, bending at the hips.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ef9b6f77-6c10-558e-9d1d-9178470f90bb','ebef52b2-dd11-5ad5-892e-68f505966591','step',4,'Keep your knees slightly bent.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('581d42f2-c5a7-5793-b737-848d8c29c3cb','ebef52b2-dd11-5ad5-892e-68f505966591','step',5,'Keeping your arms straight, extend through the hip to stand straight up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a80fd342-c95d-5e82-9379-89b77d649ede','ebef52b2-dd11-5ad5-892e-68f505966591','step',6,'Avoid pulling upward through the shoulders; all of the motion should originate through the hips.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f728af0c-940f-5661-911a-9910636b3cf6','ebef52b2-dd11-5ad5-892e-68f505966591','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
