INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cf12fecf-b8fc-5cfe-972c-b4814415e82d','165eaec6-8da7-5acd-a276-baa3429e889e','step',2,'Brace and dip a few centimetres by bending the knees, torso upright.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2903cf37-7ba1-5398-9cde-1ff16f8c3998','165eaec6-8da7-5acd-a276-baa3429e889e','step',3,'Drive up through the legs and use that momentum to press the bar overhead.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7c399ffa-f541-5cca-b959-7146ac09c8b4','165eaec6-8da7-5acd-a276-baa3429e889e','step',4,'Lock out with the bar over the middle of the foot.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a50fac38-c2f8-5be5-9e62-059cec934f67','165eaec6-8da7-5acd-a276-baa3429e889e','step',5,'Lower the bar back to the shoulders under control.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4f814c16-b375-59ac-9e84-be8b2df3bc5d','165eaec6-8da7-5acd-a276-baa3429e889e','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
