INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('48d82e0b-3bd7-5a98-8460-201a14c84027','06216468-d801-5000-b9ee-54fd8ca9e8cc','step',2,'Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fee2dba2-d083-5e44-872d-60f310427f54','06216468-d801-5000-b9ee-54fd8ca9e8cc','step',3,'While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('79b8adb4-ebe9-5beb-941d-675d11d0aaa3','06216468-d801-5000-b9ee-54fd8ca9e8cc','step',4,'Hold the contraction for a second and move your legs back to the starting position while exhaling.','en','source:free_exercise_db');
