INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c447c87e-7563-5d79-a3b4-ceb4629e190d','227316cd-426b-5669-9a07-2585812674aa','step',3,'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c5af7fb8-ee51-5235-9a44-f22a83526173','227316cd-426b-5669-9a07-2585812674aa','step',4,'The arms should be elevated until they are parallel to the floor.','en','source:free_exercise_db');
