INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('047c2b8f-4893-52f3-b94e-a041e78edfc5','def4da91-8909-5c9a-b124-e95b55801501','step',2,'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8c536d6-8fe1-5dda-b156-2e3d7808b5f4','def4da91-8909-5c9a-b124-e95b55801501','step',3,'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('66e4e9cd-a573-550c-b708-c7a334980a69','def4da91-8909-5c9a-b124-e95b55801501','step',4,'Slowly lower the weight again to the starting position as you inhale.','en','source:free_exercise_db');
