INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80280d70-cab3-5166-b024-3a857ac57407','f9d9b3a9-bd3b-592b-8f58-cbd9c3b0bee2','step',3,'Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8440299b-a63a-50cd-881f-9529e15ddd38','f9d9b3a9-bd3b-592b-8f58-cbd9c3b0bee2','step',4,'Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.','en','source:free_exercise_db');
