INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d701f042-7f34-55a0-a72c-bbecbed4b35c','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','step',1,'Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('648a94ff-4a7c-5296-9b9d-b6e40ee5c32f','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','step',2,'To begin the movement, flex the hips, pulling the legs forward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a477dfd4-1ff4-5396-8905-5026e63a83b0','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','step',3,'Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ba30c1ed-cf73-50c2-b54e-db2159cf7815','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','step',4,'Return by again flexing the hip, pulling the carriage forward as far as you can.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1223385a-abda-5196-9409-ea994b347c1d','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','step',5,'Repeat for the desired number of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('00ba5fb3-e4d9-5489-9c78-cff0bc06be9c','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7af38a8a-72c1-543c-aa7f-71db7ed21ab6','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','cue',2,'Keep the weight close to your legs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5485eb82-5558-5f62-84e6-8bd7b96e80c2','483007ed-4b6c-5a81-bfb2-9bbfc5bfcf00','cue',3,'Neutral spine from head to hips','en','ai_authored:pattern');
