INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('53715359-0a25-5868-a227-21d803bcf9e7','600bf03d-f9b7-5500-9362-74456fe06ed4','step',1,'Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.','en','source:free_exercise_db');
