INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4cafab11-afb8-5f47-8522-edbdfe4b7abd','af26be3b-6c7f-5994-9008-b11ed4e03465','step',1,'Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2dc8cdf3-00f4-57af-882d-5fe2b792dfe0','af26be3b-6c7f-5994-9008-b11ed4e03465','step',2,'Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('050584d8-2f35-5188-9776-a84d3f86bd85','af26be3b-6c7f-5994-9008-b11ed4e03465','step',3,'Pause at the bottom of the motion, squeezing your lats.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e7f61749-da10-51d1-8293-0ab678c168ef','af26be3b-6c7f-5994-9008-b11ed4e03465','step',4,'Return to the starting position without allowing the weight to fully rest on the stack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('468a7de6-d79c-5415-87d0-2ed140fbba5e','af26be3b-6c7f-5994-9008-b11ed4e03465','cue',1,'Start each rep by pulling the shoulder blades down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7cc60e0b-6771-5fe5-a4a1-39e1a14da247','af26be3b-6c7f-5994-9008-b11ed4e03465','cue',2,'Drive elbows toward your ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b92634bc-0a0c-5dab-897b-20b9008e472d','af26be3b-6c7f-5994-9008-b11ed4e03465','cue',3,'Control the way down to a full hang/stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8304ee00-6e32-5923-bf1d-e65a64eeb838','af26be3b-6c7f-5994-9008-b11ed4e03465','mistake',1,'Kipping or swinging','en','ai_authored:pattern');
