INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d4810241-59f8-5a99-bdf5-60933c1d769a','af26be3b-6c7f-5994-9008-b11ed4e03465','mistake',3,'Pulling behind the neck','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9b06a99e-7fd9-5f15-b4b3-38b5589d69d1','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','step',1,'To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8b0a2704-4912-5259-8d38-4aabf6b87d92','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','step',2,'There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('71a980ce-860e-53f8-a06e-dd8c0163beb5','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','step',3,'The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('308bf534-1ea7-5c69-84de-2cf60d62519d','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','cue',1,'Start with a 5-minute easy warm-up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5c700ed6-d333-5f8a-9415-f679e9cc1e97','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','cue',2,'Keep a pace where you can speak in short sentences (moderate)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2770170f-2c8e-576e-b509-d9b4f932f214','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','cue',3,'Relax shoulders and keep good posture','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea05a6ce-9b0f-55e1-a2aa-a4ac8a17ddb1','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','mistake',1,'Starting too fast','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('161f6d47-48a5-5d6d-8fad-9a56267e8a18','d771c0ff-bee8-5ef4-a7ba-943ed74c37d0','mistake',2,'Holding the handrails (machines)','en','ai_authored:pattern');
