INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b07a8248-95a9-5de2-8e69-1695dfca74fd','bb4d541b-2043-5ab2-8c77-9e1f7083fc35','step',1,'It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('22186edd-ad86-53c3-b3c1-59a31ec14425','bb4d541b-2043-5ab2-8c77-9e1f7083fc35','step',2,'Keep the front heel on the floor (if it lifts up, scoot your other leg further back).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('584779e6-165a-5529-b0c3-28a2ff5d2562','bb4d541b-2043-5ab2-8c77-9e1f7083fc35','step',3,'Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc8bc087-87dd-54dc-a976-7c66d1136e97','bb4d541b-2043-5ab2-8c77-9e1f7083fc35','cue',1,'Breathe slowly and deeply','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('abac9b19-9921-58db-8fc3-87ad5de38b31','bb4d541b-2043-5ab2-8c77-9e1f7083fc35','cue',2,'Move into the stretch gradually','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('73370c1e-26d3-5e50-89c8-99e44ac52c6b','bb4d541b-2043-5ab2-8c77-9e1f7083fc35','cue',3,'Hold or move only in a pain-free range','en','ai_authored:pattern');
