INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('022ddca6-4ec2-5e35-8256-b6bed656149b','bb4d541b-2043-5ab2-8c77-9e1f7083fc35','mistake',2,'Holding the breath','en','ai_authored:pattern');
