INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('39dd6bf3-0482-5b95-8f1b-603c9720ea86','25b5e466-e759-5262-8ad3-52b632a0ea32','step',1,'To begin, step onto the treadmill and select the desired option from the menu.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dabf5019-9724-5f09-ad94-ffddfd014f1d','25b5e466-e759-5262-8ad3-52b632a0ea32','step',2,'Most treadmills have a manual setting, or you can select a program to run.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('794a9b71-1a1b-5535-9174-7ca8d041e53a','25b5e466-e759-5262-8ad3-52b632a0ea32','step',3,'Elevation can be adjusted to change the intensity of the workout.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b283faab-5d57-53d5-8cf9-43e8ad73b205','25b5e466-e759-5262-8ad3-52b632a0ea32','step',4,'Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5d21d5f7-bf18-5186-a3a3-50dfe605ddd7','25b5e466-e759-5262-8ad3-52b632a0ea32','cue',1,'Start with a 5-minute easy warm-up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9f3a4978-4f0f-51a6-b2ed-6e8921f30140','25b5e466-e759-5262-8ad3-52b632a0ea32','cue',2,'Keep a pace where you can speak in short sentences (moderate)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('26c9b71f-54a8-55af-8986-a2cb5fa00dd4','25b5e466-e759-5262-8ad3-52b632a0ea32','cue',3,'Relax shoulders and keep good posture','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a7d075df-d221-5459-8ddd-aee91b5b71af','25b5e466-e759-5262-8ad3-52b632a0ea32','mistake',1,'Starting too fast','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('878ce471-5f40-5371-ae46-5e597fcf1f62','25b5e466-e759-5262-8ad3-52b632a0ea32','mistake',2,'Holding the handrails (machines)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4700a6c7-9304-5347-8946-a58137208560','25b5e466-e759-5262-8ad3-52b632a0ea32','mistake',3,'Skipping the cool-down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('db1981e0-90aa-5230-99d5-9893d9e77d19','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','step',1,'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80799af9-5927-5512-adb5-627a4393724c','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','step',2,'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e1ddca28-eb55-5644-b88f-5c15980c7696','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','step',3,'Twist your torso to the right side until your arms are parallel with the floor while breathing out.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('788c1790-47f0-5470-a4a0-f6fa9915701f','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','step',4,'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('85f388b3-62c1-520c-a4de-bbc22094a068','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5ccf5543-c7b9-5eb4-94c4-72cec8112a8d','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','cue',1,'Rotate from the torso with hips stable','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('94729b9d-afb0-56bf-a95e-377483c5e86e','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','cue',2,'Move with control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7a9dd09c-4ee2-5fc4-a9ae-ecce6c0dd348','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','cue',3,'Keep the core braced','en','ai_authored:pattern');
