INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e808c945-3ed7-51c9-bd6f-0cc2d6c4a3bf','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','mistake',2,'Twisting through the lower back only','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('69004921-045f-59cf-ae79-56698d78ef20','c804949b-f36e-53a0-bdd5-7b8d1d26a8c2','mistake',3,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('08e3db4b-8c25-5dfb-bd57-a453489c743d','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','step',1,'Take a pronated grip on a pull-up bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0b3e7dc5-6dcc-5381-ac07-7ad3d35f8843','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','step',2,'From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('16971e04-ca6f-5f37-9965-e88ebb29b997','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','step',3,'Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd534a75-2d6e-5b9a-a8a4-488fe6f86545','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','cue',1,'Start each rep by pulling the shoulder blades down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('82038644-acde-5ff4-9b9d-98b937b3e945','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','cue',2,'Drive elbows toward your ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('308f5167-d108-58a6-921f-ee46f9b273e8','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','cue',3,'Control the way down to a full hang/stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('452482a7-6451-582a-bb75-05718af0241a','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','mistake',1,'Kipping or swinging','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('33572435-457c-518c-bd6c-1cc54b64c0d2','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','mistake',2,'Half reps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e159be80-3fa7-5399-b6df-20b1129525bc','fb03c844-1f5d-5e82-a5e0-74ce87922f6f','mistake',3,'Pulling behind the neck','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b9fe299b-440c-5df0-b72b-d9288707d8d7','a8ebcede-e10d-5c90-af41-555aab136cee','step',1,'Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c92b160b-3264-53c4-ae08-319ba0aba3fb','a8ebcede-e10d-5c90-af41-555aab136cee','step',2,'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dca14ace-6c53-538d-a8fd-a8e3e1bc5698','a8ebcede-e10d-5c90-af41-555aab136cee','step',3,'Lower the bar down to the collarbone slowly as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('31aefbbb-13a2-5fca-803a-ca7b833978d5','a8ebcede-e10d-5c90-af41-555aab136cee','step',4,'Lift the bar back up to the starting position as you exhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2b4e445-9e42-53e9-b897-d94ed8829888','a8ebcede-e10d-5c90-af41-555aab136cee','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4e5d194-d47c-5965-818b-6e8891f183b3','a8ebcede-e10d-5c90-af41-555aab136cee','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2894a49c-22cd-5f53-a134-7dfb7c4ffb7b','a8ebcede-e10d-5c90-af41-555aab136cee','cue',2,'Press in a straight line overhead','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7de94a02-11f4-5918-bcb6-25b62999d3d0','a8ebcede-e10d-5c90-af41-555aab136cee','cue',3,'Finish with biceps near the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6c6ed797-946d-5d73-8e42-33273df4fa98','a8ebcede-e10d-5c90-af41-555aab136cee','mistake',1,'Excessive lower-back arch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7138f094-6f2f-5ab7-a384-c3cb2ef346d1','a8ebcede-e10d-5c90-af41-555aab136cee','mistake',2,'Pressing forward instead of up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8f67e4da-c125-5519-92d6-0147006bb1f3','a8ebcede-e10d-5c90-af41-555aab136cee','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('130a463d-0f93-5dac-ac21-22e3729b4363','f1245f09-2ade-5006-91fa-92b9b90591cf','step',1,'Place a couple of dumbbells looking forward in front of a flat bench.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6f7b65c3-63f1-5955-9016-2911a6804abf','f1245f09-2ade-5006-91fa-92b9b90591cf','step',2,'Sit on the end of the bench with your legs together and the dumbbells behind your calves.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6ccc25ae-6584-5c81-8fae-45e395c17275','f1245f09-2ade-5006-91fa-92b9b90591cf','step',3,'Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6a766ca9-ae96-5730-b988-7b5a6b7a2107','f1245f09-2ade-5006-91fa-92b9b90591cf','step',4,'Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f7d6fd0d-331a-5b32-8544-5a9a32e3e837','f1245f09-2ade-5006-91fa-92b9b90591cf','step',5,'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('522c2a6a-be19-50b1-97ef-e20dba1ee0c2','f1245f09-2ade-5006-91fa-92b9b90591cf','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3f7e0e4d-7d97-5aa6-8c36-6c6d629720c4','f1245f09-2ade-5006-91fa-92b9b90591cf','cue',1,'Lead with the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fbb32c12-92c4-5ffa-9fcf-8c1b587540c4','f1245f09-2ade-5006-91fa-92b9b90591cf','cue',2,'Control the lowering','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2424ea27-56a5-5c21-8f61-9f3d72289b3a','f1245f09-2ade-5006-91fa-92b9b90591cf','cue',3,'Keep shoulders away from ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8a069ff5-f072-525b-b0c1-4ffa8058c8f1','f1245f09-2ade-5006-91fa-92b9b90591cf','mistake',1,'Swinging with the torso','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ad94bc2-cd7d-5afc-92c2-b7711f762353','f1245f09-2ade-5006-91fa-92b9b90591cf','mistake',2,'Shrugging the weight up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb5fa02b-01c4-58ad-bbce-c5c155a011dd','f1245f09-2ade-5006-91fa-92b9b90591cf','mistake',3,'Going too heavy','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f76103dc-b942-5371-a6d5-dcb5c8ab3a8c','66d0093b-5745-50d6-b591-e384537917ea','step',1,'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5cd15e2a-1462-54e7-853e-f11887d5f6c5','66d0093b-5745-50d6-b591-e384537917ea','step',2,'Begin by extending through the elbow, pressing the handles together above your head.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('72e64d7b-84e4-5b93-af8e-4574ca5f629f','66d0093b-5745-50d6-b591-e384537917ea','step',3,'After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6c0db61f-45d3-5e76-847b-3865a2f1f3bf','66d0093b-5745-50d6-b591-e384537917ea','step',4,'You can also execute this movement with your back off the pad and alternate hands.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('acbacea1-dfef-563e-b92e-04a537e136b2','66d0093b-5745-50d6-b591-e384537917ea','cue',1,'Squeeze glutes and brace before pressing','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('57eb6626-cd0e-5a99-87de-a2108aa70be4','66d0093b-5745-50d6-b591-e384537917ea','cue',2,'Press in a straight line overhead','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4204344-1df3-5cce-a029-e989c00e5ab8','66d0093b-5745-50d6-b591-e384537917ea','cue',3,'Finish with biceps near the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ef5b8c22-7181-555a-8d8a-d119049e7c31','66d0093b-5745-50d6-b591-e384537917ea','mistake',1,'Excessive lower-back arch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c8c117c8-808a-5cf5-84e0-98071f618de1','66d0093b-5745-50d6-b591-e384537917ea','mistake',2,'Pressing forward instead of up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2b7d109a-25dc-53f5-a3f4-82ae7c156c1d','66d0093b-5745-50d6-b591-e384537917ea','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4dc401c-0692-5c15-88f8-32bb52a06d4c','5e111fe3-b91f-549d-a8ec-6ef4ffbdf189','step',1,'Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('95127069-4f0b-5257-a618-7d0908fab69d','5e111fe3-b91f-549d-a8ec-6ef4ffbdf189','step',2,'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('231cda71-f54d-570e-ad67-b4fb1e699749','5e111fe3-b91f-549d-a8ec-6ef4ffbdf189','step',3,'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e8831644-b5bc-56bf-9398-9c7faadf3052','5e111fe3-b91f-549d-a8ec-6ef4ffbdf189','step',4,'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4db5fb3b-86fd-51e0-bd21-b6e638f5ca66','5e111fe3-b91f-549d-a8ec-6ef4ffbdf189','step',5,'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9f8d56bb-1397-527c-88d4-be38e402e540','5e111fe3-b91f-549d-a8ec-6ef4ffbdf189','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
