INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('12fca9d2-2338-52b5-bb23-50aac0e3b31c','c463b526-9e13-5eb1-ba1d-3ff39bafc16b','step',1,'Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a48b1b98-6380-547a-b395-1accacc93987','c463b526-9e13-5eb1-ba1d-3ff39bafc16b','step',2,'Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c7f597b6-1309-5abd-b33c-02a3b441d20e','c463b526-9e13-5eb1-ba1d-3ff39bafc16b','step',3,'Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fc694f0e-9997-587d-8d61-7f0a05701ff5','c463b526-9e13-5eb1-ba1d-3ff39bafc16b','step',4,'As you exhale, push the dumbbells up until they touch at the top.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80da1eb9-1847-54ea-9614-26f752ff2560','c463b526-9e13-5eb1-ba1d-3ff39bafc16b','step',5,'After a second pause, slowly come down back to the starting position as you inhale.','en','source:free_exercise_db');
