INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('12016b37-6686-5cb0-9931-a0eef63f5fde','c463b526-9e13-5eb1-ba1d-3ff39bafc16b','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8a38764a-83a1-555a-b28c-6e75a788a4b0','cf6db9c7-231f-5c84-acab-1b4792bfb52f','step',1,'Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dab187ad-2c28-57cf-aff5-6f3174fbb27f','cf6db9c7-231f-5c84-acab-1b4792bfb52f','step',2,'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9ad68fb2-4ef0-5472-b823-535c3b4cb31f','cf6db9c7-231f-5c84-acab-1b4792bfb52f','step',3,'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d2c36f0d-5c3e-55b5-a7b1-3ba815922364','cf6db9c7-231f-5c84-acab-1b4792bfb52f','step',4,'Slowly return to the starting position as you breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2361d94-c519-579d-a8ab-4df62fa86820','cf6db9c7-231f-5c84-acab-1b4792bfb52f','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
