INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d6cc9160-3267-5255-9f6e-6780dc27c0f7','cf6db9c7-231f-5c84-acab-1b4792bfb52f','mistake',3,'Partial reps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('14baa2dd-0ee0-5dd8-acc0-0a762726e227','0456f284-95ee-51bd-9728-400b121e2639','step',1,'To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9947f84-ee4e-58bf-953c-fdbc8c15f474','0456f284-95ee-51bd-9728-400b121e2639','step',2,'Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b84b0441-f69d-5aae-ab20-1cd36b5c1a0b','0456f284-95ee-51bd-9728-400b121e2639','step',3,'With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('885e282c-fec8-555e-8ab2-026a213c757a','0456f284-95ee-51bd-9728-400b121e2639','step',4,'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('19b962d8-6e70-5d1b-9ee7-b81ace6b5cbd','0456f284-95ee-51bd-9728-400b121e2639','step',5,'Hold that contraction for a second and slowly go back to the original position while breathing in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f4a6fa88-5f72-5f95-a768-2ffb2230192f','0456f284-95ee-51bd-9728-400b121e2639','step',6,'Repeat for the recommended amount of repetitions and then perform the same movement with the right hand.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5c8e3fb4-9461-5792-90e5-6083a2e16fed','0456f284-95ee-51bd-9728-400b121e2639','cue',1,'Pull with the elbows, not the hands','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('75b4be6f-14b0-521d-9c70-2eedfd599d33','0456f284-95ee-51bd-9728-400b121e2639','cue',2,'Squeeze shoulder blades together','en','ai_authored:pattern');
