INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('34a605f9-062d-582e-b3ac-4d8b56db491c','0456f284-95ee-51bd-9728-400b121e2639','mistake',3,'Rounding the back','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a51d546-8a95-5e98-8ef6-6abffe8fc860','adbc98b4-808d-5070-bf9e-5c878408d4da','step',1,'Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5dac9d74-ed0e-5efc-b92f-f994688c6623','adbc98b4-808d-5070-bf9e-5c878408d4da','step',2,'While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c9692992-ecac-5cac-a3b9-593d81bff8e4','adbc98b4-808d-5070-bf9e-5c878408d4da','step',3,'Lower the dumbbells back down slowly to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('05df65f4-64ad-5ccd-9d5c-b7e41f605aa1','adbc98b4-808d-5070-bf9e-5c878408d4da','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cd1fa0dd-e3df-5a91-b705-1cb47942b195','adbc98b4-808d-5070-bf9e-5c878408d4da','cue',1,'Lead with the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d5f57f8-973e-5b7a-8cad-bb44325924c4','adbc98b4-808d-5070-bf9e-5c878408d4da','cue',2,'Control the lowering','en','ai_authored:pattern');
