INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aa73f7eb-fb73-55c3-824b-72df8dc920da','eabcb0db-3fe2-5ded-95fa-decef50b9de8','step',1,'Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eab65837-9be2-57e6-b5a1-c2571ba2f049','eabcb0db-3fe2-5ded-95fa-decef50b9de8','step',2,'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c3c1b0c4-392f-5e41-ae20-a589735a4583','eabcb0db-3fe2-5ded-95fa-decef50b9de8','step',3,'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('96e56c49-5db5-5816-9014-b66182bb1ba1','eabcb0db-3fe2-5ded-95fa-decef50b9de8','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
