INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74450b87-b8dd-5128-a9a9-bc89042ab32b','eabcb0db-3fe2-5ded-95fa-decef50b9de8','cue',2,'Fully straighten the elbow','en','ai_authored:pattern');
