INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80a29312-2c6b-5c96-bd1c-1d78215b0cae','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','step',1,'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87898b97-a689-5d67-ba58-3bc43b730c2b','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','step',2,'Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('23b32ed2-f731-5c6d-9463-abdab218beb3','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','step',3,'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c3d439cd-fde0-571b-b323-194d1a53f60e','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','step',4,'Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.','en','source:free_exercise_db');
