INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c853043-5b12-507e-a157-8b3cae0e3c1a','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','cue',2,'Move the ribs toward the pelvis','en','ai_authored:pattern');
