INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c2aef74f-8552-50ab-88a8-44fcee2769c6','36dcd5d7-ad5b-5fdc-adb8-fbba8587ed47','mistake',3,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a83e3647-5320-5477-98ca-20a6b41aef02','9938827a-fe76-543a-9ef5-46a1436a3864','step',1,'Load your pushing sled with the desired weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f826dc74-fe0a-5b3c-a76b-6873d7d402f8','9938827a-fe76-543a-9ef5-46a1436a3864','step',2,'Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('820c39d1-d135-543c-b864-92cc51a80c5f','9938827a-fe76-543a-9ef5-46a1436a3864','step',3,'Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('82ac1797-4370-5828-87ac-0293f4ee9b43','9938827a-fe76-543a-9ef5-46a1436a3864','cue',1,'Drive explosively with the legs/hips','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('02395d75-6990-516b-9210-5e3386e6e6a5','9938827a-fe76-543a-9ef5-46a1436a3864','cue',2,'Keep the load close','en','ai_authored:pattern');
