INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('515e4a1e-ef31-554f-9f95-1d3eb8aa03a0','9938827a-fe76-543a-9ef5-46a1436a3864','mistake',2,'Poor bar path','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('90b89f1c-01c8-53f4-be50-b8b1dbd2f86e','9938827a-fe76-543a-9ef5-46a1436a3864','mistake',3,'Doing these when fatigued','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('80955f9e-7aea-52ef-b749-daf03b65ec62','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','step',1,'Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a90c1b28-e82b-5286-8f45-e06100af4ee2','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','step',2,'As you breathe in, come down slowly until you feel the bar on your middle chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6452830c-c91c-52ee-a644-2717ac21f966','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','step',3,'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ecd413ad-76bb-5d3f-804b-efedc25dc600','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','step',4,'Repeat the movement for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('74849581-ff8d-5e04-b84d-0e5891090f8c','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','step',5,'When you are done, lock the bar back in the rack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('533da7b8-005b-5fe7-b9c4-5bf5269605e7','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','cue',1,'Shoulder blades squeezed back and down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e9cbaf90-9de9-5f0f-b14b-68bf435e835f','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','cue',2,'Wrists stacked over elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e4cce00c-f7fb-5b72-ab13-9e4397ac678f','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','cue',3,'Lower under control to chest level','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3007d6b9-c5a1-5816-abd5-7da70cde8d3f','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','mistake',1,'Flaring elbows to 90 degrees','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17228e6a-313d-59f7-a4a3-838b718cf062','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','mistake',2,'Bouncing off the chest','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c4c82435-fb94-5753-a901-e5810cd51eb4','6ef5b34f-8fc4-55b8-b9ec-b99b2282639e','mistake',3,'Lifting hips off the bench','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bef538e1-2335-5bb3-8008-b3fe3ee439cb','ec7f63a8-25aa-5839-af33-4f8048a611c8','step',1,'Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c1c68cc-a665-5e17-bed5-246509651c29','ec7f63a8-25aa-5839-af33-4f8048a611c8','step',2,'Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ea2f346f-fb08-5c68-bd9b-20b207ed6519','ec7f63a8-25aa-5839-af33-4f8048a611c8','step',3,'Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('36752db9-15f5-5ec0-a017-041e981c0d86','ec7f63a8-25aa-5839-af33-4f8048a611c8','step',4,'While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8e8093e2-c25a-5620-86f8-56af9936517f','ec7f63a8-25aa-5839-af33-4f8048a611c8','step',5,'Slowly lower the weight again to the starting position as you inhale.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b3d7eff9-8bd9-5101-9ad7-0143764bc384','ec7f63a8-25aa-5839-af33-4f8048a611c8','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5136ec2f-e440-568e-a93c-959f600f23f9','ec7f63a8-25aa-5839-af33-4f8048a611c8','cue',1,'Pull with the elbows, not the hands','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7f0b8216-24c4-56c1-a6b3-e9fde2f4168c','ec7f63a8-25aa-5839-af33-4f8048a611c8','cue',2,'Squeeze shoulder blades together','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3316829d-7b76-5b31-a880-f55954c08abe','ec7f63a8-25aa-5839-af33-4f8048a611c8','cue',3,'Keep the torso still','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eabd66ed-9c40-5720-ad86-4b16e90bf844','ec7f63a8-25aa-5839-af33-4f8048a611c8','mistake',1,'Jerking the torso to move the weight','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bccd8431-0069-51de-9e19-031d63184ae8','ec7f63a8-25aa-5839-af33-4f8048a611c8','mistake',2,'Shrugging the shoulders','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4772fa4f-84ee-502d-abd2-31d8fce7f7f7','ec7f63a8-25aa-5839-af33-4f8048a611c8','mistake',3,'Rounding the back','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6fa06808-6452-55d4-9a90-8ef51f2804a8','afce8de9-fef2-557d-a25d-1f370e1b1ed1','step',1,'Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('775b0281-418c-5219-8fa0-2c89a8e4b134','afce8de9-fef2-557d-a25d-1f370e1b1ed1','step',2,'Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d98f533e-d615-5397-8125-c26411900cb1','afce8de9-fef2-557d-a25d-1f370e1b1ed1','step',3,'Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cd40dd8b-0668-5e47-95fa-53acd1a5d6b9','afce8de9-fef2-557d-a25d-1f370e1b1ed1','step',4,'Return slowly to the starting position as you breathe in while lowering your heels.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('90a878b3-7b1a-5822-ac36-3fb1d03998dd','afce8de9-fef2-557d-a25d-1f370e1b1ed1','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('94d7ce3f-a55b-59ec-bd8d-a8bcfad71537','afce8de9-fef2-557d-a25d-1f370e1b1ed1','cue',1,'Rise as high as possible onto the balls of the feet','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb3e62bd-3e57-5564-a275-0375ba4973ab','afce8de9-fef2-557d-a25d-1f370e1b1ed1','cue',2,'Pause at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a48d9b02-6c60-5dd9-974e-4add827ecbcf','afce8de9-fef2-557d-a25d-1f370e1b1ed1','cue',3,'Lower fully into a stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('524a0407-25a3-542e-9bce-be568861cf16','afce8de9-fef2-557d-a25d-1f370e1b1ed1','mistake',1,'Bouncing at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cf4e0f2a-bf04-5afa-b0bb-00211f6274b5','afce8de9-fef2-557d-a25d-1f370e1b1ed1','mistake',2,'Bending the knees to cheat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2772db02-14c3-58ba-888f-1d427919223d','afce8de9-fef2-557d-a25d-1f370e1b1ed1','mistake',3,'Short range of motion','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d6983a17-d6d3-5222-b6d6-854a8a819819','49194209-7466-5dee-8fe1-ea80d991b077','step',1,'Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('22fba7d0-f2c7-53e9-a8ef-6b4ed65ec111','49194209-7466-5dee-8fe1-ea80d991b077','step',2,'Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c5d6a82-dac5-5abd-96d4-b655a6fadae0','49194209-7466-5dee-8fe1-ea80d991b077','step',3,'After a brief pause, return the hips to the bench.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('64e64a51-dac3-5dd2-bc2b-d6cbba492de8','49194209-7466-5dee-8fe1-ea80d991b077','step',4,'Repeat for the desired number of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11190ec0-2b5b-558b-ad0d-08f3ccdb5358','49194209-7466-5dee-8fe1-ea80d991b077','cue',1,'Push your hips back, not down','en','ai_authored:pattern');
