INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c3ed983-6e86-562d-a84e-89547ec5d75b','9a031b91-d55c-5bd4-8976-be8f1687d3ad','step',2,'Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aa005161-f8ae-5958-ba72-8decbccce9b1','9a031b91-d55c-5bd4-8976-be8f1687d3ad','step',3,'Return this leg to the starting position and repeat on the opposite side.','en','source:free_exercise_db');
