INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('df826e7f-e82f-5bfb-af2b-f8cb401f073f','ca4f00c3-2aa2-504f-8f18-737a37cff27a','step',2,'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('94cc2786-c6b4-5cf1-afd6-4e46435da4a6','ca4f00c3-2aa2-504f-8f18-737a37cff27a','step',3,'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench. Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0d2db640-e424-5ddf-9fc0-2c1d816f48dc','ca4f00c3-2aa2-504f-8f18-737a37cff27a','step',4,'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b0a9b47c-1f09-558a-83df-788e0346d72e','ca4f00c3-2aa2-504f-8f18-737a37cff27a','step',5,'Slowly begin to bring the barbell back to the starting position as your breathe in. .','en','source:free_exercise_db');
