INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('68ebac6b-c457-505c-b407-e07318fb0983','1b3d2c66-f45b-5e48-9439-30ee2af92183','step',4,'Repeat for the planned time.','en','ai_authored:specific');
