INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b71c6f35-b529-5ffc-9921-132ad78f180f','1b3d2c66-f45b-5e48-9439-30ee2af92183','mistake',1,'Leaning heavily on the rail','en','ai_authored:specific');
