INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1063c6c8-1474-5041-9044-f5aa54bb983c','1b3d2c66-f45b-5e48-9439-30ee2af92183','mistake',3,'Toes only on the step','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('495bec3e-6ca5-56c5-bfc0-d642aec827e3','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','step',1,'To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eb43108b-fc6c-5715-8d8a-127ba3e2b19c','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','step',2,'Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ba0e0bc9-f7cb-591c-9205-df7a99148b0d','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','step',3,'They are typically much harder than other cardio equipment.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('72103fd5-f78b-51d9-b974-a76e349a44bb','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','cue',1,'Start with a 5-minute easy warm-up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('be16e636-e08d-5641-8409-eab13df643f3','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','cue',2,'Keep a pace where you can speak in short sentences (moderate)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5f73c3de-cca0-546d-823f-b26bce598cb8','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','cue',3,'Relax shoulders and keep good posture','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('59418d3d-c4f7-5a06-8b81-92f818e678be','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','mistake',1,'Starting too fast','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fe3cb89d-53a0-5750-b5ec-88547c480646','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','mistake',2,'Holding the handrails (machines)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2fbfab44-4c00-5d72-b3bb-089f22564fea','cbbfb6b6-2e3c-5f0c-affa-5b2e53f5511d','mistake',3,'Skipping the cool-down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c2c1932-f357-51cb-8a22-7d7d77ddf6e8','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','step',1,'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c68fb30d-25d2-5c5a-9c45-9dfda610ac5e','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','step',2,'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4af49439-fc5c-5782-869c-05f5e06f3f02','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','step',3,'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3182261b-5b5c-51b4-95d5-dcf47795a806','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','step',4,'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7f7fb1a2-a903-52b0-8afd-f6660445f040','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','step',5,'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87fc676d-a281-5598-81b9-f2142833b235','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e165c830-22e9-5650-9c17-bea19a87dd5c','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','cue',1,'Rise as high as possible onto the balls of the feet','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c5d420e7-57ee-5064-95e8-4ee10e9d32a6','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','cue',2,'Pause at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e2f48dce-05e3-51f1-a714-8099a7f9658d','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','cue',3,'Lower fully into a stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('53c724f7-c6a8-541f-8962-8bb658e2c94e','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','mistake',1,'Bouncing at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e9de7f62-9243-5e93-b1a9-203ae4df08dc','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','mistake',2,'Bending the knees to cheat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('db273bf7-ebaa-586a-80ea-8482680b1f69','8fdb1fe6-c3ef-5a63-afad-a2d4900e3c32','mistake',3,'Short range of motion','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('75a64d0e-c84b-5ddf-b7fb-39815b0eb985','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','step',1,'Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('11b0fa95-1b36-5ba9-829a-9989c59077dd','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','step',2,'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('63e09187-c942-5bb4-af79-0137726ef741','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','step',3,'Slowly begin to bring the curl bar back to starting position as your breathe in.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('81904120-4abb-5012-991b-7cc43e635226','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c644af5-f28f-5cae-9739-959713e549db','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87c3dce2-28e0-59e1-9bc1-dea4c71f09f2','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','cue',2,'Squeeze at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1d587e4b-b279-5a7f-8706-8afb05fa7613','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','cue',3,'Lower all the way under control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('94736de7-0d93-58d4-bc6e-836651a8aef8','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','mistake',1,'Swinging the body','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2de4e105-accf-504e-aa26-d4f092005867','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','mistake',2,'Elbows drifting forward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d75e9bec-ddbd-55d2-80a6-eccb53d5ffaa','a76bd70c-5576-5730-b5be-c9e9a76d9ac0','mistake',3,'Cutting the range short','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('aba6d2e5-e934-5d20-823d-3909ce7e2a65','f1f01978-4686-5621-8728-ba972dc4e233','step',1,'Connect a standard handle to a tower, and move the cable to the highest pulley position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f67d7475-b394-597e-9741-d07106908348','f1f01978-4686-5621-8728-ba972dc4e233','step',2,'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('72586b2e-a210-5a73-9d35-3dee602889d7','f1f01978-4686-5621-8728-ba972dc4e233','step',3,'In one motion, pull the handle down and across your body to your front knee while rotating your torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44feaf32-db9a-5e67-92bd-a538fc558ad8','f1f01978-4686-5621-8728-ba972dc4e233','step',4,'Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('44a6f240-5024-557f-ab34-02ff892fef32','f1f01978-4686-5621-8728-ba972dc4e233','step',5,'Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner. Repeat to failure.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7c981d60-9db9-5cc7-a4f3-3dd8eebb952f','f1f01978-4686-5621-8728-ba972dc4e233','step',6,'Then, reposition and repeat the same series of movements on the opposite side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac1f4018-3eb7-57ab-bd6d-ed4b4a0fac23','f1f01978-4686-5621-8728-ba972dc4e233','cue',1,'Rotate from the torso with hips stable','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('82ab4df3-791a-500c-86b5-ecf7c56c82cd','f1f01978-4686-5621-8728-ba972dc4e233','cue',2,'Move with control','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6a5dc6d0-b5be-5d89-9a75-af6f84139559','f1f01978-4686-5621-8728-ba972dc4e233','cue',3,'Keep the core braced','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0a7b56ae-d09a-5f37-8e82-4637f1aa5c23','f1f01978-4686-5621-8728-ba972dc4e233','mistake',1,'Jerking or using momentum','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d12336f6-8a9e-5876-86cf-1762ae9d550a','f1f01978-4686-5621-8728-ba972dc4e233','mistake',2,'Twisting through the lower back only','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8088e356-b6d5-5c88-8510-56ef947c9eb0','f1f01978-4686-5621-8728-ba972dc4e233','mistake',3,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9995a795-bbbe-5c58-8abb-74cbe64f5afd','f6854338-0345-5d93-8fae-6986eb662d95','step',1,'Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1cb7eae2-d8a8-5534-b92d-646babb8df04','f6854338-0345-5d93-8fae-6986eb662d95','step',2,'With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4609f0a-a3e2-5cfe-b661-3e33dcf22515','f6854338-0345-5d93-8fae-6986eb662d95','step',3,'As you inhale, go back to the starting position by slowly lowering the heels.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('882fbe6e-5b2d-5ddc-a765-86f314d5f7e4','f6854338-0345-5d93-8fae-6986eb662d95','step',4,'Repeat for the recommended amount of times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2bdfa9f2-fdfa-592d-98cc-e4037708c3aa','f6854338-0345-5d93-8fae-6986eb662d95','cue',1,'Rise as high as possible onto the balls of the feet','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7181b376-31d7-514a-bb69-805b0faa8641','f6854338-0345-5d93-8fae-6986eb662d95','cue',2,'Pause at the top','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9107b735-89e5-5750-9d16-7b122ef94e9e','f6854338-0345-5d93-8fae-6986eb662d95','cue',3,'Lower fully into a stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c7bb1725-7a67-59df-8d81-71067244ec0d','f6854338-0345-5d93-8fae-6986eb662d95','mistake',1,'Bouncing at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c756ce86-4e05-5f2f-972b-3055cf99b7be','f6854338-0345-5d93-8fae-6986eb662d95','mistake',2,'Bending the knees to cheat','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d77bae53-b671-5e05-b95d-713d1005a3b2','f6854338-0345-5d93-8fae-6986eb662d95','mistake',3,'Short range of motion','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('edc2d8dc-5291-5241-953f-5d2dae73051a','ec3a9d89-7dab-53cf-b81b-81d701929e20','step',1,'To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35ab7af5-4b0b-5084-a97f-572a8c5d8669','ec3a9d89-7dab-53cf-b81b-81d701929e20','step',2,'The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('95b84c8c-9c70-5b08-9111-8f0b9eddc3ad','ec3a9d89-7dab-53cf-b81b-81d701929e20','step',3,'Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f1c16177-193a-56f0-b4ad-3fa127201e7a','ec3a9d89-7dab-53cf-b81b-81d701929e20','step',4,'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.','en','source:free_exercise_db');
