INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ab906bd9-d3a8-5115-89aa-f84421b44da8','8aef6fe6-2249-56a9-9354-a91dab862f18','step',1,'Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e67f7f3b-b1bf-5071-afeb-ed62d03a29af','8aef6fe6-2249-56a9-9354-a91dab862f18','step',2,'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5508625b-a4fe-588a-8155-baa6a88a1eba','8aef6fe6-2249-56a9-9354-a91dab862f18','step',3,'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d9919324-7ded-5ab0-b6ef-62807e9220a5','8aef6fe6-2249-56a9-9354-a91dab862f18','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
