INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('14ccfb01-ec7e-56ea-8d3b-07fa10281a64','321ed941-7745-5651-a26f-c04482bfe437','step',1,'Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('380165e7-dda8-5773-b9a2-b3dd4243e5b8','321ed941-7745-5651-a26f-c04482bfe437','step',2,'Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8f261dc5-79b1-5b8f-b267-65338214c682','321ed941-7745-5651-a26f-c04482bfe437','step',3,'As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c3a1dec0-ce03-58af-b0ce-f3a9ea12a3c8','321ed941-7745-5651-a26f-c04482bfe437','step',4,'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
