INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('eea9faa3-586a-5c33-beb9-ab95ffc08370','e3b20b14-c15c-539b-91d2-c57eeb4c4e86','step',1,'This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3361b958-7476-57fd-b2e9-c15e59805f23','e3b20b14-c15c-539b-91d2-c57eeb4c4e86','step',2,'Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.','en','source:free_exercise_db');
