INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('edc78694-6658-5fe7-9fdb-30eeb0aa7153','68818dbc-48c8-5a53-8fbd-02832153a3c9','step',1,'To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c693eaa7-edc5-5a39-898c-9ea8f6894c5d','68818dbc-48c8-5a53-8fbd-02832153a3c9','step',2,'Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Breathe in as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0ce5f652-c508-5caa-bc04-3b3c1e55575c','68818dbc-48c8-5a53-8fbd-02832153a3c9','step',3,'Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ca67de1d-eb35-5f6b-b890-0f081106116e','68818dbc-48c8-5a53-8fbd-02832153a3c9','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
