INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f74443f2-e4c0-5b29-ab80-417941882cc2','16e64230-a2a6-54da-8edc-3df4079029c0','step',2,'To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.','en','source:free_exercise_db');
