INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('55900b9f-a634-5bc1-b77a-154196c88a1d','1cfbacf3-48bf-5710-a325-e0e0b0c3a1a8','step',1,'Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9b0c414f-fab7-5231-98d4-a6c1225ff128','1cfbacf3-48bf-5710-a325-e0e0b0c3a1a8','step',2,'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f7486f54-0d92-52d8-ba42-8a81c575fcbd','1cfbacf3-48bf-5710-a325-e0e0b0c3a1a8','step',3,'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('057f8e19-2487-5dcb-b828-6cd054116eb5','1cfbacf3-48bf-5710-a325-e0e0b0c3a1a8','cue',1,'Take a long enough step that the front shin stays near vertical','en','ai_authored:pattern');
