INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('233c98d4-8579-575d-b55d-52900dbc5370','25647e8a-9061-5f2a-81a7-a6d635a456ff','step',1,'Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e33dbdf1-d69b-50ed-a259-3adecd3c236c','25647e8a-9061-5f2a-81a7-a6d635a456ff','step',2,'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('68c34c0b-4d5c-5371-9398-6bc97de5d5be','25647e8a-9061-5f2a-81a7-a6d635a456ff','step',3,'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ca6c4bcc-905c-54ce-b19f-8769dad01cd1','25647e8a-9061-5f2a-81a7-a6d635a456ff','step',4,'Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('08f35fd2-83ab-5f94-9b83-0755203306b8','25647e8a-9061-5f2a-81a7-a6d635a456ff','step',5,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
