INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d10e223a-8a27-52a0-b461-fed2ac45e195','2ff80430-d1c9-5865-b053-9a9a22a7463f','step',4,'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.','en','source:free_exercise_db');
