INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4b6081ec-5c52-54b9-9921-dff0d5725a2d','d1c9ae7f-4176-5241-93aa-8f7312552fe5','step',2,'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fc798a9e-4057-5a73-85aa-2a559a5ac5b1','d1c9ae7f-4176-5241-93aa-8f7312552fe5','step',3,'Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0c17b660-862f-5364-b803-7268b16749db','d1c9ae7f-4176-5241-93aa-8f7312552fe5','step',4,'While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b16beb23-7027-5ea0-94c1-7c4325f4501b','d1c9ae7f-4176-5241-93aa-8f7312552fe5','step',5,'At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07cc8287-27e9-5892-8d1b-5183ec294f98','d1c9ae7f-4176-5241-93aa-8f7312552fe5','step',6,'Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('feb19735-5cb7-5c23-b041-fd8ce3e2361c','d1c9ae7f-4176-5241-93aa-8f7312552fe5','cue',1,'Keep a slight bend in the elbows','en','ai_authored:pattern');
