INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f7605f45-7848-566d-8b27-585ad92ecfd7','d1c9ae7f-4176-5241-93aa-8f7312552fe5','cue',3,'Squeeze the chest at the top','en','ai_authored:pattern');
