INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0bfb8e0a-6d3c-5fdf-b48b-c746baab1d83','d1c9ae7f-4176-5241-93aa-8f7312552fe5','mistake',3,'Using too much weight','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1797584a-cd74-5159-8383-4d6aa58cdb21','3fac3dcf-65c0-5cb6-b3af-d9f2b09edc6f','step',1,'You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6d151dc9-973b-56ba-b122-688190527509','3fac3dcf-65c0-5cb6-b3af-d9f2b09edc6f','step',2,'Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8eac79d8-b6ce-5aef-85ad-bd42421ad58b','3fac3dcf-65c0-5cb6-b3af-d9f2b09edc6f','step',3,'While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ac592ba1-5c79-52f8-b5bc-42fe3a147e30','3fac3dcf-65c0-5cb6-b3af-d9f2b09edc6f','step',4,'While keeping the arms straight, go back to the starting position while breathing in.','en','source:free_exercise_db');
