INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0aee62fd-dccb-5666-871d-2cc21303d9bc','6932a3df-8841-52cc-88e9-c6b80e0142c5','step',1,'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bfc79feb-5ba4-5d44-85c3-6b1d80711de9','6932a3df-8841-52cc-88e9-c6b80e0142c5','step',2,'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4fe51b06-402b-576b-b450-3a2cf6684093','6932a3df-8841-52cc-88e9-c6b80e0142c5','step',3,'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','en','source:free_exercise_db');
