INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ee51b459-311b-5357-b2bf-6d98452a334e','bf9cbc96-fe35-55e1-b62e-01cf327b8131','step',2,'Make sure you have good shoes.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('31546184-8049-5492-b1d0-dac102979723','bf9cbc96-fe35-55e1-b62e-01cf327b8131','step',3,'While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f19336bd-3390-5a09-9ffb-9040587491c0','bf9cbc96-fe35-55e1-b62e-01cf327b8131','step',4,'Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling.','en','source:free_exercise_db');
