INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('07d2eb2d-2775-5b6f-9eaf-6f69d65bb70e','768720ed-b901-52ba-a51e-87e96304fd9a','step',2,'Lower your hips, look forward with your head and keep your chest up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('90378994-07bb-5582-83bd-194cdd17958e','768720ed-b901-52ba-a51e-87e96304fd9a','step',3,'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('37eba0ec-2a7b-584b-8f36-d1ba1bf80140','768720ed-b901-52ba-a51e-87e96304fd9a','step',4,'At the completion of the movement, lower the weight back to the ground under control.','en','source:free_exercise_db');
