INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('78a771ba-aca5-563b-b512-2f1165b70d8c','ef8a08b3-04b5-5f7a-9305-c23e1f8fa826','step',2,'Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7aa055ae-b5e1-52ea-b6e2-8afff667e9b9','ef8a08b3-04b5-5f7a-9305-c23e1f8fa826','step',3,'To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.','en','source:free_exercise_db');
