INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2034aa22-c407-5ea0-a82d-8207996c4149','4eb52ea8-bfba-5157-a1b5-76e03f8de50f','cue',2,'Press in a straight line overhead','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6bab6155-6e1b-58c8-911c-30f3bc5665db','4eb52ea8-bfba-5157-a1b5-76e03f8de50f','cue',3,'Finish with biceps near the ears','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0c48c21a-942b-52b4-91df-afdce0994c6e','4eb52ea8-bfba-5157-a1b5-76e03f8de50f','mistake',1,'Excessive lower-back arch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('63a730a6-46e1-5a92-81a0-bea6fcf75879','4eb52ea8-bfba-5157-a1b5-76e03f8de50f','mistake',2,'Pressing forward instead of up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87a1de09-ba53-5afd-8b0b-bf5c5d1a0c3b','4eb52ea8-bfba-5157-a1b5-76e03f8de50f','mistake',3,'Flaring the ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8db35187-fd5b-5680-978d-2f488232d2a6','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','step',1,'Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8f6b1c08-e49e-5327-af0e-bb81144735ea','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','step',2,'Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('83473a87-a096-5be8-948a-3a6d0d2d9cf2','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','step',3,'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7e28fd77-0bed-5760-8cf8-e85844924232','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','step',4,'As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f04fcdc0-9dc7-5587-9197-ec4fa2b44376','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','step',5,'After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc1f2a1e-3a9e-58e7-9f0d-8904214f230e','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','step',6,'Repeat this motion for the prescribed amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8093c5f7-c977-585c-9ee6-da56ae25e1e1','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','cue',1,'Start each rep by pulling the shoulder blades down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd87b432-2693-5dfd-b1da-81cdc79443b0','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','cue',2,'Drive elbows toward your ribs','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9903289b-50a8-5008-8bb1-71cfa626c997','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','cue',3,'Control the way down to a full hang/stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('38358c76-69a5-532c-8ba3-33866ceb5970','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','mistake',1,'Kipping or swinging','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a83fdb23-1aca-5853-ba07-a28365842fc5','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','mistake',2,'Half reps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d22ccbb0-4afe-5e60-a536-2996e3c338f9','c6fb2f2a-3164-5fb1-a9e6-56203740f76d','mistake',3,'Pulling behind the neck','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a700ed00-ee76-5355-b9d8-9a1e29c550c4','1e8551c1-5d88-569b-8205-a453dd59fbbd','step',1,'Stand tall with feet about hip-width apart. Use just your bodyweight.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bd2cd750-d43c-53f0-b757-8f5ff0a5c780','1e8551c1-5d88-569b-8205-a453dd59fbbd','step',2,'Move into the position slowly.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4a73d072-eac2-50ac-8918-4f249559f23f','1e8551c1-5d88-569b-8205-a453dd59fbbd','step',3,'Breathe deeply and move or hold only within a pain-free range.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3c113f60-ba9d-5361-985b-6c79d323408a','1e8551c1-5d88-569b-8205-a453dd59fbbd','step',4,'Return to the start and repeat or switch sides.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('83f305bb-ad39-53b2-ab4d-786be77c77df','1e8551c1-5d88-569b-8205-a453dd59fbbd','step',5,'Repeat for the planned number of reps.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('561d7958-bc62-5d31-8dc3-8e8eae496589','1e8551c1-5d88-569b-8205-a453dd59fbbd','cue',1,'Breathe slowly and deeply','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('95c0fd00-fd09-5d8e-8393-52e6be585cbf','1e8551c1-5d88-569b-8205-a453dd59fbbd','cue',2,'Move into the stretch gradually','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ed2542c4-95e1-54eb-a438-c1dc626124df','1e8551c1-5d88-569b-8205-a453dd59fbbd','cue',3,'Hold or move only in a pain-free range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c0f6fafc-6bd7-5d57-8879-15c1297abe93','1e8551c1-5d88-569b-8205-a453dd59fbbd','mistake',1,'Bouncing into the stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f57a1f3a-1392-5c8f-9bc2-6f725d2fd0a7','1e8551c1-5d88-569b-8205-a453dd59fbbd','mistake',2,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('38c9c879-f460-58c2-b0ff-be083656b69d','1e8551c1-5d88-569b-8205-a453dd59fbbd','mistake',3,'Forcing range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('120b0bfd-c502-5f98-bd59-4b76c8bb2eef','f5484b3c-7da7-56e0-a681-2fee172959d8','step',1,'Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('46e77614-826d-5cb1-8b17-f6f489e3b823','f5484b3c-7da7-56e0-a681-2fee172959d8','step',2,'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Remember to keep your torso stationary and pause for a second at the top of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9e955c32-0e02-5479-a4ca-8124c4360284','f5484b3c-7da7-56e0-a681-2fee172959d8','step',3,'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('074a1b51-44f5-5323-84bf-3e3614dd5e47','f5484b3c-7da7-56e0-a681-2fee172959d8','step',4,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('863672fd-7e2b-53a4-b35d-962ac3c214a9','f5484b3c-7da7-56e0-a681-2fee172959d8','cue',1,'Lead with the elbows','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ab8fd170-8b6f-5db8-9fc3-143b3bb91d4c','f5484b3c-7da7-56e0-a681-2fee172959d8','cue',2,'Control the lowering','en','ai_authored:pattern');
