INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('45392a71-6eb6-535d-9cd9-01615052ba4e','4e8a72f6-fdb8-5dd6-b021-33bd1ff3ed3b','step',2,'Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('98303d91-aa16-5fb6-a01b-95a0ece274b6','4e8a72f6-fdb8-5dd6-b021-33bd1ff3ed3b','step',3,'Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ffea34dd-676e-5265-9e02-c83f19263656','4e8a72f6-fdb8-5dd6-b021-33bd1ff3ed3b','step',4,'Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('98c7b846-d2ad-5016-93cb-3b6d6c673314','4e8a72f6-fdb8-5dd6-b021-33bd1ff3ed3b','step',5,'After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.','en','source:free_exercise_db');
