INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('50ea5fa4-8512-5ce9-9912-2b30cba42eb1','9b1a6360-22d6-5e96-9b01-cca2e1b42960','step',1,'Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('df7aa4b3-71f5-55b3-abd0-9dc6472527b0','9b1a6360-22d6-5e96-9b01-cca2e1b42960','step',2,'Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f395992c-d725-5171-bb6a-b477ca1b6a72','9b1a6360-22d6-5e96-9b01-cca2e1b42960','step',3,'Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('182e7589-f9e6-5851-90a0-1df6a005c3e8','9b1a6360-22d6-5e96-9b01-cca2e1b42960','step',4,'After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.','en','source:free_exercise_db');
