INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25773bc2-427a-5194-99ec-ee54b38ab172','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',1,'Stand with your back against a wall, feet about 60 cm from the wall.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1e5992b5-a2b9-57a2-b87a-79ee7fdbff6f','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',2,'Slide down until knees are bent about 90 degrees.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f1532294-01b7-5d28-8f9d-436882d136cb','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',3,'Keep your back flat on the wall and hold.','en','ai_authored:specific');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a9dd581-7d16-55bc-be40-74577f796ee7','7ac0875d-59cf-59cc-9da5-27d4283e0a4b','step',4,'Stand back up to finish.','en','ai_authored:specific');
