INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cda165c5-b1b6-5e48-bd85-9dcccfda1aeb','cee72a99-7d0c-572b-933c-2baa8847511a','step',1,'Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('efbf9d4e-4c56-5f33-8417-ac24e81e3e6a','cee72a99-7d0c-572b-933c-2baa8847511a','step',2,'Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7280668e-0595-5bd8-a9ca-acaa4d2c1564','cee72a99-7d0c-572b-933c-2baa8847511a','step',3,'Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8360a938-c0ba-5b66-a3f5-45c363d96850','cee72a99-7d0c-572b-933c-2baa8847511a','step',4,'Continue alternating between legs until the set is complete.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e99c8e7a-da13-5cde-a783-6c97541a9241','cee72a99-7d0c-572b-933c-2baa8847511a','cue',1,'Start with a 5-minute easy warm-up','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b29a194d-4e7a-5227-bd35-4522d8e0fedc','cee72a99-7d0c-572b-933c-2baa8847511a','cue',2,'Keep a pace where you can speak in short sentences (moderate)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('94f324e9-aa74-5e61-b1bd-141d68664f5e','cee72a99-7d0c-572b-933c-2baa8847511a','cue',3,'Relax shoulders and keep good posture','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3525b01-6a4c-56ac-8ad7-a7b9d0b6ff91','cee72a99-7d0c-572b-933c-2baa8847511a','mistake',1,'Starting too fast','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('365d7323-71ce-5202-996f-9b24a2f3758b','cee72a99-7d0c-572b-933c-2baa8847511a','mistake',2,'Holding the handrails (machines)','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc6ba6ab-b10b-5059-9182-0fd96fd92304','cee72a99-7d0c-572b-933c-2baa8847511a','mistake',3,'Skipping the cool-down','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d515d192-5a09-5473-a7c7-d35c4fb2edbf','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','step',1,'This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e10277c4-8b21-5e84-ba9a-2115426919bd','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','step',2,'Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8e299747-74af-5605-86d6-e40571ecc3cb','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','step',3,'After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c3847538-9680-5522-83a3-096d8ceb9c8e','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','cue',1,'Breathe slowly and deeply','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('54bddf42-c456-5f58-abbd-ddf05dab565f','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','cue',2,'Move into the stretch gradually','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('af45f6e3-45da-5b1e-9811-3ad4f26b6d86','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','cue',3,'Hold or move only in a pain-free range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('110fa014-de85-5395-aca6-d310e44bef24','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','mistake',1,'Bouncing into the stretch','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e76f5c44-de03-5f8f-86e9-32d650120065','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','mistake',2,'Holding the breath','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('90bb948d-0ac2-5083-a414-091fc8855454','60b23cc2-9ca7-52a4-8655-9ccb69098ccd','mistake',3,'Forcing range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a8208149-eb95-5d17-b9e2-05f5b93a7b00','ca2866bc-03bd-5488-b364-d520be21090c','step',1,'To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('833356b2-0638-564d-82fb-87d8547ee9e7','ca2866bc-03bd-5488-b364-d520be21090c','step',2,'Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Your entire body should be stationary except for the forearms. This is the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4ca5321e-5806-5b18-87e8-0925524f5113','ca2866bc-03bd-5488-b364-d520be21090c','step',3,'Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c8ab1ac7-989d-5aa5-a3e7-cd52c4fcdfb1','ca2866bc-03bd-5488-b364-d520be21090c','step',4,'Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a37a87d5-814f-5a72-9b07-bf3b271de2bb','ca2866bc-03bd-5488-b364-d520be21090c','step',5,'Repeat for the prescribed amount of repetitions in your program.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3a3389cd-20cd-56bd-918f-0b5872d0c15e','ca2866bc-03bd-5488-b364-d520be21090c','cue',1,'Move only at the wrist/fingers','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('73fa975e-aa6f-5612-9bdf-6a8dd21961d0','ca2866bc-03bd-5488-b364-d520be21090c','cue',2,'Use full range','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7d1613c1-1133-5e0e-8b78-38eba648e81d','ca2866bc-03bd-5488-b364-d520be21090c','cue',3,'Go slowly','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('87094033-4d75-5a18-979e-a64cfcd523c7','ca2866bc-03bd-5488-b364-d520be21090c','mistake',1,'Using the whole arm','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('46dc1237-87dd-506c-bb36-95fb6f159458','ca2866bc-03bd-5488-b364-d520be21090c','mistake',2,'Too heavy a load','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('971e40bf-ef16-5a38-94c8-a43ea42a8cfe','ca2866bc-03bd-5488-b364-d520be21090c','mistake',3,'Jerky reps','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d474b419-9d68-531b-b16c-8bf083e4a676','518b18d1-5a94-52a5-8188-5900732b5426','step',1,'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3bb21076-3d25-558f-8f62-92f19e01f912','518b18d1-5a94-52a5-8188-5900732b5426','step',2,'Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('302ebf0a-a2e5-5531-ba30-f34dfcf09d6d','518b18d1-5a94-52a5-8188-5900732b5426','step',3,'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0922ba5b-fa51-5adf-a2f8-da662d4beda5','518b18d1-5a94-52a5-8188-5900732b5426','step',4,'Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('638a8b53-2945-5144-b9d9-eb58bcd8a137','518b18d1-5a94-52a5-8188-5900732b5426','step',5,'Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('08da7bdd-69bd-55fd-989f-aca6632d5532','518b18d1-5a94-52a5-8188-5900732b5426','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d2fa5097-5051-54f0-9fd3-194a17137ad5','518b18d1-5a94-52a5-8188-5900732b5426','cue',1,'Brace your core before you descend','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('21af5485-181a-5873-8f96-f8b84c762ceb','518b18d1-5a94-52a5-8188-5900732b5426','cue',2,'Knees track over your toes','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('27506e1b-27a6-50b0-a36b-93814c2f504f','518b18d1-5a94-52a5-8188-5900732b5426','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('52725ddb-47c0-5b82-9c83-e81fe416d0af','518b18d1-5a94-52a5-8188-5900732b5426','mistake',1,'Knees caving inward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1d0363b5-3be3-59e5-afc8-1f647cb31fd1','518b18d1-5a94-52a5-8188-5900732b5426','mistake',2,'Heels lifting off the floor','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('6194009f-16b8-5da9-958f-e5c3f9f7a1cc','518b18d1-5a94-52a5-8188-5900732b5426','mistake',3,'Rounding the lower back at the bottom','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('095d0c21-1fa0-52a1-ac30-92f3afc14ad6','78a46bd5-5072-5e37-83a8-8754c175fbef','step',1,'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('758d5a04-6aef-5f1a-b429-cdb47b495c40','78a46bd5-5072-5e37-83a8-8754c175fbef','step',2,'Make sure the palms of the hands are facing each other. This will be your starting position. While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f48a8152-da39-5da0-8b1f-17f864aebd48','78a46bd5-5072-5e37-83a8-8754c175fbef','step',3,'Hold the contracted position for a second as you squeeze the biceps.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('389eb6c9-3088-5944-8661-8609b63a267d','78a46bd5-5072-5e37-83a8-8754c175fbef','step',4,'Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f99b5cc7-ee3f-5f0a-87a2-076d0cd18213','78a46bd5-5072-5e37-83a8-8754c175fbef','step',5,'Slowly begin to bring the dumbbells back down using the pronated grip. As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('dffad895-5777-5828-afd9-2bcbda5dae4c','78a46bd5-5072-5e37-83a8-8754c175fbef','step',6,'Repeat for the recommended amount of repetitions.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cf6af575-a6c9-51eb-91d7-6fbda7286611','78a46bd5-5072-5e37-83a8-8754c175fbef','cue',1,'Keep elbows pinned at your sides','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d9468db7-34fc-5330-9456-de48b0fcc1fe','78a46bd5-5072-5e37-83a8-8754c175fbef','cue',2,'Squeeze at the top','en','ai_authored:pattern');
