INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1d486f35-4278-52b2-b8a3-0ce743316068','78a46bd5-5072-5e37-83a8-8754c175fbef','mistake',2,'Elbows drifting forward','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0b13f008-1c5d-5fff-b2a3-d8ebc8b85ef1','78a46bd5-5072-5e37-83a8-8754c175fbef','mistake',3,'Cutting the range short','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('06330f89-8284-59bf-aac3-5898b29dd0ce','54c462e2-c926-57dd-9eb9-a68d5834c3cd','step',1,'Lie on your back with your head, upper back and hips supported and feet planted. Use a barbell.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('493370a4-80fd-5188-9edd-e73a69a50c87','54c462e2-c926-57dd-9eb9-a68d5834c3cd','step',2,'Set your shoulder blades back and down and brace your core.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('955a56cf-bc72-524b-a36c-709ba8db28e6','54c462e2-c926-57dd-9eb9-a68d5834c3cd','step',3,'Lower the weight or your body under control until your chest is close to the hands or the bar.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('68b3994d-c1ec-5bba-94f2-cc47aebceefb','54c462e2-c926-57dd-9eb9-a68d5834c3cd','step',4,'Press back up to straight arms, keeping your wrists stacked over your elbows.','en','ai_authored:pattern');
