INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('bb1f4e30-6a77-59ae-81a2-57f5c1cfdc1f','54c462e2-c926-57dd-9eb9-a68d5834c3cd','cue',2,'Wrists stacked over elbows','en','ai_derived:pattern');
