INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d852698d-9fa7-5466-b90f-970decdbc408','ea69597b-282b-54a7-834d-f4aed8fa41b0','step',3,'Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.','en','source:free_exercise_db');
