INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2d0a887b-c9bf-54ec-af2e-66091120e90d','2820dc4e-f440-58d2-8983-fd5953742798','step',2,'Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.','en','source:free_exercise_db');
