INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7e762888-029f-598e-90ad-eb448bc87bed','2820dc4e-f440-58d2-8983-fd5953742798','step',4,'As you exhale flatten your lower back to the floor while curling the torso upwards. Hold at the top position for a second.','en','source:free_exercise_db');
