INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9b071b7e-b7d2-5e48-8b4e-285999302db6','8b2844d0-fc34-574c-aab3-e6b745b5247b','step',1,'Connect a standard handle to a tower, and position the cable to shoulder height. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3ca34cff-a9fb-562b-9344-6a77e5bc6aea','8b2844d0-fc34-574c-aab3-e6b745b5247b','step',2,'With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1fbec20a-db14-5315-b53c-cf3e4190b3c6','8b2844d0-fc34-574c-aab3-e6b745b5247b','step',3,'Facing forward, press the cable away from your chest. You core should be tight and engaged.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('073d0331-fe0f-51e9-87ec-cde367d51685','8b2844d0-fc34-574c-aab3-e6b745b5247b','step',4,'Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation. Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('70faa82b-005a-5939-a8ba-a996f2adcb52','8b2844d0-fc34-574c-aab3-e6b745b5247b','step',5,'With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep. Repeat to failure.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f59c30d9-2eae-5622-86d5-465a96a64666','8b2844d0-fc34-574c-aab3-e6b745b5247b','step',6,'Then, reposition and repeat the same series of movements on the opposite side.','en','source:free_exercise_db');
