INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f8fe4dd7-5efa-5a08-892a-20bf3b673053','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',1,'Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f603b76a-8018-5b67-b78e-fe7a08fd3e3e','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',2,'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5cc01fae-4bdb-5503-a586-4bbbdd3feb2e','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',3,'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('29bca962-7d2f-5b57-acf9-a5fc9d91ddc7','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','step',4,'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f9aed70b-7b00-55cf-90b3-15a09e31ac4d','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','cue',1,'Brace your core before you descend','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5ea83813-4e7b-5590-aba1-e422b743973f','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','cue',2,'Knees track over your toes','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f056001b-1e4b-5626-8568-6f3ac3df9c54','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4bc05d59-998b-54b9-ba35-03fe1cc2c6b7','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','mistake',1,'Knees caving inward','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ccbbc42a-2699-5570-88cf-fc039926d0fb','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','mistake',2,'Heels lifting off the floor','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7a85cc00-eccb-5fd0-8a74-c578fee1b4a0','4fef6c0c-45e9-5f22-8f6e-124a79191a5c','mistake',3,'Rounding the lower back at the bottom','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8de5d228-92b9-5565-9fbf-77f6424c7c73','a0534253-45ad-5077-9a29-d8d38ddcce97','step',1,'Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1da39ea4-936b-549f-ba06-c3a2b7fa150c','a0534253-45ad-5077-9a29-d8d38ddcce97','step',2,'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d269ee6d-c644-5312-be60-a4ddde72204d','a0534253-45ad-5077-9a29-d8d38ddcce97','step',3,'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('c24f0fc8-c1d9-5c51-9ca6-4d65d90e9dca','a0534253-45ad-5077-9a29-d8d38ddcce97','step',4,'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d03bef54-973a-5d08-9423-480edff719bf','a0534253-45ad-5077-9a29-d8d38ddcce97','step',5,'Lower the bar by bending at the hips and guiding it to the floor.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('95fec1c1-a138-535c-a8c9-2a04b702b383','a0534253-45ad-5077-9a29-d8d38ddcce97','cue',1,'Push your hips back, not down','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e799e0fa-d57e-5da3-a72c-991d9eaf923e','a0534253-45ad-5077-9a29-d8d38ddcce97','cue',2,'Keep the weight close to your legs','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2f5d9097-6ae3-5d3f-8c66-f5787d9ffa1b','a0534253-45ad-5077-9a29-d8d38ddcce97','cue',3,'Neutral spine from head to hips','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('49671ebe-4f8c-5e8b-b04f-24e6005af198','a0534253-45ad-5077-9a29-d8d38ddcce97','mistake',1,'Rounding the back','en','ai_derived:pattern');
