INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5a87b766-b39d-572f-9f2c-1436915b2c16','43993c78-dac5-5293-bdc0-867c1567a969','step',1,'Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('25013c9c-5b24-5abf-a9f2-cb135f909caf','43993c78-dac5-5293-bdc0-867c1567a969','step',2,'Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('962c82fc-f34e-5430-9b5b-0051a9fb5a7c','43993c78-dac5-5293-bdc0-867c1567a969','step',3,'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e5a286ab-73f8-5db4-8dd2-0c5f2e12190f','43993c78-dac5-5293-bdc0-867c1567a969','step',4,'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('29abdf45-752d-5064-837c-b9ea8a32a234','43993c78-dac5-5293-bdc0-867c1567a969','step',5,'Return the weight to the ground by bending at the hips and controlling the weight on the way down.','en','source:free_exercise_db');
