INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('9c39543e-49cb-5bf5-b8b5-920ecfc034b7','dc5d1649-a02b-5c74-85b3-2b8d05b0e426','step',1,'Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('4c2bfcb8-fe71-5013-9414-ab4fe18ca3a2','dc5d1649-a02b-5c74-85b3-2b8d05b0e426','step',2,'Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('05145550-08b1-5938-b8fd-4a38614bc8eb','dc5d1649-a02b-5c74-85b3-2b8d05b0e426','step',3,'Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a276d133-97bd-5e8a-8621-41f1840967e1','dc5d1649-a02b-5c74-85b3-2b8d05b0e426','step',4,'Pause just above the pins and reverse the motion until your torso it upright.','en','source:free_exercise_db');
