INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a4380521-ede8-5d70-88e5-ae528f281b80','83071d6e-5d91-5e76-988e-6c61e3e9f479','mistake',2,'Bouncing off the chest','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('b4bc422e-6e20-5448-a49b-61461131a7b2','83071d6e-5d91-5e76-988e-6c61e3e9f479','mistake',3,'Lifting hips off the bench','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8dfe1aa5-153c-53be-b1bd-95a2dd229557','55b83608-b2e6-57f6-a02d-b245024e179d','step',1,'Stand tall with feet about hip-width apart; adjust the seat and pads so your joints line up with the machine''s pivot. Use a Smith machine.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('3b136ac4-a101-5809-9448-3822a747f49a','55b83608-b2e6-57f6-a02d-b245024e179d','step',2,'Brace your core and sit your hips down and back, keeping your chest proud and knees tracking over your toes.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('109050a4-525d-5160-a060-6964e11e149f','55b83608-b2e6-57f6-a02d-b245024e179d','step',3,'Descend to a depth you can control (around thigh-parallel or lower if your mobility allows).','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('cc0ba036-c077-5b48-97e6-c1734902c6df','55b83608-b2e6-57f6-a02d-b245024e179d','step',4,'Drive through the whole foot to stand back up, squeezing your glutes at the top.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8182ca2b-d648-59d4-b23a-7de3cbf0be8a','55b83608-b2e6-57f6-a02d-b245024e179d','step',5,'Repeat for the planned number of reps.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('928a86af-36cb-5d38-9def-ee32c1277934','55b83608-b2e6-57f6-a02d-b245024e179d','cue',1,'Brace your core before you descend','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('059d7afc-d5df-5207-b9e8-e3aaa6f47843','55b83608-b2e6-57f6-a02d-b245024e179d','cue',2,'Knees track over your toes','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('ff877e8d-c0e0-5670-b490-7b5192450548','55b83608-b2e6-57f6-a02d-b245024e179d','cue',3,'Keep the whole foot planted; drive up through mid-foot','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('fd0ed282-b8b9-57f1-9b11-8a4a95355a23','55b83608-b2e6-57f6-a02d-b245024e179d','mistake',1,'Knees caving inward','en','ai_derived:pattern');
