INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1e14f6d7-ee0f-53f7-b1d2-06dc4de68513','fe218c1f-7d28-545d-8f67-31f57a03eccc','step',1,'Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('67dda83d-f63e-51e6-a4a7-fede63020d0b','fe218c1f-7d28-545d-8f67-31f57a03eccc','step',2,'Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('7732faa1-7b84-5e29-8169-80625e65b9a4','fe218c1f-7d28-545d-8f67-31f57a03eccc','step',3,'Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.','en','source:free_exercise_db');
