INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8ddd798d-3b39-5f2a-af8f-e39e1b926c4c','5b1b8587-8286-58a4-82e1-c8a746cdeddb','step',1,'With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('35e9b350-1cd6-5ba2-816a-26b8ad46d081','5b1b8587-8286-58a4-82e1-c8a746cdeddb','step',2,'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d82f4992-09c4-597d-b3e1-f54c49d57921','5b1b8587-8286-58a4-82e1-c8a746cdeddb','step',3,'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('23e7c84e-87ef-51e8-9a33-ed9f9e1eff1c','5b1b8587-8286-58a4-82e1-c8a746cdeddb','step',4,'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('de934d7d-d872-5407-82ef-0f13ac4f8e5d','5b1b8587-8286-58a4-82e1-c8a746cdeddb','step',5,'Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('f5877a3a-ae05-5a00-a677-d7760a456f68','5b1b8587-8286-58a4-82e1-c8a746cdeddb','step',6,'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('e1c1520e-0a7f-5280-bc98-9498f89cb659','5b1b8587-8286-58a4-82e1-c8a746cdeddb','cue',1,'Drive explosively with the legs/hips','en','ai_derived:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('1efa71cc-64eb-5763-b609-f129f62f512c','5b1b8587-8286-58a4-82e1-c8a746cdeddb','cue',2,'Keep the load close','en','ai_derived:pattern');
