INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('5a7c3479-80f8-5b07-b71c-5ea49829b69c','dbf67fc7-5c68-5aa6-a137-94e9c99dfc34','step',1,'Stand tall with feet about hip-width apart; anchor the band securely or stand on it. Use a resistance band.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('060dbb6b-3b05-5ad5-be15-18e5515a4adf','dbf67fc7-5c68-5aa6-a137-94e9c99dfc34','step',2,'Step or position one foot forward so you can lower the back knee toward the floor.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('027ee229-e040-5bbe-b150-ce67c2eb40a1','dbf67fc7-5c68-5aa6-a137-94e9c99dfc34','step',3,'Lower under control until both knees are bent to roughly 90 degrees, front shin close to vertical.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2105045b-8471-5109-911d-2ed9844e463a','dbf67fc7-5c68-5aa6-a137-94e9c99dfc34','step',4,'Push through the front heel to return to the start position.','en','ai_authored:pattern');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('170e0d55-170d-5a89-9159-ee9d0c3207ba','dbf67fc7-5c68-5aa6-a137-94e9c99dfc34','step',5,'Complete all reps on one side, then switch sides.','en','ai_authored:pattern');
