INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0afd2b9d-96c7-5392-b30e-25787cccdd26','1b1a3e5e-240a-5494-b37f-7bc8bc3fc215','step',1,'To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. The dumbbell should be above your head.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('0295e201-23cb-50fa-83bf-d00264a21778','1b1a3e5e-240a-5494-b37f-7bc8bc3fc215','step',2,'This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('faa215a1-a435-501d-83f1-4409f42dbdee','1b1a3e5e-240a-5494-b37f-7bc8bc3fc215','step',3,'Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Breathe in as you perform this step.','en','source:free_exercise_db');
