INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('038a6beb-774d-5275-b755-817a48c03131','3e445d6c-c03e-510f-909d-abc1042a63ad','step',4,'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.','en','source:free_exercise_db');
