INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('180ea1ae-8cc1-564a-8ccb-27df7772de80','52a6ce34-f931-5838-88d7-6c90fd8075b9','step',2,'The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('d91cf0a9-23b8-5e6d-b3cb-65d55b71cbd1','52a6ce34-f931-5838-88d7-6c90fd8075b9','step',3,'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Forearms should always be pointing down.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('8173ee26-6aa4-5025-ab31-74edcdfe4747','52a6ce34-f931-5838-88d7-6c90fd8075b9','step',4,'Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.','en','source:free_exercise_db');
