INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a3c44790-3bd4-55b6-aeb3-33aadfc21bff','7e8f6419-d7d4-5a8f-aae1-e4cdf7cb8ce3','step',1,'Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('2c4c3c2c-87cb-5a82-bacb-b450ad3fcd9e','7e8f6419-d7d4-5a8f-aae1-e4cdf7cb8ce3','step',2,'As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('a2324381-3b78-5489-9087-cd4d101ed27b','7e8f6419-d7d4-5a8f-aae1-e4cdf7cb8ce3','step',3,'Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('368ba172-6a39-5e51-9e61-a453cbdabe7b','7e8f6419-d7d4-5a8f-aae1-e4cdf7cb8ce3','step',4,'As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.','en','source:free_exercise_db');
INSERT OR REPLACE INTO `exercise_library_instructions` (`id`,`exercise_library_item_id`,`kind`,`position`,`text`,`lang`,`provenance`) VALUES ('17d6da32-b146-5aaf-a8b0-44df7f82ce3a','7e8f6419-d7d4-5a8f-aae1-e4cdf7cb8ce3','step',5,'Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.','en','source:free_exercise_db');
